package com.gokirlbankedxp.service;

import static org.junit.jupiter.api.Assertions.assertEquals;

import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

/** Covers the learned XP-drop rate that drives the "about to run out" warning. */
class DepletionForecasterTest
{
    @Test
    void forecastIsTheSumOfTheLastDropsOnceTheWindowIsFull()
    {
        DepletionForecaster forecaster = new DepletionForecaster();

        // A steady skill: five identical drops, as woodcutting or fishing gives.
        for (int i = 0; i < 5; i++)
        {
            forecaster.recordDrop(Skill.WOODCUTTING, 100L, 5);
        }

        assertEquals(500L, forecaster.forecast(Skill.WOODCUTTING, 5));
        assertEquals(100L, forecaster.averageDrop(Skill.WOODCUTTING));
    }

    @Test
    void onlyTheMostRecentDropsCount()
    {
        DepletionForecaster forecaster = new DepletionForecaster();

        // Old, cheap drops must fall out of the window when the player switches
        // to something more expensive, or the warning would fire far too late.
        for (int i = 0; i < 5; i++)
        {
            forecaster.recordDrop(Skill.WOODCUTTING, 25L, 3);
        }
        for (int i = 0; i < 3; i++)
        {
            forecaster.recordDrop(Skill.WOODCUTTING, 175L, 3);
        }

        assertEquals(3, forecaster.sampleCount(Skill.WOODCUTTING));
        assertEquals(525L, forecaster.forecast(Skill.WOODCUTTING, 3));
    }

    @Test
    void aPartialWindowScalesTheAverageInsteadOfUnderReporting()
    {
        DepletionForecaster forecaster = new DepletionForecaster();

        // Only two of the five samples exist yet. Summing them would predict 200
        // and warn far too late; scaling the mean predicts a full five actions.
        forecaster.recordDrop(Skill.AGILITY, 100L, 5);
        forecaster.recordDrop(Skill.AGILITY, 100L, 5);

        assertEquals(500L, forecaster.forecast(Skill.AGILITY, 5));
    }

    @Test
    void variableDropsAveragedRatherThanTakenFromTheLastOne()
    {
        DepletionForecaster forecaster = new DepletionForecaster();

        // Combat: every hit is worth a different amount, so a single sample would
        // swing the prediction wildly. The mean smooths that out.
        forecaster.recordDrop(Skill.ATTACK, 40L, 4);
        forecaster.recordDrop(Skill.ATTACK, 120L, 4);
        forecaster.recordDrop(Skill.ATTACK, 60L, 4);
        forecaster.recordDrop(Skill.ATTACK, 100L, 4);

        assertEquals(80L, forecaster.averageDrop(Skill.ATTACK));
        assertEquals(320L, forecaster.forecast(Skill.ATTACK, 4));
    }

    @Test
    void skillsDoNotContaminateEachOther()
    {
        DepletionForecaster forecaster = new DepletionForecaster();

        forecaster.recordDrop(Skill.MINING, 60L, 5);
        forecaster.recordDrop(Skill.COOKING, 300L, 5);

        assertEquals(60L, forecaster.averageDrop(Skill.MINING));
        assertEquals(300L, forecaster.averageDrop(Skill.COOKING));
    }

    @Test
    void unknownOrEmptySkillsPredictNothing()
    {
        DepletionForecaster forecaster = new DepletionForecaster();

        // Zero means "no prediction available", which the plugin reads as
        // "do not warn" rather than as "nothing will be consumed".
        assertEquals(0L, forecaster.forecast(Skill.SLAYER, 5));
        assertEquals(0L, forecaster.averageDrop(Skill.SLAYER));
        assertEquals(0, forecaster.sampleCount(Skill.SLAYER));
        assertEquals(0L, forecaster.forecast(null, 5));
    }

    @Test
    void aDisabledWindowRecordsNothingAndPredictsNothing()
    {
        DepletionForecaster forecaster = new DepletionForecaster();

        forecaster.recordDrop(Skill.FISHING, 90L, 0);

        assertEquals(0, forecaster.sampleCount(Skill.FISHING));
        assertEquals(0L, forecaster.forecast(Skill.FISHING, 0));
    }

    @Test
    void nonPositiveDropsAreIgnored()
    {
        DepletionForecaster forecaster = new DepletionForecaster();

        forecaster.recordDrop(Skill.FIREMAKING, 0L, 5);
        forecaster.recordDrop(Skill.FIREMAKING, -50L, 5);

        assertEquals(0, forecaster.sampleCount(Skill.FIREMAKING));
    }

    @Test
    void clearForgetsEveryLearnedRate()
    {
        DepletionForecaster forecaster = new DepletionForecaster();
        forecaster.recordDrop(Skill.HUNTER, 200L, 5);

        forecaster.clear();

        assertEquals(0, forecaster.sampleCount(Skill.HUNTER));
        assertEquals(0L, forecaster.forecast(Skill.HUNTER, 5));
    }
}

package com.gokirlbankedxp.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.gokirlbankedxp.model.XpMultiplierTier;
import java.util.List;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

/**
 * Covers the level multiplier rule itself: which threshold applies, what it does
 * to a deposit, and what survives a save and reload.
 *
 * <p>The single most important case here is that thresholds do not stack.
 * Reaching a higher one replaces the lower one outright rather than compounding
 * with it, which is the behaviour the feature was specified with and the one a
 * reader is most likely to "fix" into a bug.</p>
 */
class XpMultiplierManagerTest
{
    @Test
    void aSkillWithNoThresholdsBanksXpUnchanged()
    {
        TestMultipliers fixture = new TestMultipliers().atLevel(Skill.COOKING, 92);

        assertEquals(1.0, fixture.multiplierManager.currentMultiplier(Skill.COOKING));
        assertEquals(500L, fixture.multiplierManager.applyTo(Skill.COOKING, 500L));
    }

    @Test
    void theHighestReachedThresholdApplies()
    {
        TestMultipliers fixture = new TestMultipliers()
            .withTier(Skill.WOODCUTTING, 50, 1.5)
            .withTier(Skill.WOODCUTTING, 70, 2.0)
            .withTier(Skill.WOODCUTTING, 90, 3.0);

        assertEquals(1.0, fixture.multiplierManager.multiplierFor(Skill.WOODCUTTING, 49));
        assertEquals(1.5, fixture.multiplierManager.multiplierFor(Skill.WOODCUTTING, 50));
        assertEquals(1.5, fixture.multiplierManager.multiplierFor(Skill.WOODCUTTING, 69));
        assertEquals(2.0, fixture.multiplierManager.multiplierFor(Skill.WOODCUTTING, 70));
        assertEquals(3.0, fixture.multiplierManager.multiplierFor(Skill.WOODCUTTING, 90));
        assertEquals(3.0, fixture.multiplierManager.multiplierFor(Skill.WOODCUTTING, 126));
    }

    /**
     * The non-stacking guarantee, stated as arithmetic.
     *
     * <p>A ladder of 1.5x, 2x and 3x would compound to 9x if the tiers were
     * multiplied together. At level 90 the answer must be exactly 3x.</p>
     */
    @Test
    void thresholdsReplaceEachOtherRatherThanCompounding()
    {
        TestMultipliers fixture = new TestMultipliers()
            .withTier(Skill.MINING, 50, 1.5)
            .withTier(Skill.MINING, 70, 2.0)
            .withTier(Skill.MINING, 90, 3.0)
            .atLevel(Skill.MINING, 90);

        assertEquals(3.0, fixture.multiplierManager.currentMultiplier(Skill.MINING));
        assertEquals(3_000L, fixture.multiplierManager.applyTo(Skill.MINING, 1_000L));
    }

    @Test
    void aZeroMultiplierBanksNothing()
    {
        TestMultipliers fixture = new TestMultipliers()
            .withTier(Skill.SLAYER, 99, 0.0)
            .atLevel(Skill.SLAYER, 99);

        assertEquals(0L, fixture.multiplierManager.applyTo(Skill.SLAYER, 10_000L));
    }

    /**
     * A fractional multiplier is a penalty, not a delete. Rounding a real deposit
     * away to nothing would read as the plugin having lost it, so any positive
     * multiplier banks at least 1 XP.
     */
    @Test
    void aFractionalMultiplierReducesADepositWithoutErasingIt()
    {
        TestMultipliers fixture = new TestMultipliers()
            .withTier(Skill.FISHING, 1, 0.5)
            .atLevel(Skill.FISHING, 40);

        assertEquals(500L, fixture.multiplierManager.applyTo(Skill.FISHING, 1_000L));
        assertEquals(1L, fixture.multiplierManager.applyTo(Skill.FISHING, 1L));
        assertEquals(1L, XpMultiplierManager.scale(1L, 0.001));
        assertEquals(0L, XpMultiplierManager.scale(1_000L, 0.0));
    }

    @Test
    void skillsHaveEntirelySeparateLadders()
    {
        TestMultipliers fixture = new TestMultipliers()
            .withTier(Skill.COOKING, 50, 2.0)
            .atLevel(Skill.COOKING, 60)
            .atLevel(Skill.FIREMAKING, 99);

        assertEquals(2.0, fixture.multiplierManager.currentMultiplier(Skill.COOKING));
        assertEquals(1.0, fixture.multiplierManager.currentMultiplier(Skill.FIREMAKING));
    }

    @Test
    void thresholdsAreSortedAndDeduplicatedOnSave()
    {
        TestMultipliers fixture = new TestMultipliers();
        fixture.multiplierManager.setTiers(Skill.MAGIC, List.of(
            new XpMultiplierTier(90, 3.0),
            new XpMultiplierTier(50, 1.5),
            // Same level twice: the later entry is the one the editor filled in
            // most recently, so it is the one that survives.
            new XpMultiplierTier(50, 2.5)));

        List<XpMultiplierTier> stored = fixture.multiplierManager.getTiers(Skill.MAGIC);
        assertEquals(2, stored.size());
        assertEquals(50, stored.get(0).getLevel());
        assertEquals(2.5, stored.get(0).getMultiplier());
        assertEquals(90, stored.get(1).getLevel());
    }

    @Test
    void thresholdsSurviveASaveAndReload()
    {
        TestMultipliers fixture = new TestMultipliers()
            .withTier(Skill.HERBLORE, 70, 2.25)
            .withTier(Skill.HERBLORE, 99, 4.0);

        XpMultiplierManager reloaded = new XpMultiplierManager(
            fixture.configManager, fixture.config, fixture.levelTracker, new com.google.gson.Gson());
        reloaded.load();

        assertEquals(2, reloaded.getTiers(Skill.HERBLORE).size());
        assertEquals(2.25, reloaded.multiplierFor(Skill.HERBLORE, 70));
        assertEquals(4.0, reloaded.multiplierFor(Skill.HERBLORE, 99));
    }

    /**
     * Config can be hand-edited, and a skill removed from a future client would
     * leave an entry that no longer parses. Neither may take the whole file down
     * with it, since that would silently wipe every other skill's ladder.
     */
    @Test
    void unusableSavedDataIsRepairedRatherThanDiscardingEverything()
    {
        TestMultipliers fixture = new TestMultipliers();
        fixture.storedValues().put("gokirlbankedxp.xpMultipliersJson",
            "{\"COOKING\":[{\"level\":999,\"multiplier\":-4.0},{\"level\":70,\"multiplier\":2.0}],"
                + "\"NOT_A_SKILL\":[{\"level\":50,\"multiplier\":2.0}]}");

        XpMultiplierManager reloaded = new XpMultiplierManager(
            fixture.configManager, fixture.config, fixture.levelTracker, new com.google.gson.Gson());
        reloaded.load();

        List<XpMultiplierTier> cooking = reloaded.getTiers(Skill.COOKING);
        assertEquals(2, cooking.size());
        assertEquals(70, cooking.get(0).getLevel());
        // Level clamped to the virtual ceiling, multiplier clamped up to zero.
        assertEquals(XpMultiplierTier.MAX_LEVEL, cooking.get(1).getLevel());
        assertEquals(0.0, cooking.get(1).getMultiplier());
    }

    @Test
    void virtualLevelsPastNinetyNineStillTriggerThresholds()
    {
        TestMultipliers fixture = new TestMultipliers()
            .withTier(Skill.THIEVING, 120, 5.0)
            .atLevel(Skill.THIEVING, 120);

        assertEquals(5.0, fixture.multiplierManager.currentMultiplier(Skill.THIEVING));
    }

    /**
     * Switching the feature off must not destroy anything. The ladder stays
     * exactly where it was so it comes back intact when the switch goes on again.
     */
    @Test
    void theMasterSwitchSuspendsMultipliersWithoutDeletingThem()
    {
        TestMultipliers fixture = new TestMultipliers(false)
            .withTier(Skill.RUNECRAFT, 50, 3.0)
            .atLevel(Skill.RUNECRAFT, 77);

        assertFalse(fixture.multiplierManager.isEnabled());
        assertEquals(1.0, fixture.multiplierManager.currentMultiplier(Skill.RUNECRAFT));
        assertEquals(500L, fixture.multiplierManager.applyTo(Skill.RUNECRAFT, 500L));

        // The ladder is untouched: the rule still resolves, it is just not used.
        assertEquals(3.0, fixture.multiplierManager.multiplierFor(Skill.RUNECRAFT, 77));
        assertEquals(1, fixture.multiplierManager.getTiers(Skill.RUNECRAFT).size());
    }

    @Test
    void clearingASkillReturnsItToBankingUnchanged()
    {
        TestMultipliers fixture = new TestMultipliers()
            .withTier(Skill.SMITHING, 40, 2.0)
            .atLevel(Skill.SMITHING, 60);

        fixture.multiplierManager.clearTiers(Skill.SMITHING);

        assertTrue(fixture.multiplierManager.getTiers(Skill.SMITHING).isEmpty());
        assertEquals(1.0, fixture.multiplierManager.currentMultiplier(Skill.SMITHING));
    }

    /** A huge multiplier on a huge deposit clamps instead of wrapping negative. */
    @Test
    void anEnormousResultSaturatesRatherThanOverflowing()
    {
        assertEquals(Long.MAX_VALUE, XpMultiplierManager.scale(Long.MAX_VALUE / 2, 1000.0));
    }
}

package com.gokirlbankedxp.service;

import static org.junit.jupiter.api.Assertions.assertNotNull;

import com.gokirlbankedxp.ui.IrlActionsPanel;
import com.gokirlbankedxp.ui.XpMultipliersPanel;
import javax.inject.Singleton;
import org.junit.jupiter.api.Test;

/**
 * Guards the scoping bug that made every timer refuse to start.
 *
 * <p>Guice leaves unannotated bindings unscoped, so each injection point gets a
 * fresh instance. The plugin, the timer manager and the actions panel all inject
 * {@link IrlActionManager}; without {@code @Singleton} they each held a separate,
 * empty library, and only the plugin's copy was ever loaded from config. Starting
 * a timer then failed with "that action is no longer available" for an action the
 * user could see in the list, because the timer manager was consulting a
 * different manager than the one the panel had just written to.</p>
 *
 * <p>These assertions are on the annotations rather than on a live injector: the
 * real child injector is built by RuneLite's client at runtime and is not
 * available to a unit test, but the annotation is the whole of what was missing.</p>
 */
class InjectionScopeTest
{
    @Test
    void actionLibraryIsSharedByEveryInjectionPoint()
    {
        assertNotNull(IrlActionManager.class.getAnnotation(Singleton.class),
            "IrlActionManager must be @Singleton; otherwise the panel, the plugin and TimerManager"
                + " each get their own empty action library.");
    }

    @Test
    void timerStateIsSharedByEveryInjectionPoint()
    {
        assertNotNull(TimerManager.class.getAnnotation(Singleton.class),
            "TimerManager must be @Singleton; otherwise timers started from the panel live in a"
                + " manager that never had startUp() called and so never tick.");
    }

    @Test
    void loggedXpIsBankedThroughASharedManager()
    {
        assertNotNull(ActionLogManager.class.getAnnotation(Singleton.class),
            "ActionLogManager must be @Singleton so it resolves actions from the shared library.");
    }

    /**
     * The panel is the only consumer that reaches all three services, so a
     * compile-time reference here keeps this test honest if the wiring changes.
     */
    @Test
    void actionsPanelIsTheUiEntryPointForAllThreeServices()
    {
        assertNotNull(IrlActionsPanel.class);
    }

    @Test
    void bankedXpStoreIsSharedByEveryInjectionPoint()
    {
        assertNotNull(BankedXpStore.class.getAnnotation(Singleton.class),
            "BankedXpStore must be @Singleton; it remembers the last config value it wrote so the"
                + " plugin can ignore the ConfigChanged echo of its own saves.");
    }

    @Test
    void observedLevelsAreSharedByEveryInjectionPoint()
    {
        assertNotNull(SkillLevelTracker.class.getAnnotation(Singleton.class),
            "SkillLevelTracker must be @Singleton; otherwise the plugin fills in one copy from the client"
                + " while the multiplier service reads an empty one and resolves every skill at level 1.");
    }

    @Test
    void multiplierThresholdsAreSharedByEveryInjectionPoint()
    {
        assertNotNull(XpMultiplierManager.class.getAnnotation(Singleton.class),
            "XpMultiplierManager must be @Singleton; otherwise thresholds saved from the multipliers tab"
                + " land in a manager the plugin never consults, and XP keeps banking at 1.00x.");
    }

    @Test
    void multipliersPanelIsTheUiEntryPointForTheMultiplierServices()
    {
        assertNotNull(XpMultipliersPanel.class.getAnnotation(Singleton.class),
            "XpMultipliersPanel must be @Singleton; it holds the visible list models, and a second"
                + " unscoped instance would be UI state nothing ever refreshes.");
    }
}

package com.gokirlbankedxp.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Covers the data-loss report that created the store: a user banked XP across a
 * five-hour session, restarted the client, and found every deposit gone.
 *
 * <p>The cause is outside the plugin. RuneLite uploads a synced profile's config
 * every few minutes and, if an upload fails, replaces the local config with the
 * server's copy on the next launch. The store's answer is a second copy in a
 * plugin-owned file, and these cases pin down which copy wins when they differ.</p>
 */
class BankedXpStoreTest
{
    private static final String XP = "gokirlbankedxp." + BankedXpStore.XP_KEY;
    private static final String SAVED_AT = "gokirlbankedxp." + BankedXpStore.SAVED_AT_KEY;

    @TempDir
    File dataDir;

    @Test
    void aSaveLandsInBothCopiesAndLoadsBack()
    {
        Map<String, String> config = new HashMap<>();
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);

        store.save(balances(Skill.AGILITY, 5_850L, Skill.COOKING, 1_200L));

        // Entries follow Skill declaration order, as the format always has.
        assertEquals("COOKING:1200,AGILITY:5850", config.get(XP));
        assertTrue(Long.parseLong(config.get(SAVED_AT)) > 0);
        assertTrue(store.dataFile().isFile(), "the plugin-owned file must exist after a save");

        Map<Skill, Long> loaded = store.load();
        assertEquals(5_850L, loaded.get(Skill.AGILITY));
        assertEquals(1_200L, loaded.get(Skill.COOKING));
    }

    /** A debt is a balance like any other: it must make the round trip with its sign intact. */
    @Test
    void aDebtIsSavedWithItsSignAndLoadsBack()
    {
        Map<String, String> config = new HashMap<>();
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);

        store.save(balances(Skill.AGILITY, 5_850L, Skill.WOODCUTTING, -5_000L, Skill.COOKING, 0L));

        // Zero means "no entry" and is dropped; the debt is kept, sign and all.
        assertEquals("WOODCUTTING:-5000,AGILITY:5850", config.get(XP));

        Map<Skill, Long> loaded = store.load();
        assertEquals(-5_000L, loaded.get(Skill.WOODCUTTING));
        assertEquals(5_850L, loaded.get(Skill.AGILITY));
        assertFalse(loaded.containsKey(Skill.COOKING));

        // The plugin-owned file restores the same debt on its own.
        config.clear();
        Map<Skill, Long> fromFile = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir).load();
        assertEquals(-5_000L, fromFile.get(Skill.WOODCUTTING));
    }

    /** The reported bug, reproduced: config rolled back to an old copy, the file has the session. */
    @Test
    void aConfigCopyOlderThanTheFileIsRestoredFromTheFile()
    {
        Map<String, String> config = new HashMap<>();
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);

        // A morning save that the server holds, then an afternoon of deposits.
        store.save(balances(Skill.AGILITY, 5_850L));
        String morningXp = config.get(XP);
        String morningSavedAt = config.get(SAVED_AT);
        store.save(balances(Skill.AGILITY, 40_000L, Skill.COOKING, 9_000L, Skill.MINING, 3_000L));

        // RuneLite restarts and replaces the local config with the server's copy.
        config.put(XP, morningXp);
        config.put(SAVED_AT, morningSavedAt);

        Map<Skill, Long> loaded = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir).load();

        assertEquals(40_000L, loaded.get(Skill.AGILITY));
        assertEquals(9_000L, loaded.get(Skill.COOKING));
        assertEquals(3_000L, loaded.get(Skill.MINING));
        // And the config copy is repaired, so a later sync carries the right data.
        assertEquals("COOKING:9000,MINING:3000,AGILITY:40000", config.get(XP));
    }

    /** The same rollback where the server copy predates the plugin entirely. */
    @Test
    void aMissingConfigCopyIsRestoredFromTheFile()
    {
        Map<String, String> config = new HashMap<>();
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);
        store.save(balances(Skill.AGILITY, 40_000L));

        config.clear();
        Map<Skill, Long> loaded = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir).load();

        assertEquals(40_000L, loaded.get(Skill.AGILITY));
        assertEquals("AGILITY:40000", config.get(XP));
    }

    /** A synced profile can legitimately carry newer data from another machine. */
    @Test
    void aConfigCopyNewerThanTheFileWinsAndRefreshesTheFile()
    {
        Map<String, String> config = new HashMap<>();
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);
        store.save(balances(Skill.AGILITY, 5_850L));
        long fileSavedAt = Long.parseLong(config.get(SAVED_AT));

        config.put(XP, "AGILITY:7000,FISHING:100");
        config.put(SAVED_AT, Long.toString(fileSavedAt + 1));

        Map<Skill, Long> loaded = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir).load();

        assertEquals(7_000L, loaded.get(Skill.AGILITY));
        assertEquals(100L, loaded.get(Skill.FISHING));
        // The file now agrees, so a later rollback of config restores this newer state.
        Map<Skill, Long> reloaded = new BankedXpStore(inMemoryConfigManager(new HashMap<>()), new Gson(), dataDir).load();
        assertEquals(7_000L, reloaded.get(Skill.AGILITY));
    }

    /** Users upgrading from before the file existed have config with no save time. */
    @Test
    void legacyConfigWithoutASaveTimeIsMigratedIntoTheFile()
    {
        Map<String, String> config = new HashMap<>();
        config.put(XP, "AGILITY:5850,WOODCUTTING:250");

        Map<Skill, Long> loaded = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir).load();

        assertEquals(5_850L, loaded.get(Skill.AGILITY));
        assertEquals(250L, loaded.get(Skill.WOODCUTTING));
        // The next launch can now survive a config rollback.
        Map<Skill, Long> reloaded = new BankedXpStore(inMemoryConfigManager(new HashMap<>()), new Gson(), dataDir).load();
        assertEquals(5_850L, reloaded.get(Skill.AGILITY));
    }

    /** A legacy config copy must not beat a file that was saved after it existed. */
    @Test
    void legacyConfigLosesToAnExistingFile()
    {
        Map<String, String> config = new HashMap<>();
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);
        store.save(balances(Skill.AGILITY, 40_000L));

        config.put(XP, "AGILITY:5850");
        config.remove(SAVED_AT);

        Map<Skill, Long> loaded = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir).load();
        assertEquals(40_000L, loaded.get(Skill.AGILITY));
    }

    @Test
    void aFreshInstallLoadsNothingAndWritesAnEmptySave()
    {
        Map<String, String> config = new HashMap<>();

        Map<Skill, Long> loaded = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir).load();

        assertTrue(loaded.isEmpty());
        assertEquals("", config.get(XP));
    }

    @Test
    void anUnreadableFileIsMovedAsideRatherThanOverwritten() throws IOException
    {
        Map<String, String> config = new HashMap<>();
        config.put(XP, "AGILITY:5850");
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);
        Files.write(store.dataFile().toPath(), "{not json".getBytes(StandardCharsets.UTF_8));

        Map<Skill, Long> loaded = store.load();

        assertEquals(5_850L, loaded.get(Skill.AGILITY));
        File[] kept = dataDir.listFiles((dir, name) -> name.contains(".corrupt-"));
        assertEquals(1, kept.length, "the damaged file is kept for inspection");
        assertTrue(store.dataFile().isFile(), "and a good file is written in its place");
    }

    @Test
    void unknownSkillsAndBadAmountsAreSkippedNotFatal()
    {
        Map<String, String> config = new HashMap<>();
        config.put(XP, "AGILITY:5850,NOTASKILL:10,COOKING:abc,MINING:0,FISHING");

        Map<Skill, Long> loaded = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir).load();

        assertEquals(1, loaded.size());
        assertEquals(5_850L, loaded.get(Skill.AGILITY));
    }

    @Test
    void recognisesTheEchoOfItsOwnConfigWriteAndNothingElse()
    {
        Map<String, String> config = new HashMap<>();
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);
        store.save(balances(Skill.AGILITY, 5_850L));

        assertTrue(store.isOwnConfigValue("AGILITY:5850"));
        assertFalse(store.isOwnConfigValue("AGILITY:1"));
        assertFalse(store.isOwnConfigValue(null), "an unset from outside is never the store's own write");
    }

    @Test
    void saveTimesAlwaysIncreaseEvenWithinTheSameMillisecond()
    {
        Map<String, String> config = new HashMap<>();
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(config), new Gson(), dataDir);

        store.save(balances(Skill.AGILITY, 1L));
        long first = Long.parseLong(config.get(SAVED_AT));
        store.save(balances(Skill.AGILITY, 2L));
        long second = Long.parseLong(config.get(SAVED_AT));

        assertTrue(second > first);
    }

    @Test
    void theFileIsNamedForTheActiveConfigProfileWhenThereIsOne()
    {
        BankedXpStore store = new BankedXpStore(inMemoryConfigManager(new HashMap<>()), new Gson(), dataDir);
        // A mocked ConfigManager has no profile, which is the fallback name.
        assertEquals("banked-xp.json", store.dataFile().getName());
        assertNull(inMemoryConfigManager(new HashMap<>()).getProfile());
    }

    private static Map<Skill, Long> balances(Object... skillsAndAmounts)
    {
        Map<Skill, Long> balances = new EnumMap<>(Skill.class);
        for (int i = 0; i < skillsAndAmounts.length; i += 2)
        {
            balances.put((Skill) skillsAndAmounts[i], (Long) skillsAndAmounts[i + 1]);
        }
        return balances;
    }

    private static ConfigManager inMemoryConfigManager(Map<String, String> values)
    {
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(invocation ->
            values.get(invocation.getArgument(0) + "." + invocation.getArgument(1)));
        doAnswer(invocation -> {
            values.put(invocation.getArgument(0) + "." + invocation.getArgument(1),
                String.valueOf((Object) invocation.getArgument(2)));
            return null;
        }).when(configManager).setConfiguration(anyString(), anyString(), any());
        return configManager;
    }
}

package com.gokirlbankedxp.service;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.gokirlbankedxp.GokIrlBankedXpConfig;
import com.gokirlbankedxp.model.XpMultiplierTier;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;

/**
 * A ready-made {@link XpMultiplierManager} over an in-memory config, for tests.
 *
 * <p>Public and shared rather than duplicated per test class: several suites now
 * need a multiplier manager purely to satisfy a constructor, and every one of
 * them wants the same default — real code, real persistence, and no tiers, so
 * XP passes through untouched and the case under test is unaffected.</p>
 *
 * <p>Building a {@link Gson} here is fine. The Plugin Hub never compiles
 * {@code src/test}, so its ban on constructing shared services does not reach
 * this file.</p>
 */
public final class TestMultipliers
{
    private final Map<String, String> values = new HashMap<>();

    public final ConfigManager configManager;
    public final GokIrlBankedXpConfig config;
    public final SkillLevelTracker levelTracker;
    public final XpMultiplierManager multiplierManager;

    /** A manager with the feature switched on and no tiers configured. */
    public TestMultipliers()
    {
        this(true);
    }

    public TestMultipliers(boolean levelMultipliersEnabled)
    {
        configManager = inMemoryConfigManager(values);
        config = mock(GokIrlBankedXpConfig.class);
        when(config.levelMultipliersEnabled()).thenReturn(levelMultipliersEnabled);

        levelTracker = new SkillLevelTracker(configManager, new Gson());
        levelTracker.load();

        multiplierManager = new XpMultiplierManager(configManager, config, levelTracker, new Gson());
        multiplierManager.load();
    }

    /**
     * Puts the player at a given level in a skill.
     *
     * <p>Goes through the same {@code recordExperience} path the plugin uses, so
     * the level is derived exactly as it is in production rather than injected.</p>
     */
    public TestMultipliers atLevel(Skill skill, int level)
    {
        levelTracker.recordExperience(skill, Experience.getXpForLevel(level));
        return this;
    }

    /** Appends one threshold to a skill's ladder. */
    public TestMultipliers withTier(Skill skill, int level, double multiplier)
    {
        List<XpMultiplierTier> tiers = new ArrayList<>(multiplierManager.getTiers(skill));
        tiers.add(new XpMultiplierTier(level, multiplier));
        multiplierManager.setTiers(skill, tiers);
        return this;
    }

    /** The raw config values written so far, for asserting on persistence. */
    public Map<String, String> storedValues()
    {
        return values;
    }

    /** Mirrors the in-memory config manager the other service tests use. */
    public static ConfigManager inMemoryConfigManager(Map<String, String> values)
    {
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(invocation ->
            values.get(invocation.getArgument(0) + "." + invocation.getArgument(1)));
        doAnswer(invocation -> {
            String key = invocation.getArgument(0) + "." + invocation.getArgument(1);
            Object value = invocation.getArgument(2);
            values.put(key, String.valueOf(value));
            return null;
        }).when(configManager).setConfiguration(anyString(), anyString(), any());
        return configManager;
    }
}

package com.gokirlbankedxp.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.Test;

/**
 * Covers the level cache the multipliers resolve against.
 *
 * <p>The persistence case is the one that matters: banking XP from the sidebar
 * works at the login screen, where the client cannot be asked for a level. If
 * levels were session-only, every such deposit would silently be multiplied as
 * though the player were level 1.</p>
 */
class SkillLevelTrackerTest
{
    @Test
    void levelsAreDerivedFromExperience()
    {
        SkillLevelTracker tracker = tracker(new HashMap<>());

        assertEquals(1, tracker.recordExperience(Skill.COOKING, 0));
        assertEquals(70, tracker.recordExperience(Skill.COOKING, Experience.getXpForLevel(70)));
        assertEquals(99, tracker.recordExperience(Skill.COOKING, Experience.getXpForLevel(99)));
        assertEquals(99, tracker.getLevel(Skill.COOKING));
    }

    @Test
    void virtualLevelsAreReportedPastNinetyNine()
    {
        SkillLevelTracker tracker = tracker(new HashMap<>());

        assertEquals(110, tracker.recordExperience(Skill.SLAYER, Experience.getXpForLevel(110)));
        assertEquals(Experience.MAX_VIRT_LEVEL,
            tracker.recordExperience(Skill.SLAYER, Experience.MAX_SKILL_XP));
    }

    @Test
    void anUnseenSkillReportsLevelOneAndSaysItWasNeverObserved()
    {
        SkillLevelTracker tracker = tracker(new HashMap<>());
        tracker.recordExperience(Skill.COOKING, Experience.getXpForLevel(50));

        assertEquals(SkillLevelTracker.UNKNOWN_LEVEL, tracker.getLevel(Skill.MINING));
        assertFalse(tracker.hasObserved(Skill.MINING));
        assertTrue(tracker.hasObserved(Skill.COOKING));
    }

    @Test
    void levelsSurviveAReloadSoLoggedOutDepositsStillMultiplyCorrectly()
    {
        Map<String, String> stored = new HashMap<>();
        SkillLevelTracker tracker = tracker(stored);
        tracker.recordExperience(Skill.AGILITY, Experience.getXpForLevel(85));

        SkillLevelTracker reloaded = tracker(stored);
        reloaded.load();

        assertEquals(85, reloaded.getLevel(Skill.AGILITY));
        assertTrue(reloaded.hasObserved(Skill.AGILITY));
    }

    /**
     * Levels change rarely and experience changes constantly, so only a level
     * change may write to config; otherwise every XP drop in the game would.
     */
    @Test
    void onlyALevelChangeWritesToConfig()
    {
        Map<String, String> stored = new HashMap<>();
        SkillLevelTracker tracker = tracker(stored);

        tracker.recordExperience(Skill.RANGED, Experience.getXpForLevel(60));
        String afterFirst = stored.get("gokirlbankedxp.observedSkillLevels");
        stored.remove("gokirlbankedxp.observedSkillLevels");

        // More experience, same level: nothing new should be written.
        tracker.recordExperience(Skill.RANGED, Experience.getXpForLevel(60) + 500);
        assertFalse(stored.containsKey("gokirlbankedxp.observedSkillLevels"));

        tracker.recordExperience(Skill.RANGED, Experience.getXpForLevel(61));
        assertTrue(stored.containsKey("gokirlbankedxp.observedSkillLevels"));
        assertTrue(afterFirst.contains("RANGED"));
    }

    @Test
    void unusableSavedLevelsAreIgnoredRatherThanThrowing()
    {
        Map<String, String> stored = new HashMap<>();
        stored.put("gokirlbankedxp.observedSkillLevels", "{\"NOT_A_SKILL\":50,\"MINING\":999}");

        SkillLevelTracker tracker = tracker(stored);
        tracker.load();

        // Clamped to the virtual ceiling rather than trusted or dropped.
        assertEquals(Experience.MAX_VIRT_LEVEL, tracker.getLevel(Skill.MINING));
    }

    private static SkillLevelTracker tracker(Map<String, String> stored)
    {
        ConfigManager configManager = TestMultipliers.inMemoryConfigManager(stored);
        SkillLevelTracker tracker = new SkillLevelTracker(configManager, new Gson());
        tracker.load();
        return tracker;
    }
}

package com.gokirlbankedxp.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import com.gokirlbankedxp.GokIrlBankedXpPlugin;
import com.gokirlbankedxp.model.IrlAction;
import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.Test;

/** Covers banking XP for work the user logs after finishing it. */
class ActionLogManagerTest
{
    @Test
    void logsRepetitionsOfUnitsAsBankedXp()
    {
        Fixture fixture = new Fixture();
        // "250 XP per km", the benchmark-style shape that has no timer at all.
        IrlAction running = fixture.createAction("Running", "km", 250L, Skill.AGILITY);

        // 12 km, nine times over.
        ActionLogManager.LoggedAward award =
            fixture.logManager.log(running.getId(), 12L, 9L).orElseThrow();

        assertEquals(108L, award.getTotalUnits());
        assertEquals(Map.of(Skill.AGILITY, 27_000L), award.getAwardedXp());
        verify(fixture.plugin).addActionXp(Skill.AGILITY, 27_000L);
    }

    @Test
    void everyMappedSkillIsAwardedAtItsOwnRate()
    {
        Fixture fixture = new Fixture();
        IrlAction lifting = fixture.actionManager.createAction(IrlAction.builder()
            .name("Weight lifting")
            .unitName("pounds")
            .timed(Boolean.FALSE)
            .defaultXpPerUnit(1L)
            .skillMappings(Map.of(Skill.STRENGTH, 2L, Skill.HITPOINTS, 1L))
            .build());

        ActionLogManager.LoggedAward award =
            fixture.logManager.log(lifting.getId(), 100L, 3L).orElseThrow();

        assertEquals(300L, award.getTotalUnits());
        assertEquals(Map.of(Skill.STRENGTH, 600L, Skill.HITPOINTS, 300L), award.getAwardedXp());
        verify(fixture.plugin).addActionXp(Skill.STRENGTH, 600L);
        verify(fixture.plugin).addActionXp(Skill.HITPOINTS, 300L);
    }

    @Test
    void previewMatchesTheAwardWithoutBankingAnything()
    {
        Fixture fixture = new Fixture();
        IrlAction running = fixture.createAction("Running", "km", 250L, Skill.AGILITY);

        ActionLogManager.LoggedAward preview =
            fixture.logManager.preview(running.getId(), 25L, 1L).orElseThrow();

        assertEquals(25L, preview.getTotalUnits());
        assertEquals(Map.of(Skill.AGILITY, 6_250L), preview.getAwardedXp());
        // A preview must never touch banked totals.
        verifyNoInteractions(fixture.plugin);
    }

    @Test
    void nothingIsBankedForUnknownActionsOrNonPositiveCounts()
    {
        Fixture fixture = new Fixture();
        IrlAction running = fixture.createAction("Running", "km", 250L, Skill.AGILITY);

        assertTrue(fixture.logManager.log(UUID.randomUUID(), 5L, 1L).isEmpty());
        assertTrue(fixture.logManager.log(running.getId(), 0L, 1L).isEmpty());
        assertTrue(fixture.logManager.log(running.getId(), 5L, 0L).isEmpty());
        assertTrue(fixture.logManager.log(running.getId(), -5L, 2L).isEmpty());
        verifyNoInteractions(fixture.plugin);
    }

    @Test
    void timedActionsCanAlsoBeLoggedByHand()
    {
        Fixture fixture = new Fixture();
        IrlAction reading = fixture.actionManager.createAction(IrlAction.builder()
            .name("Read a chapter")
            .unitName("Chapter")
            .secondsPerUnit(300L)
            .timed(Boolean.TRUE)
            .defaultXpPerUnit(25L)
            .skillMappings(Map.of(Skill.MAGIC, 25L))
            .build());

        ActionLogManager.LoggedAward award =
            fixture.logManager.log(reading.getId(), 4L, 2L).orElseThrow();

        assertEquals(200L, award.getAwardedXp().get(Skill.MAGIC));
    }

    /** Wires a real action manager over an in-memory config with a mocked plugin. */
    private static final class Fixture
    {
        private final GokIrlBankedXpPlugin plugin = mock(GokIrlBankedXpPlugin.class);
        private final IrlActionManager actionManager;
        private final ActionLogManager logManager;

        Fixture()
        {
            // The real plugin returns what it banked, and the log manager reports
            // that figure rather than its own estimate, so the mock has to answer
            // the same way or every award reads as zero.
            when(plugin.addActionXp(any(Skill.class), anyLong()))
                .thenAnswer(invocation -> invocation.getArgument(1, Long.class));

            actionManager = new IrlActionManager(inMemoryConfigManager(new HashMap<>()), new Gson());
            actionManager.loadActions();
            logManager = new ActionLogManager(actionManager, plugin, new TestMultipliers().multiplierManager);
        }

        IrlAction createAction(String name, String unit, long xpPerUnit, Skill skill)
        {
            return actionManager.createAction(IrlAction.builder()
                .name(name)
                .unitName(unit)
                .timed(Boolean.FALSE)
                .defaultXpPerUnit(xpPerUnit)
                .skillMappings(Map.of(skill, xpPerUnit))
                .build());
        }
    }

    private static ConfigManager inMemoryConfigManager(Map<String, String> values)
    {
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(invocation ->
            values.get(invocation.getArgument(0) + "." + invocation.getArgument(1)));
        doAnswer(invocation -> {
            String key = invocation.getArgument(0) + "." + invocation.getArgument(1);
            Object value = invocation.getArgument(2);
            values.put(key, String.valueOf(value));
            return null;
        }).when(configManager).setConfiguration(anyString(), anyString(), any());
        return configManager;
    }
}

package com.gokirlbankedxp.service;

import com.google.gson.Gson;
import com.gokirlbankedxp.GokIrlBankedXpPlugin;
import com.gokirlbankedxp.model.ActiveTimer;
import com.gokirlbankedxp.model.IrlAction;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Covers timer settlement, immutable earning terms, malformed saves and arithmetic limits. */
class TimerManagerRegressionTest
{
    private static IrlAction action(long seconds, long rate)
    {
        return IrlAction.builder().name("Audit action").unitName("unit")
            .secondsPerUnit(seconds).defaultXpPerUnit(rate)
            .skillMappings(Map.of(Skill.AGILITY, rate)).build();
    }

    @Test
    void shorteningAnActionMustNotAwardPreviouslyPaidTimeAgain()
    {
        IrlAction original = action(60, 10);
        ActiveTimer timer = ActiveTimer.start(original.getId(), 1000);
        assertEquals(100L, timer.applyTick(601000, original).get(Skill.AGILITY).longValue());
        IrlAction edited = original.toBuilder().secondsPerUnit(1).build();
        // Existing timers retain their original minute interval and rate.
        assertTrue(timer.applyTick(602000, edited).isEmpty());
        assertEquals(Map.of(Skill.AGILITY, 10L), timer.applyTick(661000, edited));
    }

    @Test
    void lengtheningAnActionMustNotSuspendAwardsUntilOldUnitCountIsReached()
    {
        IrlAction original = action(1, 10);
        ActiveTimer timer = ActiveTimer.start(original.getId(), 1000);
        timer.applyTick(601000, original);
        IrlAction edited = original.toBuilder().secondsPerUnit(60).build();
        // The existing timer still awards the original one-second units.
        assertEquals(Map.of(Skill.AGILITY, 600L), timer.applyTick(661000, edited));
    }

    @Test
    void stoppingSettlesAWholeUnitSinceTheLastSchedulerTick()
    {
        Fixture f = new Fixture();
        IrlAction action = f.actions.createAction(action(60, 10));
        UUID timer = f.timers.startTimer(action.getId()).orElseThrow();
        f.clock.addAndGet(59000);
        f.timers.tick();
        f.clock.addAndGet(1100);
        assertTrue(f.timers.stopTimer(timer));
        assertEquals(10L, f.awarded.get());
    }

    @Test
    void combinedTimerAwardsMustNotOverflowNegative()
    {
        Fixture f = new Fixture();
        IrlAction action = f.actions.createAction(action(1, Long.MAX_VALUE));
        f.timers.startTimer(action.getId());
        f.timers.startTimer(action.getId());
        f.clock.addAndGet(1000);
        f.timers.tick();
        assertEquals(Long.MAX_VALUE, f.awarded.get());
    }

    /**
     * scheduleAtFixedRate silently cancels a task the first time it throws. The
     * scheduled entry point therefore has to swallow the failure, or one bad
     * award would stop every timer until the plugin was restarted.
     */
    @Test
    void aFailingAwardDoesNotStopTheScheduledTick()
    {
        Fixture f = new Fixture();
        IrlAction action = f.actions.createAction(action(1, 10));
        UUID timerId = f.timers.startTimer(action.getId()).orElseThrow();
        doThrow(new IllegalStateException("config write failed"))
            .when(f.plugin).addActionXp(any(Skill.class), anyLong());

        f.clock.addAndGet(1000);
        // The raw tick does propagate the failure; the scheduled wrapper must not.
        assertThrows(IllegalStateException.class, f.timers::tick);
        f.clock.addAndGet(1000);
        assertDoesNotThrow(f.timers::runScheduledTick);

        // The timer is still there and still counting afterwards.
        assertEquals(timerId, f.timers.getActiveTimers().get(0).getId());
        assertEquals(2L, f.timers.getActiveTimers().get(0).getElapsedSeconds());
    }

    /** A renamed action shows its new name on its running timer; the frozen rates stay. */
    @Test
    void timerSnapshotsShowTheLiveActionNameWithTheFrozenTerms()
    {
        Fixture f = new Fixture();
        IrlAction original = f.actions.createAction(action(60, 10));
        f.timers.startTimer(original.getId()).orElseThrow();

        f.actions.updateAction(original.toBuilder().name("Renamed").skillMappings(Map.of(Skill.AGILITY, 999L)).build());

        TimerManager.TimerSnapshot snapshot = f.timers.getTimerSnapshots().get(0);
        assertEquals("Renamed", snapshot.actionName());
        assertEquals("Agility +10/unit", snapshot.formatRates());
    }

    @Test
    void nullPersistedTimerMustNotPreventStartup()
    {
        Fixture f = new Fixture();
        f.values.put("gokirlbankedxp.activeTimersJson", "[null]");
        assertDoesNotThrow(f.timers::startUp);
    }

    @Test
    void originalTermsSurviveActionEditAndManagerRecreation()
    {
        Fixture f = new Fixture();
        IrlAction original = f.actions.createAction(action(60, 10));
        UUID timerId = f.timers.startTimer(original.getId()).orElseThrow();
        f.clock.addAndGet(59000);
        f.timers.tick();
        f.actions.updateAction(original.toBuilder().secondsPerUnit(1).skillMappings(Map.of(Skill.AGILITY, 1000L)).build());
        f.timers.shutDown();
        // Recreate both managers, not just the timer model, to exercise the JSON format.
        IrlActionManager reopenedActions = new IrlActionManager(f.config, new Gson());
        reopenedActions.loadActions();
        TimerManager reopened = new TimerManager(f.config, reopenedActions, f.plugin, null, new Gson(), f.clock::get);
        reopened.startUp();
        f.clock.addAndGet(1000);
        reopened.tick();
        assertEquals(10L, f.awarded.get());
        assertEquals(timerId, reopened.getActiveTimers().get(0).getId());
        assertEquals(60L, reopened.getActiveTimers().get(0).getActionSnapshot().getSecondsPerUnit());
        reopened.startTimer(original.getId());
        f.clock.addAndGet(1000);
        reopened.tick();
        assertEquals(1010L, f.awarded.get(), "Only new timers use edited rates");
    }

    @Test
    void nullEntryDoesNotDiscardAdjacentValidTimer()
    {
        Fixture f = new Fixture();
        IrlAction action = f.actions.createAction(action(60, 10));
        UUID timerId = f.timers.startTimer(action.getId()).orElseThrow();
        String key = "gokirlbankedxp.activeTimersJson";
        com.google.gson.JsonArray saved = new Gson().fromJson(f.values.get(key), com.google.gson.JsonArray.class);
        saved.add(com.google.gson.JsonNull.INSTANCE);
        f.values.put(key, saved.toString());
        f.timers.startUp();
        assertEquals(timerId, f.timers.getActiveTimers().get(0).getId());
        assertEquals(1, f.timers.getActiveTimers().size());
    }

    @Test
    void pauseThenStopDoesNotAwardTwiceOrRoundUpPartialUnits()
    {
        Fixture f = new Fixture();
        IrlAction action = f.actions.createAction(action(60, 10));
        UUID timer = f.timers.startTimer(action.getId()).orElseThrow();
        f.clock.addAndGet(61000);
        assertTrue(f.timers.pauseTimer(timer));
        f.clock.addAndGet(60000);
        assertTrue(f.timers.stopTimer(timer));
        assertEquals(10L, f.awarded.get());
        UUID partial = f.timers.startTimer(action.getId()).orElseThrow();
        f.clock.addAndGet(59000);
        assertTrue(f.timers.stopTimer(partial));
        assertFalse(f.timers.stopTimer(partial));
        assertEquals(10L, f.awarded.get());
    }

    @Test
    void legacyTimerWithoutSnapshotMigratesWithoutReawardingCompletedUnits()
    {
        Fixture f = new Fixture();
        IrlAction action = f.actions.createAction(action(60, 10));
        UUID timerId = UUID.randomUUID();
        // This is the previous persisted schema: no frozen action field.
        f.values.put("gokirlbankedxp.activeTimersJson", new Gson().toJson(java.util.List.of(Map.of(
            "id", timerId, "actionId", action.getId(), "elapsedSeconds", 119L, "paused", false))));
        f.timers.startUp();
        assertEquals(60L, f.timers.getActiveTimers().get(0).getActionSnapshot().getSecondsPerUnit());
        f.clock.addAndGet(1000);
        f.timers.tick();
        assertEquals(10L, f.awarded.get(), "Only the newly completed second minute is due");
    }

    /** Mimics the repository's existing persistence fixtures with a controlled clock. */
    private static final class Fixture
    {
        final Map<String, String> values = new HashMap<>();
        final AtomicLong clock = new AtomicLong(1000);
        final AtomicLong awarded = new AtomicLong();
        final IrlActionManager actions;
        final TimerManager timers;
        final ConfigManager config = mock(ConfigManager.class);
        final GokIrlBankedXpPlugin plugin = mock(GokIrlBankedXpPlugin.class);

        Fixture()
        {
            // ConfigManager's two-argument getter returns a nullable String.
            when(config.getConfiguration(anyString(), anyString())).thenAnswer(call ->
                values.get(call.getArgument(0) + "." + call.getArgument(1)));
            // Its three-argument setter is void; retain the exact serialized value.
            doAnswer(call -> {
                values.put(call.getArgument(0) + "." + call.getArgument(1), String.valueOf((Object) call.getArgument(2)));
                return null;
            }).when(config).setConfiguration(anyString(), anyString(), any());
            // Capture the amount handed to the plugin before its positive-value guard.
            when(plugin.addActionXp(any(Skill.class), anyLong())).thenAnswer(call -> {
                long amount = call.getArgument(1);
                awarded.addAndGet(amount);
                return amount;
            });
            actions = new IrlActionManager(config, new Gson());
            actions.loadActions();
            timers = new TimerManager(config, actions, plugin, null, new Gson(), clock::get);
            timers.startUp();
        }
    }
}

package com.gokirlbankedxp.service;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.gokirlbankedxp.GokIrlBankedXpPlugin;
import com.gokirlbankedxp.model.IrlAction;
import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import org.junit.jupiter.api.Test;

/** Verifies the same config-backed save/load boundary used across client sessions. */
class PersistenceTest
{
    /**
     * Production code receives Gson from RuneLite's injector. Tests are never
     * compiled or shipped by the Plugin Hub, so building one here is fine and
     * keeps these cases free of a Guice bootstrap.
     */
    private static Gson gson()
    {
        return new Gson();
    }

    @Test
    void legacyPresetUnitIsMigratedToTheCustomUnitShape()
    {
        UUID id = UUID.randomUUID();
        Map<String, String> persistedConfig = new HashMap<>();
        persistedConfig.put("gokirlbankedxp.irlActionsJson", String.format(
            "[{\"id\":\"%s\",\"name\":\"Walking\",\"timeUnit\":\"MINUTES\","
                + "\"defaultXpPerUnit\":50,\"skillMappings\":{\"AGILITY\":50}}]", id));

        IrlActionManager manager = new IrlActionManager(inMemoryConfigManager(persistedConfig), gson());
        manager.loadActions();

        IrlAction migrated = manager.getAllActions().get(0);
        assertEquals("Minutes", migrated.getUnitName());
        assertEquals(60L, migrated.getSecondsPerUnit());
        assertFalse(persistedConfig.get("gokirlbankedxp.irlActionsJson").contains("timeUnit"));
    }

    /**
     * Actions saved before untimed actions existed carry no "timed" flag at all.
     * They were all timer-driven, so they must come back as timed rather than
     * silently losing their timers to a boolean defaulting to false.
     */
    @Test
    void actionsSavedWithoutTheTimedFlagStayTimed()
    {
        UUID id = UUID.randomUUID();
        Map<String, String> persistedConfig = new HashMap<>();
        persistedConfig.put("gokirlbankedxp.irlActionsJson", String.format(
            "[{\"id\":\"%s\",\"name\":\"Walking\",\"unitName\":\"Minutes\",\"secondsPerUnit\":60,"
                + "\"defaultXpPerUnit\":50,\"skillMappings\":{\"AGILITY\":50}}]", id));

        IrlActionManager manager = new IrlActionManager(inMemoryConfigManager(persistedConfig), gson());
        manager.loadActions();

        IrlAction migrated = manager.getAllActions().get(0);
        assertTrue(migrated.isTimed());
        assertEquals(60L, migrated.getSecondsPerUnit());
    }

    @Test
    void untimedActionsPersistWithoutADurationAndCannotStartTimers()
    {
        Map<String, String> persistedConfig = new HashMap<>();
        ConfigManager configManager = inMemoryConfigManager(persistedConfig);

        IrlActionManager actions = new IrlActionManager(configManager, gson());
        actions.loadActions();

        IrlAction lifting = actions.createAction(IrlAction.builder()
            .name("Weight lifting")
            .unitName("pounds")
            .timed(Boolean.FALSE)
            .defaultXpPerUnit(1L)
            .skillMappings(Map.of(Skill.STRENGTH, 1L))
            .build());

        assertFalse(lifting.isTimed());
        assertEquals(0L, lifting.getSecondsPerUnit());

        // The unit is still remembered for reuse, just without a duration.
        assertEquals(Map.of("pounds", 0L), actions.getSavedUnits());

        IrlActionManager reopened = new IrlActionManager(configManager, gson());
        reopened.loadActions();
        IrlAction restored = reopened.getAllActions().get(0);
        assertFalse(restored.isTimed());
        assertEquals(0L, restored.getSecondsPerUnit());
        assertEquals(Map.of("pounds", 0L), reopened.getSavedUnits());

        GokIrlBankedXpPlugin plugin = mock(GokIrlBankedXpPlugin.class);
        TimerManager timers = new TimerManager(configManager, reopened, plugin, null, gson(), () -> 0L);
        timers.startUp();
        // An untimed action has no seconds-per-unit to accrue against, so a timer
        // on one would run forever awarding nothing.
        assertTrue(timers.startTimer(restored.getId()).isEmpty());
    }

    @Test
    void customActionsUnitsAndTimersSurviveManagerRecreation()
    {
        Map<String, String> persistedConfig = new HashMap<>();
        ConfigManager configManager = inMemoryConfigManager(persistedConfig);

        IrlActionManager firstActions = new IrlActionManager(configManager, gson());
        firstActions.loadActions();
        assertTrue(firstActions.getAllActions().isEmpty());

        IrlAction action = firstActions.createAction(IrlAction.builder()
            .name("Read a chapter")
            .unitName("Chapter")
            .secondsPerUnit(300L)
            .defaultXpPerUnit(25L)
            .skillMappings(Map.of(Skill.MAGIC, 25L))
            .build());

        AtomicLong clock = new AtomicLong(10_000L);
        GokIrlBankedXpPlugin plugin = mock(GokIrlBankedXpPlugin.class);
        TimerManager firstTimers = new TimerManager(configManager, firstActions, plugin, null, gson(), clock::get);
        firstTimers.startUp();
        assertTrue(firstTimers.startTimer(action.getId()).isPresent());
        clock.addAndGet(5_000L);
        firstTimers.tick();
        firstTimers.shutDown();

        // Recreate both managers to model closing RuneLite and opening it again.
        IrlActionManager reopenedActions = new IrlActionManager(configManager, gson());
        reopenedActions.loadActions();
        assertEquals(1, reopenedActions.getAllActions().size());
        IrlAction reopenedAction = reopenedActions.getAllActions().get(0);
        assertEquals(action.getId(), reopenedAction.getId());
        assertEquals("Chapter", reopenedAction.getUnitName());
        assertEquals(300L, reopenedAction.getSecondsPerUnit());
        assertEquals(Map.of("Chapter", 300L), reopenedActions.getSavedUnits());

        TimerManager reopenedTimers = new TimerManager(configManager, reopenedActions, plugin, null, gson(), clock::get);
        reopenedTimers.startUp();
        assertEquals(1, reopenedTimers.getTimerSnapshots().size());
        assertEquals(action.getId(), reopenedTimers.getActiveTimers().get(0).getActionId());
        assertEquals(5L, reopenedTimers.getActiveTimers().get(0).getElapsedSeconds());

        // Units are a persistent user library, not merely a projection of the
        // actions that currently happen to reference them.
        assertTrue(reopenedActions.deleteAction(action.getId()));
        IrlActionManager afterDeletion = new IrlActionManager(configManager, gson());
        afterDeletion.loadActions();
        assertTrue(afterDeletion.getAllActions().isEmpty());
        assertEquals(Map.of("Chapter", 300L), afterDeletion.getSavedUnits());
    }

    private static ConfigManager inMemoryConfigManager(Map<String, String> values)
    {
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(invocation ->
            values.get(invocation.getArgument(0) + "." + invocation.getArgument(1)));
        doAnswer(invocation -> {
            String key = invocation.getArgument(0) + "." + invocation.getArgument(1);
            Object value = invocation.getArgument(2);
            values.put(key, String.valueOf(value));
            return null;
        }).when(configManager).setConfiguration(anyString(), anyString(), any());
        return configManager;
    }
}

package com.gokirlbankedxp;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.gokirlbankedxp.service.TestMultipliers;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JComboBox;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import net.runelite.api.Skill;
import org.junit.jupiter.api.Test;

class GokIrlBankedXpPanelTest
{
    @Test
    void parsesPositiveWholeNumberXp()
    {
        assertEquals(1250L, GokIrlBankedXpPanel.parsePositiveXp(" 1250 "));
    }

    /** People type XP the way the game prints it; the separator must not be a rejection. */
    @Test
    void acceptsThousandsSeparators()
    {
        assertEquals(1250L, GokIrlBankedXpPanel.parsePositiveXp("1,250"));
        assertEquals(1_000_000L, GokIrlBankedXpPanel.parsePositiveXp("1,000,000"));
    }

    /** A number followed by junk is not that number; it is a typo to report. */
    @Test
    void rejectsTrailingText()
    {
        assertEquals(0L, GokIrlBankedXpPanel.parsePositiveXp("1250xp"));
        assertEquals(0L, GokIrlBankedXpPanel.parsePositiveXp("12.5"));
    }

    @Test
    void rejectsInvalidXpWithoutThrowing()
    {
        assertEquals(0L, GokIrlBankedXpPanel.parsePositiveXp(null));
        assertEquals(0L, GokIrlBankedXpPanel.parsePositiveXp(""));
        assertEquals(0L, GokIrlBankedXpPanel.parsePositiveXp("ten"));
        assertEquals(0L, GokIrlBankedXpPanel.parsePositiveXp("-5"));
        assertEquals(0L, GokIrlBankedXpPanel.parsePositiveXp("999999999999999999999"));
    }

    @Test
    void xpControlIsAnEditableFocusableTextField() throws Exception
    {
        GokIrlBankedXpPlugin plugin = mock(GokIrlBankedXpPlugin.class);
        when(plugin.getTrackableSkills()).thenReturn(new Skill[]{Skill.AGILITY});
        AtomicReference<JTextField> fieldReference = new AtomicReference<>();

        SwingUtilities.invokeAndWait(() -> {
            GokIrlBankedXpPanel panel = new GokIrlBankedXpPanel(plugin, new TestMultipliers().multiplierManager);
            fieldReference.set(findTextField(panel));
        });

        JTextField field = fieldReference.get();
        assertNotNull(field);
        assertTrue(field.isEditable());
        assertTrue(field.isEnabled());
        assertTrue(field.isFocusable());
        assertTrue(field.getPreferredSize().height >= 36);
    }

    /**
     * The removal form must be unable to reach a skill with nothing banked.
     *
     * <p>This is the hard guarantee behind "you can never hold a negative
     * balance": rather than validating a subtraction after the fact, the skill
     * drop-down is built from the skills that actually hold XP, so an empty skill
     * is not selectable in the first place.</p>
     */
    @Test
    void removalOffersOnlySkillsThatHaveBankedXp() throws Exception
    {
        GokIrlBankedXpPlugin plugin = mock(GokIrlBankedXpPlugin.class);
        when(plugin.getTrackableSkills()).thenReturn(new Skill[]{Skill.AGILITY, Skill.COOKING});
        when(plugin.getBankedXp(Skill.COOKING)).thenReturn(500L);

        AtomicReference<GokIrlBankedXpPanel> panelReference = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> panelReference.set(new GokIrlBankedXpPanel(plugin, new TestMultipliers().multiplierManager)));

        // Only Cooking is banked; Agility has nothing.
        panelReference.get().updateSnapshot(new GokIrlBankedXpPlugin.BankedXpSnapshot(
            500L,
            List.of(new GokIrlBankedXpPlugin.BankedSkill(Skill.COOKING, "Cooking", 500L, 0, false))));
        SwingUtilities.invokeAndWait(() -> { });

        AtomicReference<List<JComboBox<?>>> combos = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> combos.set(findComboBoxes(panelReference.get())));

        // Declaration order: the deposit form is added to the card stack first,
        // so its all-skills selector precedes the removal selector.
        assertEquals(2, combos.get().size(), "expected the deposit and removal selectors");
        JComboBox<?> removeSelector = combos.get().get(1);
        assertEquals(1, removeSelector.getItemCount());
        assertEquals(Skill.COOKING, removeSelector.getItemAt(0));
        assertTrue(removeSelector.isEnabled());
    }

    /** A skill in debt has nothing to take back, so the removal form must not offer it. */
    @Test
    void removalDoesNotOfferASkillThatIsInDebt() throws Exception
    {
        GokIrlBankedXpPlugin plugin = mock(GokIrlBankedXpPlugin.class);
        when(plugin.getTrackableSkills()).thenReturn(new Skill[]{Skill.COOKING, Skill.WOODCUTTING});
        when(plugin.getBankedXp(Skill.COOKING)).thenReturn(500L);
        when(plugin.getBankedXp(Skill.WOODCUTTING)).thenReturn(-5_000L);

        AtomicReference<GokIrlBankedXpPanel> panelReference = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> panelReference.set(new GokIrlBankedXpPanel(plugin, new TestMultipliers().multiplierManager)));

        // Cooking is banked; Woodcutting is owed after a quest reward.
        panelReference.get().updateSnapshot(new GokIrlBankedXpPlugin.BankedXpSnapshot(
            -4_500L,
            List.of(
                new GokIrlBankedXpPlugin.BankedSkill(Skill.COOKING, "Cooking", 500L, 0, false),
                new GokIrlBankedXpPlugin.BankedSkill(Skill.WOODCUTTING, "Woodcutting", -5_000L, 0, false))));
        SwingUtilities.invokeAndWait(() -> { });

        AtomicReference<List<JComboBox<?>>> combos = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> combos.set(findComboBoxes(panelReference.get())));

        JComboBox<?> removeSelector = combos.get().get(1);
        assertEquals(1, removeSelector.getItemCount());
        assertEquals(Skill.COOKING, removeSelector.getItemAt(0));
        assertTrue(removeSelector.isEnabled());
    }

    @Test
    void removalIsInertWhenNothingIsBanked() throws Exception
    {
        GokIrlBankedXpPlugin plugin = mock(GokIrlBankedXpPlugin.class);
        when(plugin.getTrackableSkills()).thenReturn(new Skill[]{Skill.AGILITY});

        AtomicReference<GokIrlBankedXpPanel> panelReference = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> panelReference.set(new GokIrlBankedXpPanel(plugin, new TestMultipliers().multiplierManager)));

        panelReference.get().updateSnapshot(GokIrlBankedXpPlugin.BankedXpSnapshot.empty());
        SwingUtilities.invokeAndWait(() -> { });

        AtomicReference<List<JComboBox<?>>> combos = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> combos.set(findComboBoxes(panelReference.get())));

        JComboBox<?> removeSelector = combos.get().get(1);
        assertEquals(0, removeSelector.getItemCount());
        assertFalse(removeSelector.isEnabled());
    }

    private static List<JComboBox<?>> findComboBoxes(Container container)
    {
        List<JComboBox<?>> found = new ArrayList<>();
        for (Component child : container.getComponents())
        {
            if (child instanceof JComboBox)
            {
                found.add((JComboBox<?>) child);
            }
            else if (child instanceof Container)
            {
                found.addAll(findComboBoxes((Container) child));
            }
        }
        return found;
    }

    private static JTextField findTextField(Container container)
    {
        for (Component child : container.getComponents())
        {
            if (child instanceof JTextField)
            {
                return (JTextField) child;
            }
            if (child instanceof Container)
            {
                JTextField nested = findTextField((Container) child);
                if (nested != null)
                {
                    return nested;
                }
            }
        }
        return null;
    }
}

package com.gokirlbankedxp;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.gokirlbankedxp.service.BankedXpStore;
import com.gokirlbankedxp.service.DepletionForecaster;
import com.gokirlbankedxp.service.TestMultipliers;
import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Notification;
import net.runelite.client.events.ConfigChanged;
import org.junit.jupiter.api.Test;

/**
 * Covers the level multiplier where it actually bites: the plugin's deposit path.
 *
 * <p>{@code XpMultiplierManagerTest} proves the rule; this proves the plugin
 * applies it, applies it exactly once, and does not apply it to the things it
 * must leave alone — corrections, and XP the game itself consumes.</p>
 *
 * <p>RuneLite builds the plugin through its own child injector, which a unit test
 * cannot start, so the {@code @Inject} fields are set reflectively. That is
 * confined to test code, which the Plugin Hub never compiles.</p>
 */
class LevelMultiplierBankingTest
{
    @Test
    void aManualDepositIsMultipliedByTheSkillsCurrentThreshold()
    {
        Fixture fixture = new Fixture();
        fixture.multipliers.withTier(Skill.COOKING, 70, 2.0).atLevel(Skill.COOKING, 82);

        assertEquals(1_000L, fixture.plugin.addManualXp(Skill.COOKING, 500L));
        assertEquals(1_000L, fixture.plugin.getBankedXp(Skill.COOKING));
    }

    @Test
    void actionXpTakesTheSameMultiplierAsAManualDeposit()
    {
        Fixture fixture = new Fixture();
        fixture.multipliers.withTier(Skill.AGILITY, 50, 3.0).atLevel(Skill.AGILITY, 50);

        assertEquals(750L, fixture.plugin.addActionXp(Skill.AGILITY, 250L));
        assertEquals(750L, fixture.plugin.getBankedXp(Skill.AGILITY));
    }

    /**
     * The multiplier lives at one choke point precisely so it cannot be applied
     * twice. Two separate deposits must scale individually, not compound.
     */
    @Test
    void repeatedDepositsEachScaleOnceRatherThanCompounding()
    {
        Fixture fixture = new Fixture();
        fixture.multipliers.withTier(Skill.MINING, 1, 2.0).atLevel(Skill.MINING, 30);

        fixture.plugin.addManualXp(Skill.MINING, 100L);
        fixture.plugin.addManualXp(Skill.MINING, 100L);

        assertEquals(400L, fixture.plugin.getBankedXp(Skill.MINING));
    }

    /**
     * A correction takes back a literal figure. The user is undoing an amount
     * they can read off their own balance, so multiplying it would remove
     * something other than what they asked for.
     */
    @Test
    void removalIsNeverMultiplied()
    {
        Fixture fixture = new Fixture();
        fixture.multipliers.withTier(Skill.FISHING, 1, 4.0).atLevel(Skill.FISHING, 60);

        fixture.plugin.addManualXp(Skill.FISHING, 250L);
        assertEquals(1_000L, fixture.plugin.getBankedXp(Skill.FISHING));

        assertEquals(400L, fixture.plugin.removeManualXp(Skill.FISHING, 400L));
        assertEquals(600L, fixture.plugin.getBankedXp(Skill.FISHING));
    }

    /** In-game XP drains the balance one for one; a multiplier is a deposit rule. */
    @Test
    void inGameXpStillDrainsTheBalanceOneForOne()
    {
        Fixture fixture = new Fixture();
        fixture.multipliers.withTier(Skill.WOODCUTTING, 1, 5.0).atLevel(Skill.WOODCUTTING, 40);

        fixture.plugin.addManualXp(Skill.WOODCUTTING, 200L);
        assertEquals(1_000L, fixture.plugin.getBankedXp(Skill.WOODCUTTING));

        fixture.gainXp(Skill.WOODCUTTING, 300);

        assertEquals(700L, fixture.plugin.getBankedXp(Skill.WOODCUTTING));
    }

    @Test
    void aZeroThresholdBanksNothingAndReportsThat()
    {
        Fixture fixture = new Fixture();
        fixture.multipliers.withTier(Skill.SLAYER, 1, 0.0).atLevel(Skill.SLAYER, 50);

        assertEquals(0L, fixture.plugin.addManualXp(Skill.SLAYER, 5_000L));
        assertEquals(0L, fixture.plugin.getBankedXp(Skill.SLAYER));
    }

    @Test
    void aSkillWithNoThresholdsIsUntouched()
    {
        Fixture fixture = new Fixture();
        fixture.multipliers.withTier(Skill.COOKING, 1, 10.0).atLevel(Skill.COOKING, 50);

        assertEquals(500L, fixture.plugin.addManualXp(Skill.FLETCHING, 500L));
    }

    /**
     * Levelling up mid-session moves the skill onto the next threshold, and the
     * plugin learns that from the same {@link StatChanged} the game already sends.
     */
    @Test
    void levellingUpInGameMovesLaterDepositsOntoTheNextThreshold()
    {
        Fixture fixture = new Fixture();
        fixture.multipliers
            .withTier(Skill.HERBLORE, 50, 2.0)
            .withTier(Skill.HERBLORE, 70, 4.0)
            .atLevel(Skill.HERBLORE, 69);

        assertEquals(200L, fixture.plugin.addManualXp(Skill.HERBLORE, 100L));

        // The game reports enough experience for level 70; the tracker picks the
        // new level up from the event, with no client query of its own.
        fixture.plugin.onStatChanged(new StatChanged(
            Skill.HERBLORE, Experience.getXpForLevel(70), 70, 70));

        assertEquals(400L, fixture.plugin.addManualXp(Skill.HERBLORE, 100L));
    }

    /**
     * The master switch lives in RuneLite's settings panel, which the sidebar
     * cannot see. Flipping it has to push a fresh snapshot so the deposit
     * preview and the multipliers tab stop quoting the old multiplier.
     */
    @Test
    void togglingTheMasterSwitchRefreshesTheSidebar() throws Exception
    {
        Fixture fixture = new Fixture();

        ConfigChanged event = new ConfigChanged();
        event.setGroup(GokIrlBankedXpConfig.GROUP);
        event.setKey("levelMultipliersEnabled");
        event.setNewValue("false");
        fixture.plugin.onConfigChanged(event);

        // The snapshot is handed to the panel through invokeLater; let it land.
        SwingUtilities.invokeAndWait(() -> { });
        verify(fixture.panel).updateSnapshot(any());
    }

    /** A plugin wired to mocks, with real multiplier services behind it. */
    private static final class Fixture
    {
        private final GokIrlBankedXpPlugin plugin = new GokIrlBankedXpPlugin();
        private final GokIrlBankedXpConfig config = mock(GokIrlBankedXpConfig.class);
        private final TestMultipliers multipliers = new TestMultipliers();
        private final GokIrlXpPanel panel = mock(GokIrlXpPanel.class);
        private final Map<String, String> stored = new HashMap<>();

        Fixture()
        {
            // The warnings are covered by their own suite; silenced here so these
            // cases measure only what lands in the bank.
            when(config.lowXpThreshold()).thenReturn(0);
            when(config.chatWarningEnabled()).thenReturn(false);
            when(config.depletionWarningActions()).thenReturn(0);
            when(config.depletionNotification()).thenReturn(Notification.ON);

            set("config", config);
            set("notifier", mock(Notifier.class));
            set("depletionForecaster", new DepletionForecaster());
            // The real store, pointed at a throwaway directory, so these cases run
            // the genuine save path without touching the developer's ~/.runelite.
            set("bankedXpStore", new BankedXpStore(inMemoryConfigManager(stored), new Gson(), TestDataDir.create()));
            set("client", mock(Client.class));
            set("panel", panel);
            set("skillLevelTracker", multipliers.levelTracker);
            set("xpMultiplierManager", multipliers.multiplierManager);
        }

        /**
         * Fires an in-game XP drop for a skill.
         *
         * <p>The plugin ignores the first {@link StatChanged} it sees for a skill,
         * using it only to establish the baseline later drops are measured
         * against, so a priming event is sent first.</p>
         */
        void gainXp(Skill skill, int delta)
        {
            int baseline = Experience.getXpForLevel(50);
            plugin.onStatChanged(new StatChanged(skill, baseline, 50, 50));
            plugin.onStatChanged(new StatChanged(skill, baseline + delta, 50, 50));
        }

        private void set(String fieldName, Object value)
        {
            try
            {
                Field field = GokIrlBankedXpPlugin.class.getDeclaredField(fieldName);
                field.setAccessible(true);
                field.set(plugin, value);
            }
            catch (ReflectiveOperationException ex)
            {
                throw new IllegalStateException("Unable to inject " + fieldName, ex);
            }
        }
    }

    private static ConfigManager inMemoryConfigManager(Map<String, String> values)
    {
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(invocation ->
            values.get(invocation.getArgument(0) + "." + invocation.getArgument(1)));
        doAnswer(invocation -> {
            String key = invocation.getArgument(0) + "." + invocation.getArgument(1);
            Object value = invocation.getArgument(2);
            values.put(key, String.valueOf(value));
            return null;
        }).when(configManager).setConfiguration(anyString(), anyString(), any());
        return configManager;
    }
}

package com.gokirlbankedxp;

import com.google.gson.Gson;
import com.gokirlbankedxp.model.IrlAction;
import com.gokirlbankedxp.model.XpMultiplierTier;
import com.gokirlbankedxp.service.*;
import java.io.File;
import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.swing.SwingUtilities;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigProfile;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/** Exercise complete profile transitions and on-disk restoration, without a live client. */
class ProfileSwitchTest
{
    @TempDir File directory;

    @Test
    void switchingReloadsEveryManagerWithoutWritingOldTimersIntoTheNewProfile() throws Exception
    {
        Harness h = new Harness(directory);
        ConfigManager configManager = h.configManager;
        Map<Long, Map<String, String>> profiles = h.profiles;
        GokIrlBankedXpPlugin plugin = h.plugin;
        IrlActionManager actions = h.actions;
        SkillLevelTracker levels = h.levels;
        XpMultiplierManager multipliers = h.multipliers;
        TimerManager timers = h.timers;
        BankedXpStore store = h.store;
        Gson gson = h.gson;
        GokIrlBankedXpConfig config = h.config;

        plugin.onProfileChanged(new ProfileChanged());
        IrlAction actionA = actions.createAction(action("A", "minute", 60));
        UUID timerA = timers.startTimer(actionA.getId()).orElseThrow();
        levels.recordExperience(Skill.AGILITY, 1000000);
        multipliers.setTiers(Skill.AGILITY, List.of(new XpMultiplierTier(1, 2)));
        store.save(Map.of(Skill.AGILITY, 123L));
        Map<String, String> savedA = new HashMap<>(profiles.get(1L));

        // Prepare B using separate managers, as if it was last used in an earlier session.
        h.useProfile(h.b);
        IrlActionManager seedActions = new IrlActionManager(configManager, gson);
        seedActions.loadActions();
        IrlAction actionB = seedActions.createAction(action("B", "second", 1));
        SkillLevelTracker seedLevels = new SkillLevelTracker(configManager, gson);
        seedLevels.recordExperience(Skill.AGILITY, 0);
        XpMultiplierManager seedMultipliers = new XpMultiplierManager(configManager, config, seedLevels, gson);
        seedMultipliers.setTiers(Skill.AGILITY, List.of(new XpMultiplierTier(1, 3)));
        new BankedXpStore(configManager, gson, directory).save(Map.of(Skill.AGILITY, 456L));
        // Equal config balance strings must not suppress restoring B's newer local file.
        profiles.get(2L).put("gokirlbankedxp.storedSkillXp", "AGILITY:123");
        profiles.get(2L).put("gokirlbankedxp.storedSkillXpSavedAt", "0");

        Map<String, String> beforeTransition = new HashMap<>(profiles.get(2L));
        for (int i = 0; i < 10; i++) timers.tick();
        timers.shutDown();
        assertEquals(0L, plugin.addManualXp(Skill.AGILITY, 100L));
        assertEquals(beforeTransition, profiles.get(2L), "Old timers cannot write in the event-delivery gap");
        ConfigChanged keyEvent = new ConfigChanged();
        keyEvent.setGroup(GokIrlBankedXpConfig.GROUP);
        keyEvent.setKey(BankedXpStore.XP_KEY);
        keyEvent.setNewValue("AGILITY:123");
        plugin.onConfigChanged(keyEvent);
        plugin.onProfileChanged(new ProfileChanged());
        assertEquals(List.of(actionB.getId()), List.of(actions.getAllActions().get(0).getId()));
        assertEquals(Map.of("second", 1L), actions.getSavedUnits());
        assertTrue(timers.getActiveTimers().isEmpty());
        assertEquals(1, levels.getLevel(Skill.AGILITY));
        assertEquals(3.0, multipliers.currentMultiplier(Skill.AGILITY));
        assertEquals(456L, plugin.getBankedXp(Skill.AGILITY));
        assertEquals(savedA, profiles.get(1L));

        // Switching back recovers A's timer and terms rather than B's action library.
        h.useProfile(h.a);
        plugin.onProfileChanged(new ProfileChanged());
        assertEquals(actionA.getId(), actions.getAllActions().get(0).getId());
        assertEquals(timerA, timers.getActiveTimers().get(0).getId());
        assertTrue(levels.getLevel(Skill.AGILITY) > 1);
        assertEquals(2.0, multipliers.currentMultiplier(Skill.AGILITY));
        assertEquals(123L, plugin.getBankedXp(Skill.AGILITY));
        SwingUtilities.invokeAndWait(() -> {});
        verify(h.panel, atLeast(3)).refreshActions();
    }

    /**
     * Levels belong to the logged-in character, not to the config profile. A
     * profile that has never seen this character would otherwise report level 1
     * for every skill, and the first deposit after a switch would be multiplied
     * as though the player were brand new.
     */
    @Test
    void switchingProfilesKeepsTheLevelsSeenThisSession() throws Exception
    {
        Harness h = new Harness(directory);
        h.plugin.onProfileChanged(new ProfileChanged());

        // The plugin observes the character's Agility XP in-game while on profile A.
        int agilityXp = Experience.getXpForLevel(80);
        h.plugin.onStatChanged(new StatChanged(Skill.AGILITY, agilityXp, 80, 80));
        h.plugin.onStatChanged(new StatChanged(Skill.AGILITY, agilityXp, 80, 80));
        assertEquals(80, h.levels.getLevel(Skill.AGILITY));

        // Profile B has no saved levels at all.
        h.useProfile(h.b);
        h.plugin.onProfileChanged(new ProfileChanged());

        assertEquals(80, h.levels.getLevel(Skill.AGILITY));
        assertTrue(h.levels.hasObserved(Skill.AGILITY));
    }

    private static IrlAction action(String name, String unit, long seconds)
    {
        return IrlAction.builder().name(name).unitName(unit).secondsPerUnit(seconds)
            .defaultXpPerUnit(10).skillMappings(Map.of(Skill.AGILITY, 10L)).build();
    }

    /**
     * A plugin and its services over a two-profile in-memory config manager.
     *
     * <p>Matches RuneLite injection while keeping UI and the live client out of
     * the fixture: the {@code @Inject} fields are set reflectively, which is
     * confined to test code the Plugin Hub never compiles.</p>
     */
    private static final class Harness
    {
        final ConfigManager configManager = mock(ConfigManager.class);
        final ConfigProfile a = mock(ConfigProfile.class);
        final ConfigProfile b = mock(ConfigProfile.class);
        final Map<Long, Map<String, String>> profiles = Map.of(1L, new HashMap<>(), 2L, new HashMap<>());
        final Gson gson = new Gson();
        final GokIrlBankedXpConfig config = mock(GokIrlBankedXpConfig.class);
        final GokIrlBankedXpPlugin plugin = new GokIrlBankedXpPlugin();
        final IrlActionManager actions;
        final SkillLevelTracker levels;
        final XpMultiplierManager multipliers;
        final TimerManager timers;
        final BankedXpStore store;
        final GokIrlXpPanel panel = mock(GokIrlXpPanel.class);

        Harness(File directory) throws Exception
        {
            when(a.getId()).thenReturn(1L);
            when(b.getId()).thenReturn(2L);
            // ConfigManager activates the new profile before emitting its change events.
            useProfile(a);
            when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(call ->
                profiles.get(configManager.getProfile().getId()).get(call.getArgument(0) + "." + call.getArgument(1)));
            doAnswer(call -> {
                profiles.get(configManager.getProfile().getId()).put(
                    call.getArgument(0) + "." + call.getArgument(1), String.valueOf((Object) call.getArgument(2)));
                return null;
            }).when(configManager).setConfiguration(anyString(), anyString(), any());

            when(config.levelMultipliersEnabled()).thenReturn(true);
            actions = new IrlActionManager(configManager, gson);
            levels = new SkillLevelTracker(configManager, gson);
            multipliers = new XpMultiplierManager(configManager, config, levels, gson);
            timers = new TimerManager(configManager, actions, plugin, null, gson);
            store = new BankedXpStore(configManager, gson, directory);
            inject(plugin, "configManager", configManager);
            inject(plugin, "config", config);
            inject(plugin, "irlActionManager", actions);
            inject(plugin, "skillLevelTracker", levels);
            inject(plugin, "xpMultiplierManager", multipliers);
            inject(plugin, "timerManager", timers);
            inject(plugin, "bankedXpStore", store);
            inject(plugin, "depletionForecaster", new DepletionForecaster());
            inject(plugin, "panel", panel);
        }

        void useProfile(ConfigProfile profile)
        {
            when(configManager.getProfile()).thenReturn(profile);
        }

        private static void inject(GokIrlBankedXpPlugin plugin, String name, Object value) throws Exception
        {
            Field field = GokIrlBankedXpPlugin.class.getDeclaredField(name);
            field.setAccessible(true);
            field.set(plugin, value);
        }
    }
}

package com.gokirlbankedxp.reporting;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.RuneLite;

/** Local, explicitly saved report text; deliberately outside synced RuneLite config. */
@Singleton
public final class BugReportDraftStore
{
    private final Gson gson;
    private final Path file;

    @Inject
    public BugReportDraftStore(Gson gson)
    {
        this(gson, RuneLite.RUNELITE_DIR.toPath().resolve("gok-irl-xp/report-draft.json"));
    }

    public BugReportDraftStore(Gson gson, Path file)
    {
        this.gson = gson;
        this.file = file;
    }

    public synchronized BugReport load() throws IOException
    {
        if (!Files.exists(file))
        {
            return BugReport.empty();
        }
        try (InputStream input = Files.newInputStream(file))
        {
            byte[] bytes = input.readNBytes(BugReport.MAX_BODY_BYTES + 1);
            if (bytes.length > BugReport.MAX_BODY_BYTES)
            {
                throw new IOException("Saved draft is too large.");
            }
            try
            {
                return BugReport.fromJson(gson.fromJson(new String(bytes, StandardCharsets.UTF_8), JsonObject.class));
            }
            catch (RuntimeException ex)
            {
                // Do not log free text, or replace an unreadable user's draft.
                throw new IOException("The saved draft could not be read.");
            }
        }
    }

    public synchronized void save(BugReport report) throws IOException
    {
        byte[] bytes = gson.toJson(report.toJson()).getBytes(StandardCharsets.UTF_8);
        if (bytes.length > BugReport.MAX_BODY_BYTES)
        {
            throw new IOException("Draft exceeds the report size limit.");
        }
        Files.createDirectories(file.getParent());
        Path temporary = Files.createTempFile(file.getParent(), "report-draft-", ".tmp");
        try
        {
            Files.write(temporary, bytes);
            // If atomic replacement is unavailable, preserve the previous draft
            // and surface failure instead of silently weakening recovery guarantees.
            Files.move(temporary, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        }
        finally
        {
            Files.deleteIfExists(temporary);
        }
    }

    public synchronized void clear() throws IOException
    {
        Files.deleteIfExists(file);
    }

    /** An old request must never delete a newer draft saved by another controller. */
    public synchronized void clearIfMatches(String submissionId) throws IOException
    {
        if (Files.exists(file) && load().getSubmissionId().equals(submissionId))
        {
            clear();
        }
    }
}

package com.gokirlbankedxp.reporting;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;
import net.runelite.client.RuneLiteProperties;

/**
 * Explicit, versioned report payload shared by the editor, preview and transport.
 * No game/account objects are reachable through this model. Blank drafts are
 * allowed; validateForSubmission is the boundary before any network request.
 */
public final class BugReport
{
    public static final int MAX_BODY_BYTES = 49152;
    public static final String FEATURE_REVISION = "native-reporting-v1";

    public enum Category
    {
        BANKED_XP("Banked XP"), ACTIONS("Actions and timers"),
        MULTIPLIERS("Level multipliers"), OTHER("Other");

        private final String label;

        Category(String label)
        {
            this.label = label;
        }

        @Override
        public String toString()
        {
            return label;
        }
    }

    private final String submissionId;
    private final Category category;
    private final String title;
    private final String description;
    private final String steps;
    private final String expectedResult;
    private final JsonObject diagnostics;

    public BugReport(String submissionId, Category category, String title,
        String description, String steps, String expectedResult, JsonObject diagnostics)
    {
        if (submissionId == null || !UUID.fromString(submissionId).toString().equals(submissionId)
            || UUID.fromString(submissionId).version() != 4 || UUID.fromString(submissionId).variant() != 2)
        {
            throw new IllegalArgumentException("Invalid report reference.");
        }
        if (category == null)
        {
            throw new IllegalArgumentException("Choose an affected area.");
        }
        checkText(title, 120, "Title");
        checkText(description, 4000, "What happened");
        checkText(steps, 4000, "Steps to reproduce");
        checkText(expectedResult, 2000, "Expected result");
        if (diagnostics != null)
        {
            requireFields(diagnostics, "featureRevision", "osName", "javaVersion", "runeLiteVersion");
            if (!FEATURE_REVISION.equals(readString(diagnostics, "featureRevision")))
            {
                throw new IllegalArgumentException("Unsupported report revision.");
            }
            for (String key : diagnostics.keySet())
            {
                checkText(readString(diagnostics, key), 100, key);
            }
        }
        this.submissionId = submissionId;
        this.category = category;
        this.title = title;
        this.description = description;
        this.steps = steps;
        this.expectedResult = expectedResult;
        this.diagnostics = diagnostics == null ? null : diagnostics.deepCopy();
    }

    public static BugReport empty()
    {
        return new BugReport(UUID.randomUUID().toString(), Category.OTHER, "", "", "", "", null);
    }

    /** Only these three documented platform/version accessors are read, on opt-in. */
    public static JsonObject collectDiagnostics()
    {
        JsonObject data = new JsonObject();
        data.addProperty("featureRevision", FEATURE_REVISION);
        data.addProperty("osName", System.getProperty("os.name", "Unknown"));
        data.addProperty("javaVersion", System.getProperty("java.version", "Unknown"));
        String version = RuneLiteProperties.getVersion();
        data.addProperty("runeLiteVersion", version == null ? "Unknown" : version);
        return data;
    }

    public void validateForSubmission()
    {
        if (title.isBlank() || description.isBlank())
        {
            throw new IllegalArgumentException("Enter a title and describe what happened.");
        }
    }

    private static void checkText(String text, int limit, String name)
    {
        if (text == null || text.length() > limit)
        {
            throw new IllegalArgumentException(name + " must be at most " + limit + " characters.");
        }
        // JSON encoders must not disagree about unpaired UTF-16 surrogates.
        for (int i = 0; i < text.length(); i++)
        {
            char c = text.charAt(i);
            if (Character.isHighSurrogate(c))
            {
                if (++i == text.length() || !Character.isLowSurrogate(text.charAt(i)))
                {
                    throw new IllegalArgumentException(name + " contains an incomplete character.");
                }
            }
            else if (Character.isLowSurrogate(c))
            {
                throw new IllegalArgumentException(name + " contains an incomplete character.");
            }
        }
    }

    /** Each wire field is added deliberately; no reflective object graph export. */
    public JsonObject toJson()
    {
        JsonObject json = new JsonObject();
        json.addProperty("schemaVersion", 1);
        json.addProperty("submissionId", submissionId);
        json.addProperty("category", category.name());
        json.addProperty("title", title);
        json.addProperty("description", description);
        json.addProperty("steps", steps);
        json.addProperty("expectedResult", expectedResult);
        if (diagnostics != null)
        {
            json.add("diagnostics", diagnostics.deepCopy());
        }
        return json;
    }

    /** Saved drafts use the wire schema; unexpected fields/types never enter the UI. */
    public static BugReport fromJson(JsonObject json)
    {
        Set<String> fields = new HashSet<>(Arrays.asList("schemaVersion", "submissionId",
            "category", "title", "description", "steps", "expectedResult"));
        if (json.has("diagnostics"))
        {
            fields.add("diagnostics");
        }
        if (!json.keySet().equals(fields) || !json.get("schemaVersion").isJsonPrimitive()
            || !json.getAsJsonPrimitive("schemaVersion").isNumber()
            || !"1".equals(json.get("schemaVersion").getAsString()))
        {
            throw new IllegalArgumentException("Unsupported draft format.");
        }
        JsonObject details = null;
        if (json.has("diagnostics"))
        {
            if (!json.get("diagnostics").isJsonObject())
            {
                throw new IllegalArgumentException("Invalid technical details.");
            }
            details = json.getAsJsonObject("diagnostics");
        }
        return new BugReport(readString(json, "submissionId"),
            Category.valueOf(readString(json, "category")), readString(json, "title"),
            readString(json, "description"), readString(json, "steps"),
            readString(json, "expectedResult"), details);
    }

    private static void requireFields(JsonObject json, String... fields)
    {
        if (!json.keySet().equals(new HashSet<>(Arrays.asList(fields))))
        {
            throw new IllegalArgumentException("Unexpected technical details.");
        }
    }

    static String readString(JsonObject json, String field)
    {
        JsonElement value = json.get(field);
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isString())
        {
            throw new IllegalArgumentException("Invalid report field: " + field);
        }
        return value.getAsString();
    }

    public String getSubmissionId() { return submissionId; }
    public Category getCategory() { return category; }
    public String getTitle() { return title; }
    public String getDescription() { return description; }
    public String getSteps() { return steps; }
    public String getExpectedResult() { return expectedResult; }
    public JsonObject getDiagnostics() { return diagnostics == null ? null : diagnostics.deepCopy(); }
}

package com.gokirlbankedxp.reporting;

import java.awt.Component;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JDialog;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import okhttp3.Call;

/**
 * Owns the reporting window and its asynchronous side effects. All mutable UI
 * state is confined to the EDT; local disk work uses RuneLite's shared executor.
 * Closing a window does not erase its in-memory text or claim to unsend a report.
 */
@Singleton
public final class BugReportController
{
    private final BugReportClient client;
    private final BugReportDraftStore drafts;
    private final ScheduledExecutorService executor;
    private BugReportPanel panel;
    private JDialog window;
    private Call pendingCall;
    private boolean busy;
    private long lifecycle;

    @Inject
    public BugReportController(BugReportClient client, BugReportDraftStore drafts,
        ScheduledExecutorService executor)
    {
        this.client = client;
        this.drafts = drafts;
        this.executor = executor;
    }

    public void open(Component owner)
    {
        requireEdt();
        if (window != null)
        {
            window.toFront();
            window.requestFocus();
            return;
        }
        boolean firstOpen = panel == null;
        if (firstOpen)
        {
            panel = new BugReportPanel(client.isConfigured());
            panel.onSave(() -> save(false, false));
            panel.onSend(() -> save(true, false));
            panel.onDiscard(this::discard);
        }
        window = new JDialog(SwingUtilities.getWindowAncestor(owner), "IRL XP — Report a bug",
            Dialog.ModalityType.MODELESS);
        window.setDefaultCloseOperation(JDialog.DO_NOTHING_ON_CLOSE);
        window.setContentPane(panel);
        window.setMinimumSize(new Dimension(520, 480));
        window.setSize(620, 760);
        window.setLocationRelativeTo(owner);
        window.addWindowListener(new WindowAdapter()
        {
            @Override
            public void windowClosing(WindowEvent event)
            {
                requestClose();
            }
        });
        window.setVisible(true);
        if (firstOpen)
        {
            setBusy(true, "Loading saved draft…");
            executor.execute(() ->
            {
                try
                {
                    BugReport restored = drafts.load();
                    SwingUtilities.invokeLater(() ->
                    {
                        panel.load(restored);
                        setBusy(false, client.isConfigured() ? "Nothing is sent until you review and confirm."
                            : "Reporting is not available yet. You can save a local draft.");
                    });
                }
                catch (IOException ex)
                {
                    SwingUtilities.invokeLater(() -> setBusy(false,
                        "The saved draft could not be read. It has been kept on disk. Saving a new draft will replace it."));
                }
            });
        }
    }

    private void save(boolean send, boolean closeAfter)
    {
        if (busy)
        {
            return;
        }
        final BugReport report;
        try
        {
            report = panel.snapshot();
            if (send)
            {
                report.validateForSubmission();
            }
        }
        catch (IllegalArgumentException ex)
        {
            panel.status(ex.getMessage());
            return;
        }
        final long startedAt = lifecycle;
        setBusy(true, send ? "Saving recovery copy…" : "Saving draft on this computer…");
        executor.execute(() ->
        {
            try
            {
                drafts.save(report);
                SwingUtilities.invokeLater(() ->
                {
                    panel.markSaved();
                    if (send && startedAt == lifecycle && window != null)
                    {
                        submit(report);
                    }
                    else
                    {
                        setBusy(false, "Draft saved on this computer. Nothing was sent.");
                        if (closeAfter && startedAt == lifecycle)
                        {
                            closeWindow();
                        }
                    }
                });
            }
            catch (IOException ex)
            {
                SwingUtilities.invokeLater(() -> setBusy(false,
                    "Could not save the draft. Your text is still here; nothing was sent."));
            }
        });
    }

    private void submit(BugReport report)
    {
        setBusy(true, "Sending report… Closing this window cannot undo server acceptance.");
        try
        {
            pendingCall = client.submit(report,
                outcome -> SwingUtilities.invokeLater(() -> completed(report, outcome)));
        }
        catch (RuntimeException ex)
        {
            setBusy(false, "Could not start submission. Your draft is saved; try again later.");
        }
    }

    private void completed(BugReport report, BugReportClient.Outcome outcome)
    {
        pendingCall = null;
        if (outcome == BugReportClient.Outcome.ACCEPTED)
        {
            // Keep the form locked until deletion finishes, so new text cannot be
            // cleared by completion of the old report. Store also compares IDs.
            executor.execute(() ->
            {
                boolean removed;
                try
                {
                    drafts.clearIfMatches(report.getSubmissionId());
                    removed = true;
                }
                catch (IOException ex)
                {
                    removed = false;
                }
                final boolean cleared = removed;
                SwingUtilities.invokeLater(() ->
                {
                    panel.load(BugReport.empty());
                    // Shown only after the server's receipt echoed this exact ID, so
                    // "submitted successfully" is a verified claim, not an optimistic one.
                    setBusy(false, "Thanks! Your bug report was submitted successfully. Reference: "
                        + report.getSubmissionId()
                        + (cleared ? "" : ". The local recovery copy could not be deleted; use Discard draft to remove it."));
                });
            });
            return;
        }
        String message;
        switch (outcome)
        {
            case INVALID:
                message = "The service rejected the report. Your draft is saved; review the text and its length.";
                break;
            case RATE_LIMITED:
                message = "The report limit was reached. Your draft is saved; try again later.";
                break;
            case UNAVAILABLE:
                message = "Reporting is temporarily unavailable. Your draft is saved; try again later.";
                break;
            case CONFLICT:
                message = "This reference belongs to different report text. Your draft is saved. "
                    + "Review and edit it to create a new report; an earlier version may already be accepted.";
                break;
            default:
                message = "Acceptance could not be confirmed. Your draft is saved. Retry unchanged to check the same report; "
                    + "editing it creates a new report that could duplicate an accepted one.";
                break;
        }
        setBusy(false, message);
    }

    private void discard()
    {
        if (busy || JOptionPane.showConfirmDialog(window, "Delete the saved draft and clear this form?",
            "Discard bug report", JOptionPane.OK_CANCEL_OPTION) != JOptionPane.OK_OPTION)
        {
            return;
        }
        setBusy(true, "Removing draft…");
        executor.execute(() ->
        {
            try
            {
                drafts.clear();
                SwingUtilities.invokeLater(() ->
                {
                    panel.load(BugReport.empty());
                    setBusy(false, "Draft removed.");
                });
            }
            catch (IOException ex)
            {
                SwingUtilities.invokeLater(() -> setBusy(false, "Could not remove the saved draft. Your text is still here."));
            }
        });
    }

    private void requestClose()
    {
        if (busy)
        {
            if (JOptionPane.showConfirmDialog(window,
                "Work is still in progress. Closing cannot undo a report already accepted. Close anyway?",
                "Close report window", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
            {
                closeWindow();
            }
            return;
        }
        if (panel.isDirty())
        {
            Object[] choices = {"Save draft", "Discard changes", "Cancel"};
            int choice = JOptionPane.showOptionDialog(window,
                "Save this report on this computer before closing?", "Unfinished report",
                JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE, null, choices, choices[0]);
            if (choice == 0)
            {
                save(false, true);
                return;
            }
            if (choice != 1)
            {
                return;
            }
            // Reload the explicitly saved draft next time; discarded unsaved text
            // must not reappear just because the singleton controller survived.
            panel = null;
        }
        closeWindow();
    }

    private void setBusy(boolean busy, String message)
    {
        this.busy = busy;
        panel.setBusy(busy);
        panel.status(message);
    }

    private void closeWindow()
    {
        lifecycle++;
        if (pendingCall != null)
        {
            pendingCall.cancel();
        }
        if (window != null)
        {
            window.dispose();
            window = null;
        }
    }

    /** Called through the existing panel shutdown path on the EDT. */
    public void shutDown()
    {
        requireEdt();
        closeWindow();
    }

    private static void requireEdt()
    {
        if (!SwingUtilities.isEventDispatchThread())
        {
            throw new IllegalStateException("Report UI must be used on the Swing event thread.");
        }
    }
}

package com.gokirlbankedxp.reporting;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** User-initiated HTTPS transport. It never starts requests during construction/startup. */
@Singleton
public final class BugReportClient
{
    // Public receiver URL only. Delivery credentials exist exclusively on Railway.
    private static final String ENDPOINT = "https://receiver-production-5b81.up.railway.app/v1/reports";
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private final OkHttpClient client;
    private final Gson gson;
    private final HttpUrl endpoint;

    public enum Outcome
    {
        ACCEPTED, INVALID, CONFLICT, RATE_LIMITED, UNAVAILABLE, UNKNOWN
    }

    @Inject
    public BugReportClient(OkHttpClient client, Gson gson)
    {
        this(client, gson, ENDPOINT);
    }

    /** Explicit endpoint injection permits isolated HTTPS transport tests. */
    public BugReportClient(OkHttpClient client, Gson gson, String endpoint)
    {
        this.client = client.newBuilder().followRedirects(false).followSslRedirects(false)
            .retryOnConnectionFailure(false).callTimeout(20, TimeUnit.SECONDS).build();
        this.gson = gson;
        this.endpoint = endpoint.isEmpty() ? null : HttpUrl.parse(endpoint);
        if (!endpoint.isEmpty() && (this.endpoint == null || !this.endpoint.isHttps()
            || !this.endpoint.username().isEmpty() || !this.endpoint.password().isEmpty()
            || this.endpoint.fragment() != null || this.endpoint.query() != null))
        {
            throw new IllegalArgumentException("Reporting requires a fixed HTTPS endpoint without credentials.");
        }
    }

    public boolean isConfigured()
    {
        return endpoint != null;
    }

    public Call submit(BugReport report, Consumer<Outcome> completion)
    {
        if (!isConfigured())
        {
            throw new IllegalStateException("Reporting is not available yet.");
        }
        report.validateForSubmission();
        byte[] payload = gson.toJson(report.toJson()).getBytes(StandardCharsets.UTF_8);
        if (payload.length > BugReport.MAX_BODY_BYTES)
        {
            throw new IllegalArgumentException("Report is too large. Shorten the text and try again.");
        }
        Request request = new Request.Builder().url(endpoint)
            .header("Accept", "application/json")
            .post(RequestBody.create(JSON, payload)).build();
        Call call = client.newCall(request);
        call.enqueue(new Callback()
        {
            @Override
            public void onFailure(Call ignored, IOException error)
            {
                // A timeout/cancellation cannot prove the server did not accept it.
                completion.accept(Outcome.UNKNOWN);
            }

            @Override
            public void onResponse(Call ignored, Response response)
            {
                Outcome outcome;
                try (Response closed = response)
                {
                    outcome = readOutcome(report, response);
                }
                catch (IOException | RuntimeException ex)
                {
                    outcome = Outcome.UNKNOWN;
                }
                completion.accept(outcome);
            }
        });
        return call;
    }

    private Outcome readOutcome(BugReport report, Response response) throws IOException
    {
        switch (response.code())
        {
            case 400:
            case 413:
            case 415:
                return Outcome.INVALID;
            case 429:
                return Outcome.RATE_LIMITED;
            case 409:
                return Outcome.CONFLICT;
            case 503:
                return Outcome.UNAVAILABLE;
            case 202:
                break;
            default:
                return Outcome.UNKNOWN;
        }
        ResponseBody body = response.body();
        if (body == null)
        {
            return Outcome.UNKNOWN;
        }
        byte[] bytes = body.byteStream().readNBytes(4097);
        if (bytes.length > 4096)
        {
            return Outcome.UNKNOWN;
        }
        JsonObject receipt = new JsonObject();
        try (JsonReader reader = new JsonReader(new StringReader(new String(bytes, StandardCharsets.UTF_8))))
        {
            // Streaming strict parsing also rejects duplicate fields and avoids
            // constructing arbitrary nested trees from an untrusted response.
            reader.setLenient(false);
            Set<String> seen = new HashSet<>();
            reader.beginObject();
            while (reader.hasNext())
            {
                String field = reader.nextName();
                if (!seen.add(field))
                {
                    return Outcome.UNKNOWN;
                }
                if (field.equals("submissionId") || field.equals("reference") || field.equals("status"))
                {
                    if (reader.peek() != JsonToken.STRING)
                    {
                        return Outcome.UNKNOWN;
                    }
                    receipt.addProperty(field, reader.nextString());
                }
                else
                {
                    reader.skipValue();
                }
            }
            reader.endObject();
            if (reader.peek() != JsonToken.END_DOCUMENT)
            {
                return Outcome.UNKNOWN;
            }
        }
        // Only these typed fields determine acceptance. Extra response fields are
        // intentionally ignored and never shown, logged, or persisted.
        return report.getSubmissionId().equals(BugReport.readString(receipt, "submissionId"))
            && report.getSubmissionId().equals(BugReport.readString(receipt, "reference"))
            && "accepted".equals(BugReport.readString(receipt, "status"))
            ? Outcome.ACCEPTED : Outcome.UNKNOWN;
    }
}

package com.gokirlbankedxp.reporting;

import com.gokirlbankedxp.ui.IrlXpUi;
import com.google.gson.JsonObject;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.GridLayout;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.awt.Point;
import java.awt.Component;
import java.util.UUID;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingUtilities;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.text.JTextComponent;

/** Headless-testable native form. The controller owns persistence and network effects. */
public final class BugReportPanel extends JPanel
{
    private final JTextField title = new JTextField();
    private final JComboBox<BugReport.Category> category = new JComboBox<>(BugReport.Category.values());
    private final JTextArea description = textArea(5);
    private final JTextArea steps = textArea(4);
    private final JTextArea expected = textArea(3);
    private final JCheckBox details = new JCheckBox("Include technical details (preview before sending)");
    private final JTextArea preview = textArea(16);
    private final JTextArea status = IrlXpUi.wrappingNote("", 3);
    private final JButton review = new JButton("Review report");
    private final JButton send = new JButton("Send report");
    private final JButton edit = new JButton("Back to editing");
    private final JButton save = new JButton("Save draft");
    private final JButton discard = new JButton("Discard draft");
    private final JCheckBox consent = new JCheckBox("Send this report to the developer's private inbox");
    private final CardLayout cards = new CardLayout();
    private final JPanel pages = new JPanel(cards);
    private final JScrollPane formScroll;
    private final boolean configured;
    private BugReport current = BugReport.empty();
    private JsonObject selectedDiagnostics;
    private boolean dirty;

    public BugReportPanel(boolean configured)
    {
        this.configured = configured;
        setLayout(new BorderLayout(10, 10));
        setBackground(IrlXpUi.BACKGROUND);
        setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        JPanel form = new Form();
        form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
        form.setBackground(IrlXpUi.BACKGROUND);
        form.add(IrlXpUi.sectionTitle("Tell us what went wrong"));
        form.add(Box.createVerticalStrut(8));
        form.add(IrlXpUi.wrappingNote("No account or contact details needed. Please leave out passwords, "
            + "account names and other personal information.", 2));
        addField(form, "Title (required)", title, 120);
        addField(form, "Affected area", category, 0);
        category.setRenderer(new DefaultListCellRenderer()
        {
            @Override
            public Component getListCellRendererComponent(javax.swing.JList<?> list,
                Object value, int index, boolean selected, boolean focused)
            {
                super.getListCellRendererComponent(list, value, index, selected, focused);
                setBackground(selected ? IrlXpUi.SELECTION : IrlXpUi.INPUT_BACKGROUND);
                setForeground(IrlXpUi.TEXT);
                return this;
            }
        });
        addField(form, "What happened? (required)", description, 4000);
        addField(form, "Steps to reproduce (optional)", steps, 4000);
        addField(form, "What did you expect? (optional)", expected, 2000);
        details.setOpaque(false);
        details.setForeground(IrlXpUi.TEXT);
        form.add(details);
        form.add(IrlXpUi.wrappingNote("Saved drafts stay on this computer. Sending saves a local recovery "
            + "copy until acceptance. Save unfinished text before disabling the plugin or closing RuneLite.", 3));
        for (Component child : form.getComponents())
        {
            if (child instanceof JComponent)
            {
                ((JComponent) child).setAlignmentX(LEFT_ALIGNMENT);
            }
        }
        formScroll = new JScrollPane(form);
        formScroll.setBorder(null);
        formScroll.getViewport().setBackground(IrlXpUi.BACKGROUND);
        formScroll.getVerticalScrollBar().setUnitIncrement(16);
        pages.setBackground(IrlXpUi.BACKGROUND);
        pages.add(formScroll, "edit");

        JPanel reviewPage = new JPanel(new BorderLayout(8, 8));
        reviewPage.setOpaque(false);
        reviewPage.add(IrlXpUi.wrappingNote("This exact report goes through the IRL XP reporting service "
            + "on Railway to the developer's private GitHub inbox. Railway processes your connection's IP address. "
            + "No logs, screenshots, or game/account data are attached automatically. "
            + "Sending saves a local recovery copy until acceptance.", 5), BorderLayout.NORTH);
        preview.setEditable(false);
        IrlXpUi.styleField(preview);
        preview.setName("reportPreview");
        reviewPage.add(new JScrollPane(preview), BorderLayout.CENTER);
        consent.setOpaque(false);
        consent.setForeground(IrlXpUi.TEXT);
        reviewPage.add(consent, BorderLayout.SOUTH);
        pages.add(reviewPage, "review");
        add(pages, BorderLayout.CENTER);

        JPanel footer = new JPanel(new BorderLayout(6, 6));
        footer.setOpaque(false);
        footer.add(status, BorderLayout.NORTH);
        JPanel buttons = new JPanel(new GridLayout(2, 3, 6, 6));
        buttons.setOpaque(false);
        for (JButton button : new JButton[]{save, discard, review, edit, send})
        {
            IrlXpUi.styleSecondaryButton(button);
            buttons.add(button);
        }
        IrlXpUi.stylePrimaryButton(review);
        IrlXpUi.stylePrimaryButton(send);
        footer.add(buttons, BorderLayout.CENTER);
        add(footer, BorderLayout.SOUTH);
        review.addActionListener(event -> showReview());
        edit.addActionListener(event -> showEditor());
        consent.addActionListener(event -> send.setEnabled(configured && consent.isSelected()));
        details.addActionListener(event ->
        {
            selectedDiagnostics = details.isSelected() ? BugReport.collectDiagnostics() : null;
            dirty = true;
        });
        category.addActionListener(event -> dirty = true);
        load(BugReport.empty());
    }

    private static JTextArea textArea(int rows)
    {
        JTextArea area = new JTextArea(rows, 35);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setFont(new JLabel().getFont());
        return area;
    }

    private void addField(JPanel form, String label, JComponent input, int limit)
    {
        JPanel row = new JPanel(new BorderLayout(0, 4));
        row.setOpaque(false);
        row.setBorder(BorderFactory.createEmptyBorder(8, 0, 2, 0));
        JLabel heading = new JLabel(label);
        heading.setForeground(IrlXpUi.TEXT);
        heading.setLabelFor(input);
        input.getAccessibleContext().setAccessibleName(label);
        IrlXpUi.styleField(input);
        row.add(heading, BorderLayout.NORTH);
        row.add(input instanceof JTextArea ? new JScrollPane(input) : input, BorderLayout.CENTER);
        if (input instanceof JTextComponent)
        {
            JTextComponent text = (JTextComponent) input;
            JLabel count = IrlXpUi.mutedLabel("0 / " + limit);
            row.add(count, BorderLayout.SOUTH);
            text.getDocument().addDocumentListener(new DocumentListener()
            {
                private void changed()
                {
                    dirty = true;
                    count.setText(text.getDocument().getLength() + " / " + limit);
                    count.setForeground(text.getDocument().getLength() > limit ? IrlXpUi.DANGER : IrlXpUi.MUTED_TEXT);
                }

                @Override public void insertUpdate(DocumentEvent event) { changed(); }
                @Override public void removeUpdate(DocumentEvent event) { changed(); }
                @Override public void changedUpdate(DocumentEvent event) { changed(); }
            });
        }
        form.add(row);
    }

    public void load(BugReport report)
    {
        current = report;
        title.setText(report.getTitle());
        category.setSelectedItem(report.getCategory());
        description.setText(report.getDescription());
        steps.setText(report.getSteps());
        expected.setText(report.getExpectedResult());
        selectedDiagnostics = report.getDiagnostics();
        details.setSelected(selectedDiagnostics != null);
        dirty = false;
        showEditor();
        // JTextArea caret updates can scroll the parent to the last populated
        // field. Restore the beginning after layout so the title is always visible.
        SwingUtilities.invokeLater(() -> formScroll.getViewport().setViewPosition(new Point(0, 0)));
    }

    /** Preserve the UUID for identical retries, including after draft restoration. */
    public BugReport snapshot()
    {
        BugReport candidate = new BugReport(current.getSubmissionId(),
            (BugReport.Category) category.getSelectedItem(), title.getText(), description.getText(),
            steps.getText(), expected.getText(), selectedDiagnostics);
        if (!candidate.toJson().equals(current.toJson()))
        {
            candidate = new BugReport(UUID.randomUUID().toString(), candidate.getCategory(),
                candidate.getTitle(), candidate.getDescription(), candidate.getSteps(),
                candidate.getExpectedResult(), candidate.getDiagnostics());
        }
        current = candidate;
        return current;
    }

    private void showReview()
    {
        try
        {
            BugReport report = snapshot();
            report.validateForSubmission();
            // Render the same immutable report submitted by the controller as
            // readable plain text; no JSON or interpreted HTML in the user flow.
            StringBuilder text = new StringBuilder("Title: ").append(report.getTitle())
                .append("\nAffected area: ").append(report.getCategory())
                .append("\n\nWhat happened\n").append(report.getDescription())
                .append("\n\nSteps to reproduce\n").append(report.getSteps())
                .append("\n\nExpected result\n").append(report.getExpectedResult());
            JsonObject technical = report.getDiagnostics();
            if (technical != null)
            {
                text.append("\n\nTechnical details\nReporting revision: ")
                    .append(BugReport.readString(technical, "featureRevision"))
                    .append("\nOperating system: ").append(BugReport.readString(technical, "osName"))
                    .append("\nJava version: ").append(BugReport.readString(technical, "javaVersion"))
                    .append("\nRuneLite version: ").append(BugReport.readString(technical, "runeLiteVersion"));
            }
            text.append("\n\nReport reference: ").append(report.getSubmissionId())
                .append("\nReport format: 1");
            preview.setText(text.toString());
            preview.setCaretPosition(0);
            consent.setSelected(false);
            cards.show(pages, "review");
            review.setVisible(false);
            edit.setVisible(true);
            send.setVisible(true);
            send.setEnabled(false);
            status(configured ? "Review the report, then confirm below to send it."
                : "Reporting is not available yet. You can save a local draft.");
        }
        catch (IllegalArgumentException ex)
        {
            status(ex.getMessage());
        }
    }

    private void showEditor()
    {
        cards.show(pages, "edit");
        review.setVisible(true);
        edit.setVisible(false);
        send.setVisible(false);
        consent.setSelected(false);
        send.setEnabled(false);
        status(configured ? "Nothing is sent until you review and confirm."
            : "Reporting is not available yet. You can save a local draft.");
    }

    public void setBusy(boolean busy)
    {
        for (JComponent control : new JComponent[]{title, category, description, steps, expected,
            details, review, edit, save, discard, consent})
        {
            control.setEnabled(!busy);
        }
        send.setEnabled(!busy && configured && consent.isSelected());
    }

    public void status(String message) { status.setText(message); }
    public boolean isDirty() { return dirty; }
    public void markSaved() { dirty = false; }
    public void onSave(Runnable action) { save.addActionListener(event -> action.run()); }
    public void onDiscard(Runnable action) { discard.addActionListener(event -> action.run()); }
    public void onSend(Runnable action) { send.addActionListener(event -> action.run()); }

    /** Track the viewport width so wrapped notes never force horizontal scrolling. */
    private static final class Form extends JPanel implements Scrollable
    {
        @Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
        @Override public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction) { return 16; }
        @Override public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
        {
            return Math.max(16, visible.height - 16);
        }
        @Override public boolean getScrollableTracksViewportWidth() { return true; }
        @Override public boolean getScrollableTracksViewportHeight() { return false; }
    }
}

package com.gokirlbankedxp.model;

public enum TimeUnit
{
    SECONDS(1, "Seconds"),
    MINUTES(60, "Minutes"),
    HOURS(3600, "Hours");

    private final long secondsPerUnit;
    private final String displayName;

    TimeUnit(long secondsPerUnit, String displayName)
    {
        this.secondsPerUnit = secondsPerUnit;
        this.displayName = displayName;
    }

    public long toSeconds(long amount)
    {
        if (amount <= 0)
        {
            return 0L;
        }

        return Math.multiplyExact(amount, secondsPerUnit);
    }

    public long fromSeconds(long seconds)
    {
        if (seconds <= 0)
        {
            return 0L;
        }

        return seconds / secondsPerUnit;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public long getSecondsPerUnit()
    {
        return secondsPerUnit;
    }
}

package com.gokirlbankedxp.model;

import java.util.Collections;
import java.util.Map;
import java.util.UUID;
import net.runelite.api.Skill;

public class ActiveTimer
{
    private final UUID id;
    private final UUID actionId;
    private long elapsedSeconds;
    private boolean paused;
    private long lastTickMillis;
    private long awardedUnits;
    /** Frozen earning terms: editing an action must not reinterpret time already paid. */
    private IrlAction actionSnapshot;

    public IrlAction getActionSnapshot()
    {
        return actionSnapshot;
    }

    /** Bind once; also used to migrate timers saved before snapshots existed. */
    public void bindAction(IrlAction action)
    {
        if (actionSnapshot == null)
        {
            actionSnapshot = action;
        }
    }

    public ActiveTimer(UUID id, UUID actionId, long elapsedSeconds, boolean paused, long lastTickMillis, long awardedUnits)
    {
        this.id = id == null ? UUID.randomUUID() : id;
        this.actionId = actionId;
        this.elapsedSeconds = Math.max(0, elapsedSeconds);
        this.paused = paused;
        this.lastTickMillis = lastTickMillis;
        this.awardedUnits = Math.max(0, awardedUnits);
    }

    public static ActiveTimer start(UUID actionId, long nowMillis)
    {
        return new ActiveTimer(UUID.randomUUID(), actionId, 0L, false, nowMillis, 0L);
    }

    public UUID getId()
    {
        return id;
    }

    public UUID getActionId()
    {
        return actionId;
    }

    public boolean isPaused()
    {
        return paused;
    }

    public long getElapsedSeconds()
    {
        return elapsedSeconds;
    }

    public long getDisplayElapsedSeconds(long nowMillis)
    {
        if (paused || lastTickMillis == 0)
        {
            return elapsedSeconds;
        }

        long delta = Math.max(0, (nowMillis - lastTickMillis) / 1000);
        return elapsedSeconds + delta;
    }

    public String getFormattedElapsedTime(long nowMillis)
    {
        long seconds = getDisplayElapsedSeconds(nowMillis);
        long hours = seconds / 3600;
        long minutes = (seconds % 3600) / 60;
        long secs = seconds % 60;
        return String.format("%02d:%02d:%02d", hours, minutes, secs);
    }

    public void pause(long nowMillis)
    {
        accrueElapsed(nowMillis);
        this.paused = true;
    }

    public void resume(long nowMillis)
    {
        this.paused = false;
        this.lastTickMillis = nowMillis;
    }

    public void alignAwardedUnits(long secondsPerUnit)
    {
        if (secondsPerUnit <= 0)
        {
            this.awardedUnits = 0;
            return;
        }

        this.awardedUnits = elapsedSeconds / secondsPerUnit;
    }

    public Map<Skill, Long> applyTick(long nowMillis, IrlAction action)
    {
        bindAction(action);
        action = actionSnapshot;
        if (action == null || paused)
        {
            lastTickMillis = nowMillis;
            return Collections.emptyMap();
        }

        long deltaSeconds = accrueElapsed(nowMillis);
        if (deltaSeconds == 0)
        {
            return Collections.emptyMap();
        }

        long unitSeconds = action.getSecondsPerUnit();
        if (unitSeconds <= 0)
        {
            return Collections.emptyMap();
        }

        long totalUnits = elapsedSeconds / unitSeconds;
        long newUnits = totalUnits - awardedUnits;
        if (newUnits <= 0)
        {
            return Collections.emptyMap();
        }

        awardedUnits += newUnits;
        // The units -> XP conversion lives on the action so that live timers and
        // manually logged sessions can never drift apart.
        return action.xpForUnits(newUnits);
    }

    /**
     * Commits whole elapsed seconds while retaining any millisecond remainder.
     * Advancing the anchor directly to {@code nowMillis} used to discard that
     * remainder on every scheduler tick and caused long-running timers to drift.
     */
    private long accrueElapsed(long nowMillis)
    {
        if (lastTickMillis == 0)
        {
            lastTickMillis = nowMillis;
            return 0L;
        }

        long deltaMillis = Math.max(0L, nowMillis - lastTickMillis);
        long deltaSeconds = deltaMillis / 1000L;
        if (deltaSeconds > 0)
        {
            elapsedSeconds += deltaSeconds;
            lastTickMillis += deltaSeconds * 1000L;
        }
        return deltaSeconds;
    }

    public ActiveTimer copy()
    {
        ActiveTimer copy = new ActiveTimer(id, actionId, elapsedSeconds, paused, lastTickMillis, awardedUnits);
        copy.bindAction(actionSnapshot);
        return copy;
    }
}

package com.gokirlbankedxp.model;

import com.google.common.math.LongMath;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;
import lombok.AccessLevel;
import lombok.Builder;
import lombok.Getter;
import net.runelite.api.Skill;

/**
 * A single user-defined real-world activity and the XP it is worth.
 *
 * <p>An action is either <em>timed</em> or <em>untimed</em>:</p>
 * <ul>
 *   <li><b>Timed</b> actions can be run on a live timer. {@code secondsPerUnit}
 *       says how much real time makes up one unit, so the timer knows when to
 *       award another unit's worth of XP.</li>
 *   <li><b>Untimed</b> actions are benchmark-style ("XP per pound lifted",
 *       "XP per kilometre run"). There is no meaningful duration for a unit, so
 *       {@code secondsPerUnit} is zero and the user banks XP by logging how many
 *       units they completed instead.</li>
 * </ul>
 */
@Getter
public class IrlAction
{
    private final UUID id;
    private final String name;
    /** User-defined unit label used in the action editor and timer summaries. */
    private final String unitName;
    /**
     * Exact timer interval represented by one unit. Zero for untimed actions,
     * which have no duration to convert.
     */
    private final long secondsPerUnit;
    /**
     * Boxed on purpose: Gson leaves it null for actions saved before untimed
     * actions existed, which lets {@link #isTimed()} tell "saved by an older
     * version" apart from "the user explicitly unticked Timed". Every legacy
     * action was timer-driven, so a null value migrates to timed.
     */
    @Getter(AccessLevel.NONE)
    private final Boolean timed;
    /**
     * Legacy field retained only so Gson can migrate actions saved by older
     * versions, where units were restricted to the TimeUnit enum.
     */
    private final TimeUnit timeUnit;
    private final long defaultXpPerUnit;
    private final Map<Skill, Long> skillMappings;

    @Builder(toBuilder = true)
    private IrlAction(
        UUID id,
        String name,
        String unitName,
        long secondsPerUnit,
        Boolean timed,
        TimeUnit timeUnit,
        long defaultXpPerUnit,
        Map<Skill, Long> skillMappings
    )
    {
        this.id = id == null ? UUID.randomUUID() : id;
        this.name = name == null ? "" : name.trim();
        String normalizedUnitName = unitName == null ? "" : unitName.trim();
        this.unitName = normalizedUnitName.isEmpty() && timeUnit != null
            ? timeUnit.getDisplayName()
            : normalizedUnitName;

        long resolvedSeconds = secondsPerUnit > 0
            ? secondsPerUnit
            : timeUnit == null ? 0L : timeUnit.getSecondsPerUnit();
        // A null flag means "not stated" and is resolved from the duration, which
        // is how pre-existing saved actions keep working. An explicit flag always
        // wins, and an untimed action never keeps a duration around to confuse
        // the timer code.
        boolean resolvedTimed = timed == null ? resolvedSeconds > 0 : timed;
        this.timed = resolvedTimed;
        this.secondsPerUnit = resolvedTimed ? resolvedSeconds : 0L;

        this.timeUnit = timeUnit;
        this.defaultXpPerUnit = defaultXpPerUnit;
        this.skillMappings = Collections.unmodifiableMap(sanitizeMappings(skillMappings));
    }

    public boolean isValid()
    {
        return !name.isEmpty()
            && !getUnitName().isEmpty()
            // Only timed actions need a duration; untimed ones are logged by hand.
            && (!isTimed() || getSecondsPerUnit() > 0)
            && defaultXpPerUnit > 0
            && !getSkillMappings().isEmpty();
    }

    /** Resolves legacy enum-backed actions even when Gson bypasses the constructor. */
    public String getUnitName()
    {
        if (unitName != null && !unitName.trim().isEmpty())
        {
            return unitName.trim();
        }
        return timeUnit == null ? "" : timeUnit.getDisplayName();
    }

    /**
     * True when this action can be run on a live timer.
     *
     * <p>Gson bypasses the constructor, so the legacy fallback lives here too:
     * an action persisted without the flag is timed exactly when it carries a
     * positive duration.</p>
     */
    public boolean isTimed()
    {
        if (timed != null)
        {
            return timed;
        }
        return resolveSecondsPerUnit() > 0;
    }

    /** Resolves legacy enum-backed actions even when Gson bypasses the constructor. */
    public long getSecondsPerUnit()
    {
        return isTimed() ? resolveSecondsPerUnit() : 0L;
    }

    public boolean hasSkillMapping(Skill skill)
    {
        return skill != null && getSkillMappings().containsKey(skill);
    }

    public long getXpForSkill(Skill skill)
    {
        if (skill == null)
        {
            return 0L;
        }

        Long override = getSkillMappings().get(skill);
        if (override != null && override > 0)
        {
            return override;
        }

        return Math.max(0L, defaultXpPerUnit);
    }

    /**
     * Converts a completed number of units into per-skill XP.
     *
     * <p>This is the single place that turns "units done" into "XP earned", used
     * both by the live timer as it accrues units and by manual logging of an
     * already-finished session, so the two paths can never disagree.</p>
     *
     * <p>Multiplication saturates rather than overflowing: an absurd unit count
     * clamps to {@link Long#MAX_VALUE} instead of silently wrapping negative.</p>
     */
    public Map<Skill, Long> xpForUnits(long units)
    {
        if (units <= 0)
        {
            return Collections.emptyMap();
        }

        Map<Skill, Long> xp = new EnumMap<>(Skill.class);
        for (Skill skill : getSkillMappings().keySet())
        {
            long rate = getXpForSkill(skill);
            if (rate > 0)
            {
                xp.put(skill, LongMath.saturatedMultiply(rate, units));
            }
        }
        return xp;
    }

    /** Never null, even for actions Gson deserialized without the field. */
    public Map<Skill, Long> getSkillMappings()
    {
        return skillMappings == null ? Collections.emptyMap() : skillMappings;
    }

    /** The stored duration, ignoring whether the action is actually timed. */
    private long resolveSecondsPerUnit()
    {
        if (secondsPerUnit > 0)
        {
            return secondsPerUnit;
        }
        return timeUnit == null ? 0L : timeUnit.getSecondsPerUnit();
    }

    private static Map<Skill, Long> sanitizeMappings(Map<Skill, Long> mappings)
    {
        if (mappings == null || mappings.isEmpty())
        {
            return Collections.emptyMap();
        }

        Map<Skill, Long> cleaned = new EnumMap<>(Skill.class);
        for (Map.Entry<Skill, Long> entry : mappings.entrySet())
        {
            Skill skill = entry.getKey();
            Long rate = entry.getValue();
            if (skill == null || rate == null || rate <= 0)
            {
                continue;
            }

            cleaned.put(skill, rate);
        }

        return cleaned;
    }

    public IrlAction ensureId(UUID fallbackId)
    {
        return id != null ? this : toBuilder().id(Objects.requireNonNull(fallbackId)).build();
    }
}

package com.gokirlbankedxp.model;

import java.util.Objects;
import net.runelite.api.Experience;

/**
 * One rung of a skill's level-based banking multiplier.
 *
 * <p>A tier says: "once this skill reaches {@code level}, multiply every XP
 * deposit for it by {@code multiplier}". Tiers deliberately do <em>not</em>
 * stack. Exactly one tier is ever in force — the highest one the player has
 * reached — so crossing into a new tier replaces the previous multiplier rather
 * than compounding with it. Below the lowest tier, XP is banked unchanged.</p>
 *
 * <p>Levels run to {@link Experience#MAX_VIRT_LEVEL} (126) rather than stopping
 * at 99, because levels here are derived from experience and keep climbing past
 * the in-game cap. A player who never passes 99 simply never sets a tier there.</p>
 *
 * <p>Immutable, and deliberately tolerant on the way in: Gson reconstructs saved
 * tiers by writing fields directly without running this constructor, so anything
 * read back from config is re-validated through {@link #isValid()} and
 * {@link #normalized()} rather than trusted.</p>
 */
public class XpMultiplierTier implements Comparable<XpMultiplierTier>
{
    /** The lowest level a tier can trigger at — level 1 means "always on". */
    public static final int MIN_LEVEL = 1;

    /** Virtual level ceiling, so tiers stay meaningful past 99. */
    public static final int MAX_LEVEL = Experience.MAX_VIRT_LEVEL;

    /**
     * Multipliers are non-negative by rule; zero is legal and means "bank
     * nothing for this skill at this level". The upper bound is not a game rule,
     * only a guard against a typo (a stray extra digit) silently banking an
     * absurd amount, and against overflow when scaling large deposits.
     */
    public static final double MIN_MULTIPLIER = 0.0;
    public static final double MAX_MULTIPLIER = 1000.0;

    private final int level;
    private final double multiplier;

    public XpMultiplierTier(int level, double multiplier)
    {
        this.level = level;
        this.multiplier = multiplier;
    }

    public int getLevel()
    {
        return level;
    }

    public double getMultiplier()
    {
        return multiplier;
    }

    /**
     * Whether this tier can be used as-is.
     *
     * <p>NaN and infinity are rejected explicitly: neither is caught by the range
     * comparisons below (every comparison against NaN is false), and either one
     * would turn a banked total into garbage.</p>
     */
    public boolean isValid()
    {
        if (Double.isNaN(multiplier) || Double.isInfinite(multiplier))
        {
            return false;
        }

        return level >= MIN_LEVEL
            && level <= MAX_LEVEL
            && multiplier >= MIN_MULTIPLIER
            && multiplier <= MAX_MULTIPLIER;
    }

    /**
     * The nearest usable tier to this one, clamped into range.
     *
     * <p>Used when loading saved data so a hand-edited or out-of-date config
     * yields a sane tier instead of being silently dropped. A multiplier that is
     * not a number at all has no nearest value, so it falls back to 1.0 — XP
     * banked unchanged, the same as having no tier.</p>
     */
    public XpMultiplierTier normalized()
    {
        int clampedLevel = Math.min(MAX_LEVEL, Math.max(MIN_LEVEL, level));
        double clampedMultiplier;
        if (Double.isNaN(multiplier))
        {
            clampedMultiplier = 1.0;
        }
        else
        {
            clampedMultiplier = Math.min(MAX_MULTIPLIER, Math.max(MIN_MULTIPLIER, multiplier));
        }

        return new XpMultiplierTier(clampedLevel, clampedMultiplier);
    }

    /** Sorted by the level they trigger at, which is the order they take effect in. */
    @Override
    public int compareTo(XpMultiplierTier other)
    {
        return Integer.compare(level, other.level);
    }

    @Override
    public boolean equals(Object other)
    {
        if (this == other)
        {
            return true;
        }
        if (!(other instanceof XpMultiplierTier))
        {
            return false;
        }
        XpMultiplierTier that = (XpMultiplierTier) other;
        return level == that.level && Double.compare(multiplier, that.multiplier) == 0;
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(level, multiplier);
    }

    @Override
    public String toString()
    {
        return "XpMultiplierTier{level=" + level + ", multiplier=" + multiplier + '}';
    }
}

