    /**
     * Repopulates both action drop-downs.
     *
     * <p>The timer selector lists only timed actions: an untimed one has no
     * seconds-per-unit, so a timer on it could never award anything. The log
     * selector lists everything, because recording completed units is valid for
     * a timed action too.</p>
     *
     * <p>Already on the EDT — both callers come through
     * {@link #refreshActionList()}'s invokeLater — so this must not queue another
     * round trip, or the selection restored below would be undone by the
     * listeners firing afterwards.</p>
     */
    private void refreshSelectors(List<IrlAction> actions)
    {
        UUID previouslyLogged = selectedActionId(logActionSelector);
        UUID previouslyTimed = selectedActionId(timerActionSelector);

        DefaultComboBoxModel<IrlAction> timerModel = new DefaultComboBoxModel<>();
        DefaultComboBoxModel<IrlAction> logModel = new DefaultComboBoxModel<>();
        for (IrlAction action : actions)
        {
            if (action.isTimed())
            {
                timerModel.addElement(action);
            }
            logModel.addElement(action);
        }

        // Both selectors keep the user's choice across a refresh. The list is
        // rebuilt after every create, edit and delete, and losing the chosen
        // timer action each time meant starting the wrong one after an edit.
        timerActionSelector.setModel(timerModel);
        restoreSelection(timerActionSelector, timerModel, previouslyTimed);

        logActionSelector.setModel(logModel);
        restoreSelection(logActionSelector, logModel, previouslyLogged);
        onLogSelectionChanged();
    }

    /** Keeps the user's chosen action selected across a list refresh. */
    private void restoreSelection(JComboBox<IrlAction> selector, DefaultComboBoxModel<IrlAction> model, UUID actionId)
    {
        if (model.getSize() == 0)
        {
            return;
        }

        for (int i = 0; i < model.getSize(); i++)
        {
            if (model.getElementAt(i).getId().equals(actionId))
            {
                selector.setSelectedIndex(i);
                return;
            }
        }

        selector.setSelectedIndex(0);
    }

    private UUID selectedActionId(JComboBox<IrlAction> selector)
    {
        IrlAction selected = (IrlAction) selector.getSelectedItem();
        return selected == null ? null : selected.getId();
    }

    private void onStartTimer()
    {
        IrlAction action = (IrlAction) timerActionSelector.getSelectedItem();
        if (action == null)
        {
            JOptionPane.showMessageDialog(this,
                "No timed actions to start. Tick \"Run this action on a timer\" when creating or editing an action.",
                "No action selected", JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        if (timerManager.startTimer(action.getId()).isEmpty())
        {
            JOptionPane.showMessageDialog(this, "That action is no longer available. Refresh the Actions tab and try again.",
                "Timer not started", JOptionPane.WARNING_MESSAGE);
            refreshActionList();
            return;
        }
        refreshActiveTimers(false);
    }

    /**
     * Relabels the units field with the selected action's own unit name.
     *
     * <p>Naming the unit is what makes the row concrete — "PUSH-UPS IN ONE GO"
     * asks a question the user can answer, where "UNITS" does not.</p>
     */
    private void onLogSelectionChanged()
    {
        IrlAction action = (IrlAction) logActionSelector.getSelectedItem();
        String unit = action == null ? "UNITS" : action.getUnitName().toUpperCase(Locale.US);
        logUnitsLabel.setText(unit + " IN ONE GO");
        refreshLogPreview();
    }

    /**
     * Shows what the current entry would bank, without banking it.
     *
     * <p>The numbers come from the same service call that performs the award, so
     * the preview can never disagree with what the button does.</p>
     */
    private void refreshLogPreview()
    {
        IrlAction action = (IrlAction) logActionSelector.getSelectedItem();
        Optional<ActionLogManager.LoggedAward> award = action == null
            ? Optional.empty()
            : actionLogManager.preview(action.getId(), parsePositive(logUnitsField), parsePositive(logRepetitionsField));

        if (award.isEmpty())
        {
            logPreview.setForeground(IrlXpUi.MUTED_TEXT);
            logPreview.setText("Fill in both boxes above to see what this will bank.");
            logButton.setEnabled(false);
            return;
        }

        // Written out as two labelled lines rather than "60 push-ups -> Strength
        // +300": the first line shows the multiplication's result so the user can
        // check it, the second names it as the XP the button is about to bank.
        ActionLogManager.LoggedAward value = award.get();
        logPreview.setForeground(IrlXpUi.SUCCESS);
        logPreview.setText(String.format(
            Locale.US,
            // A literal \n, not %n: JTextArea treats \n as its line break on every
            // platform, while %n would inject a stray \r on Windows.
            "That is %s %s in total.\nBanks: %s%s",
            QuantityFormatter.formatNumber(value.getTotalUnits()),
            value.getUnitName(),
            describeAward(value),
            // Only mentioned when it changed something, so a user with no
            // multipliers set never sees a line about a feature they do not use.
            value.isMultiplied()
                ? "\n(level multipliers applied — was " + describeBase(value) + ")"
                : ""));
        logButton.setEnabled(true);
    }

    private void onLogCompletion()
    {
        IrlAction action = (IrlAction) logActionSelector.getSelectedItem();
        if (action == null)
        {
            JOptionPane.showMessageDialog(this, "Create an action first, then log the work you completed.",
                "No action selected", JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        Optional<ActionLogManager.LoggedAward> award =
            actionLogManager.log(action.getId(), parsePositive(logUnitsField), parsePositive(logRepetitionsField));

        if (award.isEmpty())
        {
            JOptionPane.showMessageDialog(this,
                "Both boxes need a positive whole number. Enter how much you did in one go, "
                    + "and how many times you repeated it.",
                "Nothing banked", JOptionPane.WARNING_MESSAGE);
            refreshActionList();
            return;
        }

        ActionLogManager.LoggedAward value = award.get();
        JOptionPane.showMessageDialog(this,
            String.format(
                Locale.US,
                "Logged %s: %s %s in total.\nBanked %s.",
                value.getActionName(),
                QuantityFormatter.formatNumber(value.getTotalUnits()),
                value.getUnitName(),
                describeAward(value)),
            "XP banked", JOptionPane.INFORMATION_MESSAGE);
    }

    /** Renders what is actually banked, as "Agility +6,250, Hitpoints +2,000". */
    private static String describeAward(ActionLogManager.LoggedAward award)
    {
        return describeXp(award.getAwardedXp());
    }

    /** Renders the pre-multiplier figures, shown only when a multiplier changed them. */
    private static String describeBase(ActionLogManager.LoggedAward award)
    {
        return describeXp(award.getBaseXp());
    }

    private static String describeXp(Map<Skill, Long> xp)
    {
        return xp.entrySet().stream()
            .map(entry -> entry.getKey().getName() + " +" + QuantityFormatter.formatNumber(entry.getValue()))
            .collect(Collectors.joining(", "));
    }

    /**
     * Reads a formatted field as a positive count.
     *
     * <p>Returns 0 for blank or half-typed input, which the caller treats as
     * "nothing to bank yet" rather than as an error. Reads the text on screen,
     * not the field's last committed value: after an invalid edit the committed
     * value is still the previous good number, and banking that would bank an
     * amount the user has just deleted.</p>
     */
    private static long parsePositive(JFormattedTextField field)
    {
        Number value = IrlXpUi.readNumber(field);
        return value == null ? 0L : Math.max(0L, value.longValue());
    }

    private void onPauseTimer()
    {
        TimerManager.TimerSnapshot selected = activeTimersList.getSelectedValue();
        if (selected != null)
        {
            timerManager.pauseTimer(selected.id());
            refreshActiveTimers(true);
        }
    }

    private void onResumeTimer()
    {
        TimerManager.TimerSnapshot selected = activeTimersList.getSelectedValue();
        if (selected != null)
        {
            timerManager.resumeTimer(selected.id());
            refreshActiveTimers(true);
        }
    }

    private void onStopTimer()
    {
        TimerManager.TimerSnapshot selected = activeTimersList.getSelectedValue();
        if (selected != null)
        {
            timerManager.stopTimer(selected.id());
            refreshActiveTimers(false);
        }
    }

    /**
     * Rebuilds the timer list from the manager's current snapshots.
     *
     * <p>Runs immediately when already on the EDT. The pause, resume and stop
     * handlers call this and then read the selected snapshot back to decide
     * which buttons to enable; if the rebuild were queued instead, that read
     * would still see the snapshot from before the click, and Resume stayed
     * greyed out for up to a second after pressing Pause.</p>
     */
    private void refreshActiveTimers(boolean preserveSelection)
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            rebuildActiveTimers(preserveSelection);
        }
        else
        {
            SwingUtilities.invokeLater(() -> rebuildActiveTimers(preserveSelection));
        }
    }

    /** The EDT-only body of {@link #refreshActiveTimers}. */
    private void rebuildActiveTimers(boolean preserveSelection)
    {
        UUID selectedId = preserveSelection ? getSelectedTimerId() : null;

        activeTimersModel.clear();
        List<TimerManager.TimerSnapshot> timers = timerManager.getTimerSnapshots();
        for (TimerManager.TimerSnapshot snapshot : timers)
        {
            activeTimersModel.addElement(snapshot);
        }

        if (selectedId != null)
        {
            for (int i = 0; i < activeTimersModel.size(); i++)
            {
                if (activeTimersModel.get(i).id().equals(selectedId))
                {
                    activeTimersList.setSelectedIndex(i);
                    break;
                }
            }
        }

        activeTimersList.repaint();
    }

    private UUID getSelectedTimerId()
    {
        TimerManager.TimerSnapshot selected = activeTimersList.getSelectedValue();
        return selected == null ? null : selected.id();
    }

    private void updateTimerButtons(JButton pauseButton, JButton resumeButton, JButton stopButton)
    {
        TimerManager.TimerSnapshot selected = activeTimersList.getSelectedValue();
        boolean hasSelection = selected != null;
        pauseButton.setEnabled(hasSelection && !selected.paused());
        resumeButton.setEnabled(hasSelection && selected.paused());
        stopButton.setEnabled(hasSelection);
    }

    private static class ActionListCellRenderer extends DefaultListCellRenderer
    {
        @Override
        public java.awt.Component getListCellRendererComponent(
            JList<?> list,
            Object value,
            int index,
            boolean isSelected,
            boolean cellHasFocus)
        {
            super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
            if (value instanceof IrlAction)
            {
                IrlAction action = (IrlAction) value;
                int skillCount = action.getSkillMappings().size();
                String unitName = action.getUnitName() == null ? "" : action.getUnitName();
                // The timed/untimed marker tells the user at a glance which
                // actions can be started as a timer and which must be logged.
                setText(String.format("%s (%s, %s) - %d skill%s",
                    action.getName(),
                    unitName,
                    action.isTimed() ? "timed" : "logged",
                    skillCount,
                    skillCount == 1 ? "" : "s"));
            }
            return this;
        }
    }

    private static class TimerListCellRenderer extends DefaultListCellRenderer
    {
        @Override
        public java.awt.Component getListCellRendererComponent(
            JList<?> list,
            Object value,
            int index,
            boolean isSelected,
            boolean cellHasFocus)
        {
            super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
            if (value instanceof TimerManager.TimerSnapshot)
            {
                TimerManager.TimerSnapshot snapshot = (TimerManager.TimerSnapshot) value;
                String status = snapshot.paused() ? "Paused" : "Running";
                String rates = snapshot.formatRates();
                String rateText = rates.isEmpty() ? "" : " " + rates;
                setText(String.format("%s - %s (%s)%s",
                    snapshot.actionName(),
                    snapshot.formatElapsed(),
                    status,
                    rateText));
            }
            return this;
        }
    }

    /** Ensures the action drop-downs show a user-facing name, never a Java object identifier. */
    private static class ActionNameCellRenderer extends DefaultListCellRenderer
    {
        @Override
        public java.awt.Component getListCellRendererComponent(
            JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
        {
            super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
            if (value instanceof IrlAction)
            {
                setText(((IrlAction) value).getName());
            }
            return this;
        }
    }
}

package com.gokirlbankedxp.ui;

import java.text.NumberFormat;
import java.text.ParseException;
import java.text.ParsePosition;
import javax.swing.text.NumberFormatter;

/**
 * A {@link NumberFormatter} that only accepts text it can read <em>in full</em>.
 *
 * <p>The stock formatter delegates to {@link java.text.Format#parseObject(String)},
 * which stops at the first character it cannot read and returns whatever it
 * parsed up to that point. In a plugin that turns typed numbers into banked XP
 * that is a data-integrity problem, not a nicety:</p>
 * <ul>
 *   <li>With grouping switched off, {@code "1,000"} parsed as {@code 1}. A user
 *       who typed a thousand XP per unit silently got one.</li>
 *   <li>{@code "12abc"} parsed as {@code 12}, hiding the typo.</li>
 * </ul>
 *
 * <p>This formatter separates the two jobs the stock one conflates. The
 * <em>display</em> format (passed to the superclass) turns a value into text
 * the same way it always did, so fields still show {@code 1000} rather than
 * {@code 1,000}. The <em>parser</em> is a second format used only for reading,
 * and it must consume every character of the trimmed text or the read fails.
 * Giving the parser grouping lets {@code "1,000"} read as a thousand, which is
 * what anyone typing it means.</p>
 *
 * <p>Whole-number fields additionally refuse anything the parser had to widen
 * to a {@code double}: a value past the {@code long} range would otherwise
 * saturate silently instead of being reported as invalid.</p>
 *
 * <p>The min/max check is the same one {@link javax.swing.text.InternationalFormatter}
 * applies, re-implemented here because that class performs it inside its own
 * {@code stringToValue}, which this one replaces.</p>
 */
public class StrictNumberFormatter extends NumberFormatter
{
    private final NumberFormat parser;

    /**
     * @param display how a value is rendered into the field
     * @param parser how the field's text is read back; must consume the whole
     *     string for the read to succeed
     */
    public StrictNumberFormatter(NumberFormat display, NumberFormat parser)
    {
        super(display);
        this.parser = parser;
        // Half-typed text has to be allowed or the user cannot clear the field
        // to type a new number. Validity is judged when the value is read.
        setAllowsInvalid(true);
    }

    @Override
    public Object stringToValue(String text) throws ParseException
    {
        String trimmed = text == null ? "" : text.trim();
        if (trimmed.isEmpty())
        {
            throw new ParseException("No number entered", 0);
        }

        ParsePosition position = new ParsePosition(0);
        Number parsed = parser.parse(trimmed, position);
        if (parsed == null || position.getIndex() != trimmed.length())
        {
            // Either nothing parsed, or something was left over ("12abc").
            throw new ParseException("Not a whole number", Math.max(0, position.getErrorIndex()));
        }

        Object value = toValueClass(parsed);
        checkRange(value);
        return value;
    }

    /**
     * Converts what the parser returned into the field's declared value class.
     *
     * <p>{@link java.text.DecimalFormat} returns a {@link Long} when the number
     * is integral and fits, and a {@link Double} otherwise. For a {@code Long}
     * field a {@code Double} therefore means "too big" or "had a fraction", both
     * of which are rejected rather than rounded.</p>
     */
    private Object toValueClass(Number parsed) throws ParseException
    {
        Class<?> valueClass = getValueClass();
        if (valueClass == Long.class)
        {
            if (!(parsed instanceof Long))
            {
                throw new ParseException("Not a whole number in range", 0);
            }
            return parsed;
        }
        if (valueClass == Double.class)
        {
            return parsed.doubleValue();
        }
        // No value class declared: hand back whatever the parser produced.
        return parsed;
    }

    /** The same min/max rule InternationalFormatter enforces, for the replaced read path. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private void checkRange(Object value) throws ParseException
    {
        Comparable minimum = getMinimum();
        Comparable maximum = getMaximum();
        try
        {
            if (minimum != null && minimum.compareTo(value) > 0)
            {
                throw new ParseException("Value below minimum", 0);
            }
            if (maximum != null && maximum.compareTo(value) < 0)
            {
                throw new ParseException("Value above maximum", 0);
            }
        }
        catch (ClassCastException ex)
        {
            throw new ParseException("Value is not comparable to the field's range", 0);
        }
    }
}

package com.gokirlbankedxp.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Font;
import java.text.NumberFormat;
import java.text.ParseException;
import java.text.ParsePosition;
import java.util.Locale;
import java.util.OptionalLong;
import javax.swing.BorderFactory;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JFormattedTextField;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.ListCellRenderer;
import javax.swing.border.Border;
import javax.swing.border.CompoundBorder;
import javax.swing.text.NumberFormatter;
import net.runelite.api.Skill;

/**
 * Shared visual language for the IRL XP sidebar and editor.
 *
 * <p>The palette intentionally stays close to RuneLite's dark chrome while the
 * warm gold accent makes the plugin feel like a compact progression dashboard.
 * Keeping these choices here prevents the XP and action views from drifting
 * back into two visually unrelated tools.</p>
 */
public final class IrlXpUi
{
    public static final Color BACKGROUND = new Color(0x17191C);
    public static final Color SURFACE = new Color(0x22252A);
    public static final Color SURFACE_RAISED = new Color(0x2A2E34);
    public static final Color INPUT_BACKGROUND = new Color(0x121417);
    public static final Color BORDER = new Color(0x3A3F46);
    public static final Color TEXT = new Color(0xF2F0EA);
    public static final Color MUTED_TEXT = new Color(0xA5A9AF);
    public static final Color ACCENT = new Color(0xD9A441);
    public static final Color ACCENT_DARK = new Color(0x8F6724);
    public static final Color SUCCESS = new Color(0x66B88A);
    public static final Color DANGER = new Color(0xD06B68);
    public static final Color SELECTION = new Color(0x4B3B20);

    private IrlXpUi()
    {
    }

    public static JPanel card(java.awt.LayoutManager layout)
    {
        JPanel panel = new JPanel(layout);
        panel.setBackground(SURFACE);
        panel.setBorder(cardBorder());
        return panel;
    }

    public static Border cardBorder()
    {
        return new CompoundBorder(
            BorderFactory.createLineBorder(BORDER),
            BorderFactory.createEmptyBorder(12, 12, 12, 12));
    }

    public static JLabel sectionTitle(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(TEXT);
        label.setFont(label.getFont().deriveFont(Font.BOLD, 15f));
        return label;
    }

    public static JLabel mutedLabel(String text)
    {
        JLabel label = new JLabel(text);
        label.setForeground(MUTED_TEXT);
        label.setFont(label.getFont().deriveFont(11f));
        return label;
    }

    public static void stylePrimaryButton(JButton button)
    {
        styleButton(button, ACCENT, new Color(0x18130B));
        button.setFont(button.getFont().deriveFont(Font.BOLD));
    }

    public static void styleSecondaryButton(JButton button)
    {
        styleButton(button, SURFACE_RAISED, TEXT);
        button.setBorder(new CompoundBorder(
            BorderFactory.createLineBorder(BORDER),
            BorderFactory.createEmptyBorder(5, 10, 5, 10)));
    }

    public static void styleDangerButton(JButton button)
    {
        styleButton(button, new Color(0x46282A), new Color(0xF0B6B3));
        button.setBorder(new CompoundBorder(
            BorderFactory.createLineBorder(new Color(0x714044)),
            BorderFactory.createEmptyBorder(5, 10, 5, 10)));
    }

    private static void styleButton(JButton button, Color background, Color foreground)
    {
        button.setBackground(background);
        button.setForeground(foreground);
        button.setFocusPainted(false);
        button.setOpaque(true);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        button.setBorder(BorderFactory.createEmptyBorder(6, 11, 6, 11));
    }

    public static void styleField(JComponent component)
    {
        component.setBackground(INPUT_BACKGROUND);
        component.setForeground(TEXT);
        component.setBorder(new CompoundBorder(
            BorderFactory.createLineBorder(BORDER),
            BorderFactory.createEmptyBorder(4, 6, 4, 6)));
    }

    public static void styleList(JList<?> list, JScrollPane scrollPane)
    {
        list.setBackground(INPUT_BACKGROUND);
        list.setForeground(TEXT);
        list.setSelectionBackground(SELECTION);
        list.setSelectionForeground(TEXT);
        list.setFixedCellHeight(36);
        scrollPane.setBorder(BorderFactory.createLineBorder(BORDER));
        scrollPane.getViewport().setBackground(INPUT_BACKGROUND);
    }

    /**
     * A muted, multi-line explanatory note.
     *
     * <p>A plain {@link JLabel} cannot wrap without HTML and a hard-coded pixel
     * width, so hints use a non-interactive {@link JTextArea} instead. Wrapped
     * text areas cannot work out their own height until they have been given a
     * width, so callers state how many lines to reserve.</p>
     */
    public static JTextArea wrappingNote(String text, int rows)
    {
        JTextArea area = new JTextArea(text);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setEditable(false);
        area.setFocusable(false);
        area.setOpaque(false);
        area.setBorder(null);
        area.setForeground(MUTED_TEXT);
        // JTextArea defaults to a monospaced font; borrow the label font so the
        // note reads as part of the form rather than as sample output.
        area.setFont(new JLabel().getFont().deriveFont(11f));
        area.setRows(rows);
        return area;
    }

    /**
     * Creates the formatter used by every positive-XP input.
     *
     * <p>Invalid intermediate text is allowed so an empty field accepts normal
     * typing. The value is judged when it is read back through
     * {@link #readNumber}, and only text that parses <em>completely</em> counts:
     * see {@link StrictNumberFormatter} for why "1,000" and "12abc" must not be
     * quietly read as 1 and 12.</p>
     *
     * <p>The field displays plain digits, but the parser accepts thousands
     * separators, so a user may type either {@code 1000} or {@code 1,000}.</p>
     */
    public static NumberFormatter positiveLongFormatter()
    {
        NumberFormat display = NumberFormat.getIntegerInstance(Locale.US);
        display.setGroupingUsed(false);
        NumberFormat parser = NumberFormat.getIntegerInstance(Locale.US);
        parser.setGroupingUsed(true);
        StrictNumberFormatter formatter = new StrictNumberFormatter(display, parser);
        formatter.setMinimum(1L);
        formatter.setValueClass(Long.class);
        return formatter;
    }

    /**
     * Creates the formatter used by every level-multiplier input.
     *
     * <p>Unlike {@link #positiveLongFormatter()} this accepts decimals and
     * accepts zero, because both are meaningful here: {@code 1.5} is "half again
     * as much XP" and {@code 0} is "this skill earns nothing at this level". Only
     * negatives are impossible, since XP already banked must never be reduced by
     * banking more. The ceiling is a typo guard, not a game rule.</p>
     *
     * <p>Grouping is off for parsing too: multipliers never reach a thousand,
     * and a stray comma in a decimal is far more likely a typo than a separator.</p>
     *
     * @param maximum the largest multiplier the editor will accept
     */
    public static NumberFormatter multiplierFormatter(double maximum)
    {
        NumberFormat display = NumberFormat.getNumberInstance(Locale.US);
        display.setGroupingUsed(false);
        display.setMinimumFractionDigits(0);
        // Two places is enough to express the multipliers people actually pick
        // (1.5x, 2.25x) without inviting values that round to nothing in use.
        display.setMaximumFractionDigits(2);
        NumberFormat parser = NumberFormat.getNumberInstance(Locale.US);
        parser.setGroupingUsed(false);
        StrictNumberFormatter formatter = new StrictNumberFormatter(display, parser);
        formatter.setMinimum(0.0);
        formatter.setMaximum(maximum);
        formatter.setValueClass(Double.class);
        return formatter;
    }

    /**
     * Builds a numeric field that never silently rewrites what the user typed.
     *
     * <p>{@link JFormattedTextField}'s default focus-lost policy is
     * {@code COMMIT_OR_REVERT}: when the text does not parse, the field snaps
     * back to its last good value the moment focus leaves it. A user who typed
     * {@code 0} into "seconds per unit" and clicked Save watched the field
     * revert to {@code 60} and the action save with 60 — or did not watch, and
     * only found out later. With {@code COMMIT}, unparseable text stays on
     * screen, and {@link #readNumber} reports it as invalid so the form shows an
     * error instead.</p>
     */
    public static JFormattedTextField numberField(NumberFormatter formatter)
    {
        JFormattedTextField field = new JFormattedTextField(formatter);
        field.setFocusLostBehavior(JFormattedTextField.COMMIT);
        return field;
    }

    /**
     * Reads the number currently shown in a formatted field.
     *
     * <p>Deliberately reads the <em>text</em> through the field's own formatter
     * rather than {@link JFormattedTextField#getValue()}. The value is only
     * updated by a successful commit, so after the user types something invalid
     * it still holds the previous good number — exactly the figure that must
     * not be acted on. Reading the text has no side effects either, so this is
     * safe to call from a document listener while the user is typing.</p>
     *
     * @return the number on screen, or null when the text is blank, not a
     *     number, or outside the formatter's range
     */
    public static Number readNumber(JFormattedTextField field)
    {
        JFormattedTextField.AbstractFormatter formatter = field.getFormatter();
        if (formatter == null)
        {
            return null;
        }

        try
        {
            Object value = formatter.stringToValue(field.getText());
            return value instanceof Number ? (Number) value : null;
        }
        catch (ParseException ex)
        {
            return null;
        }
    }

    /**
     * Parses a whole number typed into a plain text field, such as the sidebar's
     * XP amount box.
     *
     * <p>Uses the same rules as the formatted fields: the whole string must be a
     * number, thousands separators are accepted ({@code 1,000}), and anything
     * that does not fit in a {@code long} is rejected rather than clamped.</p>
     *
     * @return the number, or empty when the text is not one
     */
    public static OptionalLong parseWholeNumber(String text)
    {
        String trimmed = text == null ? "" : text.trim();
        if (trimmed.isEmpty())
        {
            return OptionalLong.empty();
        }

        NumberFormat parser = NumberFormat.getIntegerInstance(Locale.US);
        parser.setGroupingUsed(true);
        ParsePosition position = new ParsePosition(0);
        Number parsed = parser.parse(trimmed, position);
        // DecimalFormat only returns a Long when the value is integral and fits;
        // anything else came back as a Double and is not a usable whole number.
        if (!(parsed instanceof Long) || position.getIndex() != trimmed.length())
        {
            return OptionalLong.empty();
        }
        return OptionalLong.of(parsed.longValue());
    }

    /** Renders a multiplier the way the editor and the sidebar both show it. */
    public static String formatMultiplier(double multiplier)
    {
        return String.format(Locale.US, "%.2fx", multiplier);
    }

    /**
     * A renderer that shows a {@link Skill} by its in-game display name.
     *
     * <p>{@code Skill} does not override {@code toString()}, so the default
     * renderer shows the raw enum constant ("RUNECRAFT") rather than the name the
     * game uses ("Runecraft"). Every skill drop-down in this plugin needs the
     * same fix, so it lives here rather than being re-implemented per panel.</p>
     */
    public static ListCellRenderer<Object> skillNameRenderer()
    {
        return new DefaultListCellRenderer()
        {
            @Override
            public Component getListCellRendererComponent(
                JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
            {
                super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                if (value instanceof Skill)
                {
                    setText(((Skill) value).getName());
                }
                return this;
            }
        };
    }
}

package com.gokirlbankedxp.ui;

import com.gokirlbankedxp.model.XpMultiplierTier;
import com.gokirlbankedxp.service.SkillLevelTracker;
import com.gokirlbankedxp.service.XpMultiplierManager;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Window;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.DefaultListCellRenderer;
import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.ListSelectionModel;
import javax.swing.SwingUtilities;
import net.runelite.api.Skill;

/**
 * The sidebar's MULTIPLIERS tab: level-based banking multipliers, per skill.
 *
 * <p>This tab is only the entry point. Picking a skill shows what that skill is
 * banking at right now, and the thresholds themselves are edited in
 * {@link XpMultiplierEditorDialog}, which has room for a level field, a
 * multiplier field and a legible label on one line — the roughly 225px sidebar
 * does not.</p>
 *
 * <p>The list underneath exists so a user can see, without clicking through
 * twenty-three skills, which ones they have actually set up and what each is
 * paying at their current level. A feature configured one skill at a time needs
 * somewhere that shows the whole picture, or it becomes impossible to remember
 * what you did.</p>
 *
 * <p>{@code @Singleton} for the same reason the other panels carry it: this holds
 * live list models, and a second unscoped instance would be UI state that nothing
 * ever refreshes.</p>
 */
@Singleton
public class XpMultipliersPanel extends JPanel
{
    private final XpMultiplierManager multiplierManager;
    private final SkillLevelTracker levelTracker;

    private final JComboBox<Skill> skillSelector = new JComboBox<>(Skill.values());
    private final JLabel currentStatusLabel = new JLabel(" ");
    private final JTextArea skillSummary = IrlXpUi.wrappingNote(" ", 3);
    private final JButton editButton = new JButton("SET THRESHOLDS");
    private final JButton clearButton = new JButton("Clear");
    private final JTextArea disabledNote = IrlXpUi.wrappingNote(" ", 3);

    private final DefaultListModel<String> configuredModel = new DefaultListModel<>();

    @Inject
    public XpMultipliersPanel(XpMultiplierManager multiplierManager, SkillLevelTracker levelTracker)
    {
        this.multiplierManager = multiplierManager;
        this.levelTracker = levelTracker;

        setLayout(new BorderLayout(0, 10));
        setBackground(IrlXpUi.BACKGROUND);
        setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));

        add(buildEditorCard(), BorderLayout.NORTH);
        add(buildConfiguredCard(), BorderLayout.CENTER);

        refresh();
    }

    /** The per-skill picker and the buttons that act on the chosen skill. */
    private JPanel buildEditorCard()
    {
        JPanel card = IrlXpUi.card(new BorderLayout(0, 8));

        JPanel heading = new JPanel(new BorderLayout(0, 6));
        heading.setOpaque(false);
        heading.add(IrlXpUi.sectionTitle("Level multipliers"), BorderLayout.NORTH);
        heading.add(IrlXpUi.wrappingNote(
            "Bank more XP as your levels climb. Pick a skill, choose how many thresholds you want, "
                + "then set the level each one starts at and what it multiplies your banked XP by.", 4),
            BorderLayout.CENTER);
        card.add(heading, BorderLayout.NORTH);

        JPanel body = new JPanel(new BorderLayout(0, 6));
        body.setOpaque(false);

        JPanel selectorRow = new JPanel(new BorderLayout(0, 4));
        selectorRow.setOpaque(false);
        JLabel skillLabel = new JLabel("Skill");
        skillLabel.setForeground(IrlXpUi.MUTED_TEXT);
        selectorRow.add(skillLabel, BorderLayout.NORTH);

        skillSelector.setPreferredSize(new Dimension(1, 32));
        skillSelector.setRenderer(IrlXpUi.skillNameRenderer());
        skillSelector.setToolTipText("Multipliers are set per skill; each skill has its own thresholds.");
        skillSelector.addActionListener(e -> refreshSelectedSkill());
        IrlXpUi.styleField(skillSelector);
        selectorRow.add(skillSelector, BorderLayout.CENTER);
        body.add(selectorRow, BorderLayout.NORTH);

        JPanel status = new JPanel(new BorderLayout(0, 4));
        status.setOpaque(false);
        currentStatusLabel.setForeground(IrlXpUi.ACCENT);
        currentStatusLabel.setFont(currentStatusLabel.getFont().deriveFont(Font.BOLD, 13f));
        status.add(currentStatusLabel, BorderLayout.NORTH);
        status.add(skillSummary, BorderLayout.CENTER);
        body.add(status, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new GridLayout(1, 2, 5, 0));
        buttons.setOpaque(false);
        IrlXpUi.stylePrimaryButton(editButton);
        IrlXpUi.styleDangerButton(clearButton);
        editButton.addActionListener(e -> onEditThresholds());
        clearButton.addActionListener(e -> onClearThresholds());
        buttons.add(editButton);
        buttons.add(clearButton);
        body.add(buttons, BorderLayout.SOUTH);

        card.add(body, BorderLayout.CENTER);

        // Shown only while the feature is switched off in the settings panel.
        // Silently ignoring a user's carefully built ladder because of a checkbox
        // they set months ago is exactly the kind of thing this tab has to say
        // out loud, and it names where the switch is.
        disabledNote.setForeground(IrlXpUi.DANGER);
        card.add(disabledNote, BorderLayout.SOUTH);

        return card;
    }

    /** The overview list: every skill that has a ladder, and what it pays now. */
    private JPanel buildConfiguredCard()
    {
        JPanel card = IrlXpUi.card(new BorderLayout(0, 8));

        JPanel heading = new JPanel(new BorderLayout());
        heading.setOpaque(false);
        heading.add(IrlXpUi.sectionTitle("Skills with multipliers"), BorderLayout.WEST);
        card.add(heading, BorderLayout.NORTH);

        JList<String> configuredList = new JList<>(configuredModel);
        configuredList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        configuredList.setVisibleRowCount(8);
        configuredList.setCellRenderer(new DefaultListCellRenderer()
        {
            @Override
            public Component getListCellRendererComponent(
                JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
            {
                JLabel label = (JLabel) super.getListCellRendererComponent(
                    list, value, index, isSelected, cellHasFocus);
                label.setBorder(BorderFactory.createEmptyBorder(5, 9, 5, 9));
                return label;
            }
        });

        JScrollPane scrollPane = new JScrollPane(configuredList);
        IrlXpUi.styleList(configuredList, scrollPane);
        configuredList.setFixedCellHeight(30);
        card.add(scrollPane, BorderLayout.CENTER);
        return card;
    }

    /**
     * Rebuilds everything on this tab.
     *
     * <p>Called on the EDT after any change that could move a multiplier: a save
     * from the editor, and every banked-XP snapshot the plugin publishes — an XP
     * drop can be a level-up, which silently changes what the next deposit is
     * worth, and this tab is the only place that says so.</p>
     */
    public void refresh()
    {
        SwingUtilities.invokeLater(() -> {
            refreshSelectedSkill();
            refreshConfiguredList();
        });
    }

    /** Updates the status line, the per-skill summary, and the buttons' enabled state. */
    private void refreshSelectedSkill()
    {
        Skill selected = (Skill) skillSelector.getSelectedItem();
        boolean enabled = multiplierManager.isEnabled();

        disabledNote.setText(enabled
            ? ""
            : "Level multipliers are switched OFF in this plugin's settings panel "
                + "(the gear beside IRL XP in RuneLite's plugin list). Your thresholds are kept, "
                + "but XP is banked unchanged until you switch them back on.");
        disabledNote.setVisible(!enabled);

        if (selected == null)
        {
            currentStatusLabel.setText(" ");
            skillSummary.setText(" ");
            editButton.setEnabled(false);
            clearButton.setEnabled(false);
            return;
        }

        List<XpMultiplierTier> tiers = multiplierManager.getTiers(selected);
        int level = levelTracker.getLevel(selected);
        boolean observed = levelTracker.hasObserved(selected);

        // The multiplier the tiers would give, ignoring the master switch, so the
        // status line describes the ladder itself; the note above covers the case
        // where the switch is stopping it from being used.
        double tierMultiplier = multiplierManager.multiplierFor(selected, level);
        double effective = enabled ? tierMultiplier : XpMultiplierManager.NEUTRAL_MULTIPLIER;

        currentStatusLabel.setText(String.format(
            Locale.US,
            "%s %s — banking at %s",
            selected.getName(),
            observed ? "level " + level : "(level not seen yet)",
            IrlXpUi.formatMultiplier(effective)));

        skillSummary.setText(describeLadder(selected, tiers, level, observed));

        editButton.setEnabled(true);
        editButton.setText(tiers.isEmpty() ? "SET THRESHOLDS" : "EDIT THRESHOLDS");
        clearButton.setEnabled(!tiers.isEmpty());
    }

    /** One or two sentences describing this skill's ladder in plain language. */
    private String describeLadder(Skill skill, List<XpMultiplierTier> tiers, int level, boolean observed)
    {
        if (tiers.isEmpty())
        {
            return skill.getName() + " has no thresholds yet, so its XP is banked exactly as earned.";
        }

        StringBuilder text = new StringBuilder();
        text.append(tiers.size())
            .append(tiers.size() == 1 ? " threshold: " : " thresholds: ");

        List<String> parts = new ArrayList<>();
        for (XpMultiplierTier tier : tiers)
        {
            parts.add(String.format(Locale.US, "lvl %d %s",
                tier.getLevel(), IrlXpUi.formatMultiplier(tier.getMultiplier())));
        }
        text.append(String.join(", ", parts)).append('.');

        if (observed)
        {
            int firstLevel = tiers.get(0).getLevel();
            if (level < firstLevel)
            {
                text.append(" You are ")
                    .append(firstLevel - level)
                    .append(level + 1 == firstLevel ? " level" : " levels")
                    .append(" from the first one.");
            }
        }

        return text.toString();
    }

    /** Rebuilds the overview list from every skill that currently has a ladder. */
    private void refreshConfiguredList()
    {
        configuredModel.clear();

        Map<Skill, List<XpMultiplierTier>> all = multiplierManager.getAllTiers();
        if (all.isEmpty())
        {
            configuredModel.addElement("No multipliers set yet — pick a skill above.");
            return;
        }

        // EnumMap iterates in Skill declaration order, which is the order the
        // in-game skill guide uses, so the list reads the way players expect.
        all.forEach((skill, tiers) -> configuredModel.addElement(String.format(
            Locale.US,
            "%s   •   %d threshold%s   •   now %s",
            skill.getName(),
            tiers.size(),
            tiers.size() == 1 ? "" : "s",
            IrlXpUi.formatMultiplier(multiplierManager.currentMultiplier(skill)))));
    }

    private void onEditThresholds()
    {
        Skill selected = (Skill) skillSelector.getSelectedItem();
        if (selected == null)
        {
            return;
        }

        Window window = SwingUtilities.getWindowAncestor(this);
        XpMultiplierEditorDialog dialog = new XpMultiplierEditorDialog(
            window,
            selected,
            multiplierManager.getTiers(selected),
            levelTracker.getLevel(selected),
            levelTracker.hasObserved(selected));
        dialog.setVisible(true);

        List<XpMultiplierTier> saved = dialog.getResultTiers();
        if (saved != null)
        {
            multiplierManager.setTiers(selected, saved);
            refresh();
        }
    }

    private void onClearThresholds()
    {
        Skill selected = (Skill) skillSelector.getSelectedItem();
        if (selected == null || multiplierManager.getTiers(selected).isEmpty())
        {
            return;
        }

        int response = JOptionPane.showConfirmDialog(
            this,
            String.format("Remove every %s threshold? Its XP will be banked unchanged again.", selected.getName()),
            "Confirm clear",
            JOptionPane.YES_NO_OPTION);

        if (response == JOptionPane.YES_OPTION)
        {
            multiplierManager.clearTiers(selected);
            refresh();
        }
    }
}

package com.gokirlbankedxp.ui;

