import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.api.Skill;

/**
 * The per-skill level multiplier editor.
 *
 * <p>Laid out to answer, in order, the three questions the feature poses: how
 * many thresholds do you want, what level does each one start at, and what does
 * each one multiply your banked XP by. The count spinner at the top is the single
 * control that adds and removes rows, so there is exactly one place to decide how
 * big the ladder is rather than a scatter of add/remove buttons.</p>
 *
 * <p>A live summary underneath restates the resulting ladder as sentences,
 * including the "below your first threshold" case that has no row of its own.
 * Thresholds replace each other rather than stacking, which is the single fact
 * about this feature most likely to be assumed wrong, so the summary spells out
 * what each band actually pays and the note above it says so outright.</p>
 *
 * <p>This is a dialog, not a sidebar form, for the same reason the action editor
 * is: RuneLite's sidebar is roughly 225px wide, and a level field, a multiplier
 * field and a readable label do not fit on one line there.</p>
 */
class XpMultiplierEditorDialog extends JDialog
{
    private static final Color ERROR_COLOR = new Color(0x522B2D);

    /** Offered for the first row so a new ladder starts from a sensible place. */
    private static final int DEFAULT_FIRST_LEVEL = 50;
    private static final double DEFAULT_MULTIPLIER = 2.0;

    private final Skill skill;
    private final int currentLevel;
    private final boolean levelObserved;

    private final JSpinner thresholdCountSpinner = new JSpinner(
        new SpinnerNumberModel(0, 0, XpMultiplierManager.MAX_TIERS_PER_SKILL, 1));
    private final JPanel rowContainer = new JPanel();
    private final List<TierRow> rows = new ArrayList<>();
    private final JTextArea summary = IrlXpUi.wrappingNote(" ", 8);
    private final JLabel errorLabel = new JLabel(" ");

    /** Null until the user saves; the caller reads it to know whether to persist. */
    private List<XpMultiplierTier> resultTiers;

    /** Guards {@link #refreshSummary()} against re-entering itself. */
    private boolean refreshingSummary;

    /**
     * @param existingTiers the skill's saved ladder, lowest level first
     * @param currentLevel the player's last observed level in this skill
     * @param levelObserved false when the plugin has never seen this skill's
     *     experience, so the level shown is a default rather than a fact
     */
    XpMultiplierEditorDialog(
        Window owner,
        Skill skill,
        List<XpMultiplierTier> existingTiers,
        int currentLevel,
        boolean levelObserved)
    {
        super(owner, skill.getName() + " level multipliers", ModalityType.APPLICATION_MODAL);
        this.skill = skill;
        this.currentLevel = currentLevel;
        this.levelObserved = levelObserved;

        setLayout(new BorderLayout(8, 8));
        getContentPane().setBackground(IrlXpUi.BACKGROUND);
        ((JComponent) getContentPane()).setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        setPreferredSize(new Dimension(560, 660));
        setResizable(true);
        setDefaultCloseOperation(DISPOSE_ON_CLOSE);

        add(buildHeader(), BorderLayout.NORTH);
        add(buildRowsCard(), BorderLayout.CENTER);
        add(buildFooter(), BorderLayout.SOUTH);

        populateFrom(existingTiers);

        pack();
        setLocationRelativeTo(owner);
    }

    /** The ladder the user saved, or null if they cancelled. */
    List<XpMultiplierTier> getResultTiers()
    {
        return resultTiers;
    }

    private JPanel buildHeader()
    {
        JPanel card = IrlXpUi.card(new BorderLayout(0, 8));

        JPanel heading = new JPanel(new BorderLayout());
        heading.setOpaque(false);
        heading.add(IrlXpUi.sectionTitle(skill.getName() + " multipliers"), BorderLayout.WEST);

        JLabel levelLabel = new JLabel(levelObserved
            ? String.format(Locale.US, "Your level: %d", currentLevel)
            : "Level not seen yet");
        levelLabel.setForeground(IrlXpUi.ACCENT);
        levelLabel.setFont(levelLabel.getFont().deriveFont(Font.BOLD, 12f));
        heading.add(levelLabel, BorderLayout.EAST);
        card.add(heading, BorderLayout.NORTH);

        JPanel body = new JPanel(new GridBagLayout());
        body.setOpaque(false);

        GridBagConstraints gc = new GridBagConstraints();
        gc.gridx = 0;
        gc.gridy = 0;
        gc.gridwidth = GridBagConstraints.REMAINDER;
        gc.anchor = GridBagConstraints.WEST;
        gc.fill = GridBagConstraints.HORIZONTAL;
        gc.weightx = 1.0;
        gc.insets = new Insets(0, 0, 6, 0);

        body.add(IrlXpUi.wrappingNote(
            "Each threshold multiplies the " + skill.getName() + " XP you bank, once you reach its level. "
                + "Thresholds never stack: only the highest one you have reached applies, and reaching it "
                + "replaces the one below it completely.", 3), gc);

        gc.gridy = 1;
        gc.gridwidth = 1;
        gc.weightx = 0;
        gc.fill = GridBagConstraints.NONE;
        JLabel countLabel = new JLabel("How many thresholds do you want?");
        countLabel.setForeground(IrlXpUi.TEXT);
        body.add(countLabel, gc);

        gc.gridx = 1;
        gc.insets = new Insets(0, 8, 6, 0);
        thresholdCountSpinner.setPreferredSize(new Dimension(64, 28));
        thresholdCountSpinner.setToolTipText(
            "Set to 0 to bank " + skill.getName() + " XP unchanged. Up to "
                + XpMultiplierManager.MAX_TIERS_PER_SKILL + " thresholds.");
        // The spinner is the only control that changes how many rows exist, so
        // every row add/remove funnels through one listener.
        thresholdCountSpinner.addChangeListener(e -> syncRowCount());
        body.add(thresholdCountSpinner, gc);

        gc.gridx = 2;
        gc.weightx = 1.0;
        gc.fill = GridBagConstraints.HORIZONTAL;
        body.add(IrlXpUi.mutedLabel("0 means no multiplier for this skill"), gc);

        card.add(body, BorderLayout.CENTER);
        return card;
    }

    private JPanel buildRowsCard()
    {
        rowContainer.setLayout(new BoxLayout(rowContainer, BoxLayout.Y_AXIS));
        rowContainer.setBackground(IrlXpUi.INPUT_BACKGROUND);

        JScrollPane scrollPane = new JScrollPane(rowContainer);
        scrollPane.setBorder(BorderFactory.createLineBorder(IrlXpUi.BORDER));
        scrollPane.getViewport().setBackground(IrlXpUi.INPUT_BACKGROUND);
        scrollPane.getVerticalScrollBar().setUnitIncrement(12);

        JPanel card = IrlXpUi.card(new BorderLayout(0, 8));
        JPanel heading = new JPanel(new BorderLayout());
        heading.setOpaque(false);
        heading.add(IrlXpUi.sectionTitle("Your thresholds"), BorderLayout.WEST);
        heading.add(IrlXpUi.mutedLabel("Level it starts at, and what it pays"), BorderLayout.EAST);
        card.add(heading, BorderLayout.NORTH);
        card.add(scrollPane, BorderLayout.CENTER);
        return card;
    }

    private JPanel buildFooter()
    {
        JPanel footer = new JPanel(new BorderLayout(0, 6));
        footer.setBackground(IrlXpUi.BACKGROUND);

        JPanel summaryCard = IrlXpUi.card(new BorderLayout(0, 6));
        summaryCard.add(IrlXpUi.sectionTitle("What this means"), BorderLayout.NORTH);
        summaryCard.add(summary, BorderLayout.CENTER);
        footer.add(summaryCard, BorderLayout.NORTH);

        errorLabel.setForeground(new Color(0xF0B6B3));
        footer.add(errorLabel, BorderLayout.CENTER);

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 8));
        buttons.setBackground(IrlXpUi.BACKGROUND);
        JButton cancel = new JButton("Cancel");
        JButton save = new JButton("SAVE MULTIPLIERS");
        IrlXpUi.styleSecondaryButton(cancel);
        IrlXpUi.stylePrimaryButton(save);

        cancel.addActionListener(e -> {
            resultTiers = null;
            dispose();
        });

        save.addActionListener(e -> {
            List<XpMultiplierTier> candidate = buildTiersFromForm();
            if (candidate != null)
            {
                resultTiers = candidate;
                dispose();
            }
        });

        buttons.add(cancel);
        buttons.add(save);
        footer.add(buttons, BorderLayout.SOUTH);
        return footer;
    }

    /** Fills the form in from the saved ladder, or leaves it empty for a new one. */
    private void populateFrom(List<XpMultiplierTier> existingTiers)
    {
        List<XpMultiplierTier> tiers = existingTiers == null ? Collections.emptyList() : existingTiers;

        // Setting the spinner fires syncRowCount(), which creates the rows; the
        // values are written afterwards so they are not overwritten by defaults.
        thresholdCountSpinner.setValue(Math.min(tiers.size(), XpMultiplierManager.MAX_TIERS_PER_SKILL));

        for (int i = 0; i < rows.size() && i < tiers.size(); i++)
        {
            rows.get(i).setValues(tiers.get(i));
        }

        refreshSummary();
    }

    /**
     * Makes the number of rows match the spinner.
     *
     * <p>Growing the ladder seeds the new row rather than leaving it blank: a new
     * threshold starts one level above the previous one and keeps its multiplier,
     * which is a valid ladder the user can edit down, instead of an empty row that
     * would fail validation the moment they pressed save. Shrinking simply drops
     * the trailing rows, which is what "I want fewer thresholds" means.</p>
     */
    private void syncRowCount()
    {
        int wanted = (Integer) thresholdCountSpinner.getValue();

        while (rows.size() > wanted)
        {
            TierRow removed = rows.remove(rows.size() - 1);
            rowContainer.remove(removed.panel);
        }

        while (rows.size() < wanted)
        {
            TierRow row = new TierRow(rows.size() + 1);
            row.setValues(seedForRow(rows.size()));
            rows.add(row);
            rowContainer.add(row.panel);
        }

        rowContainer.revalidate();
        rowContainer.repaint();
        refreshSummary();
    }

    /** A starting level and multiplier for a newly added row, based on the row before it. */
    private XpMultiplierTier seedForRow(int index)
    {
        if (index == 0)
        {
            return new XpMultiplierTier(
                Math.min(XpMultiplierTier.MAX_LEVEL, DEFAULT_FIRST_LEVEL), DEFAULT_MULTIPLIER);
        }

        TierRow previous = rows.get(index - 1);
        int previousLevel = previous.readLevel();
        double previousMultiplier = previous.readMultiplier();
        return new XpMultiplierTier(
            Math.min(XpMultiplierTier.MAX_LEVEL, previousLevel + 1),
            Double.isNaN(previousMultiplier) ? DEFAULT_MULTIPLIER : previousMultiplier);
    }

    /**
     * Validates the form and turns it into a ladder.
     *
     * <p>Two rows at the same level is rejected here rather than silently
     * collapsed. The service would keep only one of them, and a user who typed
     * two thresholds and got one would reasonably read that as lost work.</p>
     *
     * @return the tiers to save, or null when the form was rejected
     */
    private List<XpMultiplierTier> buildTiersFromForm()
    {
        clearValidationHighlights();

        List<XpMultiplierTier> tiers = new ArrayList<>();
        Set<Integer> seenLevels = new HashSet<>();

        for (TierRow row : rows)
        {
            int level = row.readLevel();
            double multiplier = row.readMultiplier();

            if (Double.isNaN(multiplier))
            {
                // Blank, not a number, or outside the range the field enforces:
                // all three read back as NaN, so the message covers all three.
                markInvalid(row.multiplierField, String.format(Locale.US,
                    "Threshold %d: enter a multiplier between %.0f and %.0f.",
                    row.index, XpMultiplierTier.MIN_MULTIPLIER, XpMultiplierTier.MAX_MULTIPLIER));
                return null;
            }

            if (multiplier < XpMultiplierTier.MIN_MULTIPLIER || multiplier > XpMultiplierTier.MAX_MULTIPLIER)
            {
                markInvalid(row.multiplierField, String.format(Locale.US,
                    "Threshold %d: the multiplier must be between %.0f and %.0f.",
                    row.index, XpMultiplierTier.MIN_MULTIPLIER, XpMultiplierTier.MAX_MULTIPLIER));
                return null;
            }

            if (!seenLevels.add(level))
            {
                markInvalid(row.multiplierField, String.format(Locale.US,
                    "Two thresholds both start at level %d. Give each one its own level.", level));
                return null;
            }

            tiers.add(new XpMultiplierTier(level, multiplier));
        }

        Collections.sort(tiers);
        return tiers;
    }

    /**
     * Restates the ladder as the bands it actually produces.
     *
     * <p>Reads the rows in whatever order they are on screen, sorted by level, so
     * a user who fills the second row in first still sees the truth. The band
     * below the lowest threshold is always listed, because it is the one case
     * with no row to look at and the one people forget exists.</p>
     */
    private void refreshSummary()
    {
        // Reading rows has no side effects now that it reads text rather than
        // committing, but the guard stays as a cheap safety net against any
        // listener that re-enters while the summary is being rebuilt.
        if (refreshingSummary)
        {
            return;
        }

        refreshingSummary = true;
        try
        {
            rebuildSummary();
        }
        finally
        {
            refreshingSummary = false;
        }
    }

    private void rebuildSummary()
    {
        List<XpMultiplierTier> tiers = new ArrayList<>();
        for (TierRow row : rows)
        {
            double multiplier = row.readMultiplier();
            tiers.add(new XpMultiplierTier(row.readLevel(), Double.isNaN(multiplier) ? 1.0 : multiplier));
        }
        Collections.sort(tiers);

        StringBuilder text = new StringBuilder();
        if (tiers.isEmpty())
        {
            text.append(skill.getName())
                .append(" XP is banked exactly as earned, at 1.00x.");
        }
        else
        {
            int firstLevel = tiers.get(0).getLevel();
            if (firstLevel > XpMultiplierTier.MIN_LEVEL)
            {
                text.append("Below level ").append(firstLevel).append(": 1.00x (banked unchanged)\n");
            }

            for (int i = 0; i < tiers.size(); i++)
            {
                XpMultiplierTier tier = tiers.get(i);
                String band = i + 1 < tiers.size()
                    ? String.format(Locale.US, "Levels %d-%d", tier.getLevel(), tiers.get(i + 1).getLevel() - 1)
                    : String.format(Locale.US, "Level %d and above", tier.getLevel());
                text.append(band)
                    .append(": ")
                    .append(IrlXpUi.formatMultiplier(tier.getMultiplier()));

                if (tier.getMultiplier() == 0.0)
                {
                    text.append(" (banks nothing)");
                }

                text.append('\n');
            }

            if (levelObserved)
            {
                double now = resolveMultiplier(tiers, currentLevel);
                text.append("\nAt your level (")
                    .append(currentLevel)
                    .append("), 1,000 XP would bank as ")
                    .append(String.format(Locale.US, "%,d", XpMultiplierManager.scale(1000L, now)))
                    .append(" XP.");
            }
        }

        summary.setText(text.toString());
    }

    /**
     * The same non-stacking rule the service applies, run against unsaved rows.
     *
     * <p>Duplicated deliberately: the service resolves against what is stored, and
     * this preview has to describe what is on screen but not yet saved. Both are
     * the same three lines — the highest tier at or below the level wins.</p>
     */
    private static double resolveMultiplier(List<XpMultiplierTier> sortedTiers, int level)
    {
        double applicable = XpMultiplierManager.NEUTRAL_MULTIPLIER;
        for (XpMultiplierTier tier : sortedTiers)
        {
            if (tier.getLevel() > level)
            {
                break;
            }
            applicable = tier.getMultiplier();
        }
        return applicable;
    }

    private void clearValidationHighlights()
    {
        errorLabel.setText(" ");
        for (TierRow row : rows)
        {
            row.multiplierField.setBackground(IrlXpUi.INPUT_BACKGROUND);
        }
    }

    private void markInvalid(JComponent field, String message)
    {
        field.setBackground(ERROR_COLOR);
        errorLabel.setText(message);
        field.requestFocusInWindow();
    }

    /**
     * One threshold: the level it starts at, and what it multiplies by.
     *
     * <p>The level is a spinner rather than a text field so it cannot be set
     * outside 1 to 126 at all, which removes a whole class of validation error
     * from the save path.</p>
     */
    private class TierRow
    {
        private final int index;
        private final JPanel panel = new JPanel(new GridBagLayout());
        private final JSpinner levelSpinner = new JSpinner(new SpinnerNumberModel(
            XpMultiplierTier.MIN_LEVEL,
            XpMultiplierTier.MIN_LEVEL,
            XpMultiplierTier.MAX_LEVEL,
            1));
        private final JFormattedTextField multiplierField =
            IrlXpUi.numberField(IrlXpUi.multiplierFormatter(XpMultiplierTier.MAX_MULTIPLIER));

        TierRow(int index)
        {
            this.index = index;

            panel.setBackground(IrlXpUi.INPUT_BACKGROUND);
            panel.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createMatteBorder(0, 0, 1, 0, IrlXpUi.BORDER),
                BorderFactory.createEmptyBorder(7, 9, 7, 9)));
            panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));

            GridBagConstraints gc = new GridBagConstraints();
            gc.gridy = 0;
            gc.anchor = GridBagConstraints.WEST;
            gc.insets = new Insets(0, 0, 0, 6);

            gc.gridx = 0;
            JLabel name = new JLabel("Threshold " + index);
            name.setForeground(IrlXpUi.TEXT);
            name.setPreferredSize(new Dimension(90, 24));
            panel.add(name, gc);

            gc.gridx = 1;
            JLabel fromLabel = new JLabel("from level");
            fromLabel.setForeground(IrlXpUi.MUTED_TEXT);
            panel.add(fromLabel, gc);

            gc.gridx = 2;
            levelSpinner.setPreferredSize(new Dimension(66, 26));
            levelSpinner.setToolTipText("The level at which this threshold takes over (1 to "
                + XpMultiplierTier.MAX_LEVEL + ", virtual levels included).");
            levelSpinner.addChangeListener(e -> refreshSummary());
            panel.add(levelSpinner, gc);

            gc.gridx = 3;
            JLabel bankLabel = new JLabel("bank XP at");
            bankLabel.setForeground(IrlXpUi.MUTED_TEXT);
            panel.add(bankLabel, gc);

            gc.gridx = 4;
            multiplierField.setPreferredSize(new Dimension(76, 26));
            multiplierField.setToolTipText(
                "Banked XP is multiplied by this. 2 means double, 0.5 means half, 0 means nothing is banked.");
            IrlXpUi.styleField(multiplierField);
            // Follow the text, not the committed value: readMultiplier() reads
            // what is on screen, so the summary can update as the user types
            // instead of only once the field commits.
            multiplierField.getDocument().addDocumentListener(new DocumentListener()
            {
                @Override
                public void insertUpdate(DocumentEvent event)
                {
                    refreshSummary();
                }

                @Override
                public void removeUpdate(DocumentEvent event)
                {
                    refreshSummary();
                }

                @Override
                public void changedUpdate(DocumentEvent event)
                {
                    refreshSummary();
                }
            });
            panel.add(multiplierField, gc);

            gc.gridx = 5;
            JLabel times = new JLabel("x");
            times.setForeground(IrlXpUi.ACCENT);
            times.setFont(times.getFont().deriveFont(Font.BOLD, 13f));
            panel.add(times, gc);

            // A weighted, empty trailing cell absorbs the spare width so the
            // controls stay left-aligned instead of spreading out when the
            // dialog is resized.
            gc.gridx = 6;
            gc.weightx = 1.0;
            gc.fill = GridBagConstraints.HORIZONTAL;
            panel.add(Box.createHorizontalGlue(), gc);
        }

        void setValues(XpMultiplierTier tier)
        {
            levelSpinner.setValue(Math.min(XpMultiplierTier.MAX_LEVEL,
                Math.max(XpMultiplierTier.MIN_LEVEL, tier.getLevel())));
            multiplierField.setValue(tier.getMultiplier());
        }

        int readLevel()
        {
            return (Integer) levelSpinner.getValue();
        }

        /**
         * The typed multiplier.
         *
         * <p>Reads the text on screen rather than the field's committed value. A
         * field the user is still typing in holds its last committed value, not
         * what is shown — and after an invalid edit the committed value is the
         * previous good number, which is exactly what must not be saved.</p>
         *
         * @return the value, or NaN when the text is blank, not a number, or
         *     outside the range the field enforces
         */
        double readMultiplier()
        {
            Number value = IrlXpUi.readNumber(multiplierField);
            return value == null ? Double.NaN : value.doubleValue();
        }
    }
}

package com.gokirlbankedxp.service;

import com.gokirlbankedxp.GokIrlBankedXpConfig;
import com.gokirlbankedxp.GokIrlBankedXpPlugin;
import com.gokirlbankedxp.model.ActiveTimer;
import com.gokirlbankedxp.model.IrlAction;
import com.google.common.math.LongMath;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigProfile;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Drives the live timers that convert elapsed real time into banked XP.
 *
 * <p>{@code @Singleton} is required, not decorative: the plugin and the actions
 * panel both inject this class, and an unscoped binding would give each of them
 * a separate manager. Only the plugin's copy has {@link #startUp()} called on
 * it, so timers started from the panel would never tick.</p>
 */
@Singleton
public class TimerManager
{
    private static final Logger log = LoggerFactory.getLogger(TimerManager.class);
    private static final String CONFIG_KEY = "activeTimersJson";
    private static final Type STORED_TIMER_LIST = new TypeToken<List<StoredTimer>>()
    {
    }.getType();

    private final ConfigManager configManager;
    private final IrlActionManager actionManager;
    private final GokIrlBankedXpPlugin plugin;
    private final Supplier<Long> timeSupplier;
    private final Gson gson;

    /**
     * RuneLite's shared scheduler, owned by the client and used by every plugin.
     * This class therefore only ever cancels the single task it submitted, and
     * must never shut the executor down. Tests pass null and drive {@link #tick()}
     * by hand so timing stays deterministic.
     */
    private final ScheduledExecutorService executor;
    private ScheduledFuture<?> tickFuture;

    private final Object lock = new Object();
    private final Map<UUID, ActiveTimer> activeTimers = new LinkedHashMap<>();
    private int ticksSinceSave = 0;
    /** Identity of the config profile which owns the in-memory timers. */
    private Long loadedProfileId;

    private Long currentProfileId()
    {
        ConfigProfile profile = configManager.getProfile();
        return profile == null ? null : profile.getId();
    }

    /** Reload all dependent state while timer ticks are excluded. Never save old timers into the new profile. */
    public void reloadProfile(Runnable reloadDependencies)
    {
        synchronized (lock)
        {
            activeTimers.clear();
            reloadDependencies.run();
            loadTimersLocked();
        }
    }

    @Inject
    public TimerManager(ConfigManager configManager, IrlActionManager actionManager, GokIrlBankedXpPlugin plugin,
        ScheduledExecutorService executor, Gson gson)
    {
        this(configManager, actionManager, plugin, executor, gson, System::currentTimeMillis);
    }

    TimerManager(ConfigManager configManager, IrlActionManager actionManager, GokIrlBankedXpPlugin plugin,
        ScheduledExecutorService executor, Gson gson, Supplier<Long> timeSupplier)
    {
        this.configManager = Objects.requireNonNull(configManager);
        this.actionManager = Objects.requireNonNull(actionManager);
        this.plugin = Objects.requireNonNull(plugin);
        this.gson = Objects.requireNonNull(gson);
        this.timeSupplier = Objects.requireNonNull(timeSupplier);
        this.executor = executor;
    }

    public void startUp()
    {
        synchronized (lock)
        {
            loadTimersLocked();
        }

        // Guarding on tickFuture keeps a startUp() after a shutDown() (the plugin
        // being toggled off and on) from stacking a second ticking task.
        if (executor != null && tickFuture == null)
        {
            tickFuture = executor.scheduleAtFixedRate(this::runScheduledTick, 1, 1, TimeUnit.SECONDS);
        }
    }

    /**
     * The entry point the scheduler calls once a second.
     *
     * <p>{@link ScheduledExecutorService#scheduleAtFixedRate} cancels a task for
     * good the first time it throws, and does so silently. Without this guard a
     * single failure anywhere under {@link #tick()} — a config write that threw,
     * a listener on the event bus, a disk error surfacing as a runtime exception
     * — would stop every timer until the plugin was restarted, with nothing on
     * screen to say why. The failure is logged and the next second's tick runs
     * as normal.</p>
     *
     * <p>A unit whose award threw is not re-awarded: the timer had already
     * counted it as paid before the exception. That loses at most one unit's XP
     * on an error that should never happen, against timers that otherwise stop
     * for the whole session.</p>
     */
    void runScheduledTick()
    {
        try
        {
            tick();
        }
        catch (RuntimeException ex)
        {
            log.warn("Timer tick failed; timers will keep running", ex);
        }
    }

    public void shutDown()
    {
        // Cancel only the task this plugin submitted. The executor belongs to the
        // client and is shared with every other plugin, so shutting it down here
        // would silently break them until the client restarts.
        if (tickFuture != null)
        {
            tickFuture.cancel(false);
            tickFuture = null;
        }

        saveTimers();
    }

    /**
     * Starts a timer for a timed action.
     *
     * <p>Returns empty when the action no longer exists, or when it is an
     * untimed (benchmark-style) action. Untimed actions have no seconds-per-unit
     * to accrue against, so a timer on one would run forever awarding nothing;
     * those are banked through {@link ActionLogManager} instead.</p>
     */
    public Optional<UUID> startTimer(UUID actionId)
    {
        synchronized (lock)
        {
            if (!Objects.equals(loadedProfileId, currentProfileId()))
            {
                return Optional.empty();
            }
            // Resolve inside the reload boundary so a captured action cannot
            // outlive its profile and seed a timer in the next one.
            Optional<IrlAction> action = actionManager.getAction(actionId);
            if (action.isEmpty() || !action.get().isTimed())
            {
                return Optional.empty();
            }
            ActiveTimer timer = ActiveTimer.start(actionId, timeSupplier.get());
            timer.bindAction(action.get());
            timer.alignAwardedUnits(action.get().getSecondsPerUnit());
            activeTimers.put(timer.getId(), timer);
            saveTimersLocked();
            return Optional.of(timer.getId());
        }
    }

    public boolean stopTimer(UUID timerId)
    {
        if (timerId == null)
        {
            return false;
        }

        synchronized (lock)
        {
            if (!Objects.equals(loadedProfileId, currentProfileId()))
            {
                return false;
            }
            ActiveTimer timer = activeTimers.get(timerId);
            if (timer == null)
            {
                return false;
            }
            // Match Pause: settle completed units, but do not round up an unfinished unit.
            actionManager.getAction(timer.getActionId()).filter(IrlAction::isTimed).ifPresent(action ->
                timer.applyTick(timeSupplier.get(), action).forEach(plugin::addActionXp));
            activeTimers.remove(timerId);
            saveTimersLocked();
            return true;
        }
    }

    public boolean pauseTimer(UUID timerId)
    {
        return changePauseState(timerId, true);
    }

    public boolean resumeTimer(UUID timerId)
    {
        return changePauseState(timerId, false);
    }

    private boolean changePauseState(UUID timerId, boolean paused)
    {
        if (timerId == null)
        {
            return false;
        }

        Map<Skill, Long> earnedBeforePause = Collections.emptyMap();
        synchronized (lock)
        {
            if (!Objects.equals(loadedProfileId, currentProfileId()))
            {
                return false;
            }
            ActiveTimer timer = activeTimers.get(timerId);
            if (timer == null)
            {
                return false;
            }

            if (paused && timer.isPaused())
            {
                return false;
            }

            if (!paused && !timer.isPaused())
            {
                return false;
            }

            long now = timeSupplier.get();
            if (paused)
            {
                // Settle any whole units since the scheduler's last tick before
                // freezing the timer, so a quick pause/stop cannot lose XP.
                Optional<IrlAction> action = actionManager.getAction(timer.getActionId());
                if (action.isPresent() && action.get().isTimed())
                {
                    earnedBeforePause = timer.applyTick(now, action.get());
                }
                timer.pause(now);
            }
            else
            {
                timer.resume(now);
            }

            saveTimersLocked();
            // Keep settlement inside the profile reload boundary.
            earnedBeforePause.forEach((skill, amount) -> plugin.addActionXp(skill, amount));
        }
        return true;
    }

    public List<ActiveTimer> getActiveTimers()
    {
        synchronized (lock)
        {
            List<ActiveTimer> copy = new ArrayList<>();
            for (ActiveTimer timer : activeTimers.values())
            {
                copy.add(timer.copy());
            }
            return copy;
        }
    }

    public List<TimerSnapshot> getTimerSnapshots()
    {
        long now = timeSupplier.get();
        List<TimerSnapshot> snapshots = new ArrayList<>();
        synchronized (lock)
        {
            for (ActiveTimer timer : activeTimers.values())
            {
                Optional<IrlAction> action = actionManager.getAction(timer.getActionId());
                if (action.isEmpty())
                {
                    continue;
                }

                // The rates and unit come from the frozen terms the timer is
                // actually paying out at, so what is shown matches what is
                // earned even after the action was edited. The name is the
                // live one: a renamed action should not keep its old name in
                // the timer list, and the name changes nothing about the XP.
                IrlAction terms = timer.getActionSnapshot() == null ? action.get() : timer.getActionSnapshot();
                snapshots.add(new TimerSnapshot(
                    timer.getId(),
                    action.get().getName(),
                    timer.getDisplayElapsedSeconds(now),
                    timer.isPaused(),
                    terms.getSkillMappings(),
                    terms.getUnitName()
                ));
            }
        }
        return snapshots;
    }

    public void tick()
    {
        long now = timeSupplier.get();
        Map<Skill, Long> pendingXp = new EnumMap<>(Skill.class);
        boolean changed = false;

        synchronized (lock)
        {
            // ConfigManager changes its active profile before posting ProfileChanged.
            // A scheduler tick in that interval must not write the old profile's state.
            if (!Objects.equals(loadedProfileId, currentProfileId()))
            {
                return;
            }
            List<UUID> missingActions = new ArrayList<>();

            for (ActiveTimer timer : activeTimers.values())
            {
                Optional<IrlAction> actionOptional = actionManager.getAction(timer.getActionId());
                // A timer is stale once its action is deleted or edited to be
                // untimed; either way it can no longer accrue units.
                if (actionOptional.isEmpty() || !actionOptional.get().isTimed())
                {
                    missingActions.add(timer.getId());
                    continue;
                }

                IrlAction action = actionOptional.get();
                Map<Skill, Long> earned = timer.applyTick(now, action);
                for (Map.Entry<Skill, Long> entry : earned.entrySet())
                {
                    pendingXp.merge(entry.getKey(), entry.getValue(), LongMath::saturatedAdd);
                }
            }

            if (!missingActions.isEmpty())
            {
                missingActions.forEach(activeTimers::remove);
                changed = true;
            }

            ticksSinceSave++;
            if (ticksSinceSave >= 10 || changed)
            {
                saveTimersLocked();
                ticksSinceSave = 0;
            }
            // A profile reload cannot interleave between accruing and crediting XP.
            pendingXp.forEach((skill, amount) -> plugin.addActionXp(skill, amount));
        }
    }

    public void saveTimers()
    {
        synchronized (lock)
        {
            saveTimersLocked();
        }
    }

    private void loadTimersLocked()
    {
        activeTimers.clear();
        ticksSinceSave = 0;
        loadedProfileId = currentProfileId();

        String raw = configManager.getConfiguration(GokIrlBankedXpConfig.GROUP, CONFIG_KEY);
        if (raw == null || raw.isBlank())
        {
            saveTimersLocked();
            return;
        }

        try
        {
            List<StoredTimer> stored = gson.fromJson(raw, STORED_TIMER_LIST);
            if (stored != null)
            {
                for (StoredTimer entry : stored)
                {
                    if (entry == null)
                    {
                        continue;
                    }
                    Optional<IrlAction> action = actionManager.getAction(entry.actionId);
                    // Drop timers whose action was deleted, or converted to an
                    // untimed action, while the client was closed.
                    if (action.isEmpty() || !action.get().isTimed())
                    {
                        continue;
                    }

                    ActiveTimer timer = new ActiveTimer(
                        entry.id,
                        entry.actionId,
                        Math.max(0, entry.elapsedSeconds),
                        entry.paused,
                        timeSupplier.get(),
                        0L
                    );
                    // Gson bypasses constructors. Rebuild to sanitize nullable fields and mappings.
                    IrlAction terms = entry.actionSnapshot == null ? action.get() : entry.actionSnapshot.toBuilder().build();
                    if (!terms.isValid() || !terms.isTimed() || !Objects.equals(terms.getId(), entry.actionId))
                    {
                        terms = action.get();
                    }
                    timer.bindAction(terms);
                    timer.alignAwardedUnits(terms.getSecondsPerUnit());
                    activeTimers.put(timer.getId(), timer);
                }
            }
        }
        catch (JsonParseException ex)
        {
            log.warn("Unable to parse active timers config; clearing timers", ex);
        }

        saveTimersLocked();
    }

    private void saveTimersLocked()
    {
        if (!Objects.equals(loadedProfileId, currentProfileId()))
        {
            return;
        }
        List<StoredTimer> stored = new ArrayList<>();
        for (ActiveTimer timer : activeTimers.values())
        {
            stored.add(new StoredTimer(timer.getId(), timer.getActionId(), timer.getElapsedSeconds(), timer.isPaused(), timer.getActionSnapshot()));
        }
        String json = gson.toJson(stored);
        configManager.setConfiguration(GokIrlBankedXpConfig.GROUP, CONFIG_KEY, json);
    }

    /**
     * Immutable view data for the timer list. This intentionally uses an ordinary
     * class instead of a Java record because RuneLite Plugin Hub targets Java 11.
     */
    public static final class TimerSnapshot
    {
        private final UUID id;
        private final String actionName;
        private final long elapsedSeconds;
        private final boolean paused;
        private final Map<Skill, Long> rates;
        private final String unitName;

        TimerSnapshot(UUID id, String actionName, long elapsedSeconds, boolean paused,
                      Map<Skill, Long> rates, String unitName)
        {
            this.id = id;
            this.actionName = actionName;
            this.elapsedSeconds = elapsedSeconds;
            this.paused = paused;
            this.rates = rates;
            this.unitName = unitName;
        }

        public UUID id()
        {
            return id;
        }

        public String actionName()
        {
            return actionName;
        }

        public boolean paused()
        {
            return paused;
        }

        public String formatRates()
        {
            if (rates == null || rates.isEmpty())
            {
                return "";
            }

            String unit = unitName == null ? "unit" : unitName.toLowerCase(Locale.US);
            List<String> parts = new ArrayList<>();
            for (Map.Entry<Skill, Long> entry : rates.entrySet())
            {
                parts.add(String.format("%s +%d/%s", entry.getKey().getName(), entry.getValue(), unit));
            }
            return String.join(", ", parts);
        }

        public String formatElapsed()
        {
            long hours = elapsedSeconds / 3600;
            long minutes = (elapsedSeconds % 3600) / 60;
            long seconds = elapsedSeconds % 60;
            return String.format("%02d:%02d:%02d", hours, minutes, seconds);
        }
    }

    private static class StoredTimer
    {
        UUID id;
        UUID actionId;
        long elapsedSeconds;
        boolean paused;
        // Optional for legacy JSON; new saves retain the original earning terms across restart.
        IrlAction actionSnapshot;

        StoredTimer()
        {
        }

        StoredTimer(UUID id, UUID actionId, long elapsedSeconds, boolean paused, IrlAction actionSnapshot)
        {
            this.id = id;
            this.actionId = actionId;
            this.elapsedSeconds = elapsedSeconds;
            this.paused = paused;
            this.actionSnapshot = actionSnapshot;
        }
    }
}

package com.gokirlbankedxp.service;

import com.gokirlbankedxp.GokIrlBankedXpConfig;
import com.gokirlbankedxp.model.IrlAction;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Owns the user's action library.
 *
 * <p>Guice leaves unannotated bindings unscoped, so without {@code @Singleton}
 * every injection point (the plugin, the timer manager, the actions panel) would
 * receive its own manager holding its own copy of the library. Only the plugin's
 * copy is ever loaded from config, so the others looked permanently empty and
 * lookups by id failed even for actions the user had just created.</p>
 */
@Singleton
public class IrlActionManager
{
    private static final Logger log = LoggerFactory.getLogger(IrlActionManager.class);
    private static final String CONFIG_KEY = "irlActionsJson";
    private static final String UNITS_CONFIG_KEY = "irlActionUnitsJson";
    private static final Type ACTION_LIST_TYPE = new TypeToken<List<IrlAction>>()
    {
    }.getType();
    private static final Type UNIT_MAP_TYPE = new TypeToken<Map<String, Long>>()
    {
    }.getType();

    private final ConfigManager configManager;
    private final Gson gson;

    private final Object lock = new Object();
    private final Map<UUID, IrlAction> actions = new LinkedHashMap<>();
    private final Map<String, Long> savedUnits = new java.util.TreeMap<>(String.CASE_INSENSITIVE_ORDER);

    /**
     * RuneLite binds a shared Gson instance in its injector, and the Plugin Hub
     * forbids constructing new Gson/GsonBuilder instances, so it is injected here
     * rather than built. Any future customisation must go through
     * {@code gson.newBuilder()} instead of creating a fresh instance.
     */
    @Inject
    public IrlActionManager(ConfigManager configManager, Gson gson)
    {
        this.configManager = Objects.requireNonNull(configManager);
        this.gson = Objects.requireNonNull(gson);
    }

    public List<IrlAction> loadActions()
    {
        synchronized (lock)
        {
            actions.clear();
            loadSavedUnitsLocked();
            String raw = configManager.getConfiguration(GokIrlBankedXpConfig.GROUP, CONFIG_KEY);

            if (raw != null && !raw.isBlank())
            {
                try
                {
                    List<IrlAction> parsed = gson.fromJson(raw, ACTION_LIST_TYPE);
                    if (parsed != null)
                    {
                        for (IrlAction action : parsed)
                        {
                            IrlAction normalized = normalize(action).ensureId(UUID.randomUUID());
                            if (!normalized.isValid())
                            {
                                log.warn("Skipping invalid IRL action from config: {}", normalized.getName());
                                continue;
                            }

                            warnOnDuplicateNameLocked(normalized);
                            actions.put(normalized.getId(), normalized);
                            rememberUnitLocked(normalized);
                        }
                    }
                }
                catch (JsonParseException ex)
                {
                    log.warn("Failed to parse IRL actions config; keeping the action library empty", ex);
                }
            }

            // Persist the normalized representation (including migrations from
            // legacy enum-backed units). An empty library intentionally remains
            // empty; unit choices now come only from actions the user saved.
            saveActionsLocked();

            return snapshot();
        }
    }

    public List<IrlAction> getAllActions()
    {
        synchronized (lock)
        {
            return List.copyOf(actions.values());
        }
    }

    /** Returns only unit definitions represented by actions the user has saved. */
    public Map<String, Long> getSavedUnits()
    {
        synchronized (lock)
        {
            return new LinkedHashMap<>(savedUnits);
        }
    }

    public Optional<IrlAction> getAction(UUID id)
    {
        if (id == null)
        {
            return Optional.empty();
        }

        synchronized (lock)
        {
            return Optional.ofNullable(actions.get(id));
        }
    }

    public IrlAction createAction(IrlAction action)
    {
        IrlAction normalized = normalize(action).ensureId(UUID.randomUUID());
        if (!normalized.isValid())
        {
            throw new IllegalArgumentException("Cannot create invalid IRL action");
        }

        synchronized (lock)
        {
            warnOnDuplicateNameLocked(normalized);
            actions.put(normalized.getId(), normalized);
            rememberUnitLocked(normalized);
            saveActionsLocked();
            return normalized;
        }
    }

    public boolean updateAction(IrlAction action)
    {
        IrlAction normalized = normalize(action);
        if (normalized.getId() == null || !normalized.isValid())
        {
            return false;
        }

        synchronized (lock)
        {
            if (!actions.containsKey(normalized.getId()))
            {
                return false;
            }

            warnOnDuplicateNameLocked(normalized);
            actions.put(normalized.getId(), normalized);
            rememberUnitLocked(normalized);
            saveActionsLocked();
            return true;
        }
    }

    public boolean deleteAction(UUID id)
    {
        if (id == null)
        {
            return false;
        }

        synchronized (lock)
        {
            boolean removed = actions.remove(id) != null;
            if (removed)
            {
                saveActionsLocked();
            }
            return removed;
        }
    }

    public void saveActions()
    {
        synchronized (lock)
        {
            saveActionsLocked();
        }
    }

    private IrlAction normalize(IrlAction action)
    {
        if (action == null)
        {
            return IrlAction.builder()
                .id(UUID.randomUUID())
                .name("")
                .unitName("")
                .secondsPerUnit(0L)
                .timed(Boolean.FALSE)
                .timeUnit(null)
                .defaultXpPerUnit(0L)
                .skillMappings(Map.of())
                .build();
        }

        Map<Skill, Long> sanitized = new EnumMap<>(Skill.class);
        if (action.getSkillMappings() != null)
        {
            for (Map.Entry<Skill, Long> entry : action.getSkillMappings().entrySet())
            {
                Skill skill = entry.getKey();
                Long rate = entry.getValue();
                if (skill == null || rate == null || rate <= 0)
                {
                    continue;
                }
                sanitized.put(skill, rate);
            }
        }

        // isTimed()/getSecondsPerUnit() already resolve the legacy shapes, so
        // writing them back through the builder persists the migrated form and
        // drops the deprecated timeUnit enum.
        boolean timed = action.isTimed();
        return IrlAction.builder()
            .id(action.getId())
            .name(action.getName())
            .unitName(action.getUnitName())
            .secondsPerUnit(timed ? action.getSecondsPerUnit() : 0L)
            .timed(timed)
            .timeUnit(null)
            .defaultXpPerUnit(action.getDefaultXpPerUnit())
            .skillMappings(sanitized)
            .build();
    }

    private void saveActionsLocked()
    {
        String json = gson.toJson(actions.values());
        configManager.setConfiguration(GokIrlBankedXpConfig.GROUP, CONFIG_KEY, json);
        configManager.setConfiguration(GokIrlBankedXpConfig.GROUP, UNITS_CONFIG_KEY, gson.toJson(savedUnits));
    }

    /** Loads the independently persisted unit library before actions are migrated. */
    private void loadSavedUnitsLocked()
    {
        savedUnits.clear();
        String raw = configManager.getConfiguration(GokIrlBankedXpConfig.GROUP, UNITS_CONFIG_KEY);
        if (raw == null || raw.isBlank())
        {
            return;
        }

        try
        {
            Map<String, Long> parsed = gson.fromJson(raw, UNIT_MAP_TYPE);
            if (parsed != null)
            {
                parsed.forEach((name, seconds) -> {
                    // Zero is a legitimate duration here: it marks a unit that
                    // only untimed actions use (pounds, repetitions, chapters).
                    if (name != null && !name.isBlank() && seconds != null && seconds >= 0)
                    {
                        savedUnits.put(name.trim(), seconds);
                    }
                });
            }
        }
        catch (JsonParseException ex)
        {
            log.warn("Failed to parse saved action units; rebuilding them from saved actions", ex);
        }
    }

    /**
     * Adds the action's unit to the reusable unit library.
     *
     * <p>Untimed actions contribute the unit's name with a zero duration. A
     * known duration is never overwritten by one, so a unit shared between a
     * timed and an untimed action keeps the duration the timed action needs.</p>
     */
    private void rememberUnitLocked(IrlAction action)
    {
        String name = action.getUnitName();
        if (name == null || name.isBlank())
        {
            return;
        }

        String trimmed = name.trim();
        long seconds = action.getSecondsPerUnit();
        if (seconds > 0)
        {
            savedUnits.put(trimmed, seconds);
        }
        else
        {
            savedUnits.putIfAbsent(trimmed, 0L);
        }
    }

    private List<IrlAction> snapshot()
    {
        return new ArrayList<>(actions.values());
    }

    private void warnOnDuplicateNameLocked(IrlAction candidate)
    {
        if (candidate.getName() == null || candidate.getName().isEmpty())
        {
            return;
        }

        String normalizedName = candidate.getName().toLowerCase(Locale.ROOT);
        boolean duplicate = actions.values().stream()
            .anyMatch(existing ->
                !existing.getId().equals(candidate.getId())
                    && existing.getName() != null
                    && existing.getName().toLowerCase(Locale.ROOT).equals(normalizedName));

        if (duplicate)
        {
            log.warn("Duplicate IRL action name detected: {}", candidate.getName());
        }
    }
}

package com.gokirlbankedxp.service;

import com.gokirlbankedxp.GokIrlBankedXpConfig;
import com.gokirlbankedxp.model.XpMultiplierTier;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The level-based banking multiplier: how much a skill's in-game level changes
 * what a real-world action is worth.
 *
 * <p>Each skill carries its own ladder of {@link XpMultiplierTier tiers}, and the
 * user decides how many rungs it has, what level each rung starts at, and what
 * multiplier it applies. Resolution is deliberately simple and non-cumulative:
 * the tier in force is the highest one whose level the player has reached, and it
 * <em>replaces</em> every lower tier rather than compounding with them. Reaching
 * a level-90 tier means the level-70 tier stops applying entirely.</p>
 *
 * <p>Below the lowest tier — and for any skill with no tiers at all — the
 * multiplier is 1.0, so XP is banked exactly as entered. That is what makes the
 * feature invisible until someone opts into it.</p>
 *
 * <p>This class is the single authority on the arithmetic. The plugin applies it
 * once, at the one point where XP enters the bank, and the sidebar calls the same
 * methods to preview what a deposit will become, so the number shown and the
 * number banked can never disagree about the rules.</p>
 *
 * <p>{@code @Singleton}: the plugin, the log form, and the multipliers tab all
 * inject this. Unscoped, each would load its own copy and edits made in the tab
 * would never reach the plugin that banks the XP.</p>
 */
@Singleton
public class XpMultiplierManager
{
    private static final Logger log = LoggerFactory.getLogger(XpMultiplierManager.class);

    /** Hidden config key. The tiers are edited in the sidebar, not the settings panel. */
    private static final String CONFIG_KEY = "xpMultipliersJson";

    /** The multiplier applied when no tier is in force: bank exactly what was earned. */
    public static final double NEUTRAL_MULTIPLIER = 1.0;

    /**
     * Ceiling on how many rungs one skill's ladder may have. Not a game rule —
     * the user chooses the count — but an unbounded spinner invites a config
     * entry with thousands of rows that has to be parsed on every startup.
     */
    public static final int MAX_TIERS_PER_SKILL = 20;

    /**
     * Stored keyed by skill name rather than by {@link Skill} so that an entry
     * for a skill a future client no longer has is skipped on load instead of
     * failing the whole parse and silently discarding every other skill's tiers.
     */
    private static final Type TIER_MAP_TYPE = new TypeToken<Map<String, List<XpMultiplierTier>>>()
    {
    }.getType();

    private final ConfigManager configManager;
    private final GokIrlBankedXpConfig config;
    private final SkillLevelTracker levelTracker;
    private final Gson gson;

    private final Object lock = new Object();
    /** Every list held here is already normalized, deduplicated and sorted by level. */
    private final Map<Skill, List<XpMultiplierTier>> tiersBySkill = new EnumMap<>(Skill.class);

    /**
     * Gson is injected, not constructed: the Plugin Hub build rejects
     * plugin sources that construct their own Gson.
     */
    @Inject
    public XpMultiplierManager(
        ConfigManager configManager,
        GokIrlBankedXpConfig config,
        SkillLevelTracker levelTracker,
        Gson gson)
    {
        this.configManager = Objects.requireNonNull(configManager);
        this.config = Objects.requireNonNull(config);
        this.levelTracker = Objects.requireNonNull(levelTracker);
        this.gson = Objects.requireNonNull(gson);
    }

    /** Reads saved tiers back in, discarding anything that no longer makes sense. */
    public void load()
    {
        String raw = configManager.getConfiguration(GokIrlBankedXpConfig.GROUP, CONFIG_KEY);

        synchronized (lock)
        {
            tiersBySkill.clear();

            if (raw == null || raw.isBlank())
            {
                return;
            }

            try
            {
                Map<String, List<XpMultiplierTier>> parsed = gson.fromJson(raw, TIER_MAP_TYPE);
                if (parsed == null)
                {
                    return;
                }

                parsed.forEach((name, tiers) -> {
                    Skill skill = parseSkill(name);
                    if (skill == null)
                    {
                        log.debug("Ignoring multiplier tiers for unknown skill [{}]", name);
                        return;
                    }

                    List<XpMultiplierTier> sanitized = sanitize(tiers);
                    if (!sanitized.isEmpty())
                    {
                        tiersBySkill.put(skill, sanitized);
                    }
                });
            }
            catch (JsonParseException ex)
            {
                log.warn("Failed to parse level multipliers; every skill falls back to 1.00x", ex);
            }
        }
    }

    /**
     * This skill's ladder, lowest rung first.
     *
     * @return an immutable list, empty when the skill has no tiers configured
     */
    public List<XpMultiplierTier> getTiers(Skill skill)
    {
        if (skill == null)
        {
            return Collections.emptyList();
        }

        synchronized (lock)
        {
            return List.copyOf(tiersBySkill.getOrDefault(skill, Collections.emptyList()));
        }
    }

    /** Every skill that has at least one tier, for the sidebar's summary list. */
    public Map<Skill, List<XpMultiplierTier>> getAllTiers()
    {
        synchronized (lock)
        {
            Map<Skill, List<XpMultiplierTier>> copy = new EnumMap<>(Skill.class);
            tiersBySkill.forEach((skill, tiers) -> copy.put(skill, List.copyOf(tiers)));
            return copy;
        }
    }

    /**
     * Replaces one skill's ladder and saves it.
     *
     * <p>The incoming list is normalized before it is stored: out-of-range values
     * are clamped, two rungs at the same level collapse to the later one, and the
     * result is sorted by level. That means {@link #multiplierFor} can assume
     * sorted, unique levels and stay a simple scan. Passing an empty or null list
     * removes the skill's ladder entirely.</p>
     *
     * @return the ladder as it was actually stored
     */
    public List<XpMultiplierTier> setTiers(Skill skill, List<XpMultiplierTier> tiers)
    {
        if (skill == null)
        {
            return Collections.emptyList();
        }

        List<XpMultiplierTier> sanitized = sanitize(tiers);

        synchronized (lock)
        {
            if (sanitized.isEmpty())
            {
                tiersBySkill.remove(skill);
            }
            else
            {
                tiersBySkill.put(skill, sanitized);
            }

            persistLocked();
        }

        return List.copyOf(sanitized);
    }

    /** Removes a skill's ladder, so its XP banks unchanged again. */
    public void clearTiers(Skill skill)
    {
        setTiers(skill, Collections.emptyList());
    }

    /**
     * The multiplier a given level earns in a given skill.
     *
     * <p>Pure resolution against the saved ladder: it does not consult the
     * player's actual level, and it ignores the master on/off switch. Callers
     * that want "what applies right now" should use {@link #currentMultiplier}.
     * Kept separate so the rule itself is testable without a client.</p>
     *
     * @return the highest reached tier's multiplier, or {@link #NEUTRAL_MULTIPLIER}
     *     when the level is below every tier or the skill has none
     */
    public double multiplierFor(Skill skill, int level)
    {
        if (skill == null)
        {
            return NEUTRAL_MULTIPLIER;
        }

        List<XpMultiplierTier> tiers;
        synchronized (lock)
        {
            tiers = tiersBySkill.get(skill);
            if (tiers == null || tiers.isEmpty())
            {
                return NEUTRAL_MULTIPLIER;
            }

            // Sorted ascending by level, so the last tier at or below the
            // player's level is the one in force. Tiers never stack: this
            // overwrites rather than accumulating.
            double applicable = NEUTRAL_MULTIPLIER;
            for (XpMultiplierTier tier : tiers)
            {
                if (tier.getLevel() > level)
                {
                    break;
                }
                applicable = tier.getMultiplier();
            }

            return applicable;
        }
    }

    /**
     * The multiplier in force for a skill right now, honouring the master switch.
     *
     * <p>Uses the last level {@link SkillLevelTracker} observed, which is what the
     * banking path uses too, so the sidebar's preview and the actual deposit agree
     * even at the login screen.</p>
     */
    public double currentMultiplier(Skill skill)
    {
        if (!isEnabled())
        {
            return NEUTRAL_MULTIPLIER;
        }

        return multiplierFor(skill, levelTracker.getLevel(skill));
    }

    /**
     * Converts a base XP amount into the amount that should actually be banked.
     *
     * <p>The one place this conversion happens. Everything that banks XP goes
     * through the plugin, which calls this exactly once per deposit.</p>
     */
    public long applyTo(Skill skill, long baseXp)
    {
        return scale(baseXp, currentMultiplier(skill));
    }

    /** Whether the feature is switched on in the plugin's settings panel. */
    public boolean isEnabled()
    {
        return config.levelMultipliersEnabled();
    }

    /**
     * Scales an XP amount by a multiplier, in whole XP.
     *
     * <p>Three deliberate edge cases:</p>
     * <ul>
     *   <li>A multiplier of exactly zero banks nothing. That is the point of
     *       allowing zero — "this skill earns nothing at this level".</li>
     *   <li>Any other positive multiplier banks at least 1 XP, so a small deposit
     *       under a fractional multiplier is reduced rather than erased. Rounding
     *       a real deposit away to nothing reads as the plugin having lost it.</li>
     *   <li>A result past the {@code long} ceiling clamps instead of wrapping
     *       negative, matching how the plugin's banked totals saturate.</li>
     * </ul>
     */
    public static long scale(long baseXp, double multiplier)
    {
        if (baseXp <= 0)
        {
            return 0L;
        }

        if (Double.isNaN(multiplier) || multiplier <= 0.0)
        {
            return 0L;
        }

        if (multiplier == NEUTRAL_MULTIPLIER)
        {
            return baseXp;
        }

        double scaled = (double) baseXp * multiplier;
        if (Double.isInfinite(scaled) || scaled >= (double) Long.MAX_VALUE)
        {
            return Long.MAX_VALUE;
        }

        return Math.max(1L, Math.round(scaled));
    }

    /**
     * Puts a user-supplied ladder into the canonical shape the rest of the class
     * assumes: valid values only, one tier per level, sorted by level.
     *
     * <p>A {@link TreeMap} keyed by level does the deduplication and the sort in
     * one step; a later tier at the same level wins, which matches the editor,
     * where the lower row is the one the user filled in most recently.</p>
     */
    private static List<XpMultiplierTier> sanitize(List<XpMultiplierTier> tiers)
    {
        if (tiers == null || tiers.isEmpty())
        {
            return Collections.emptyList();
        }

        Map<Integer, XpMultiplierTier> byLevel = new TreeMap<>();
        for (XpMultiplierTier tier : tiers)
        {
            if (tier == null)
            {
                continue;
            }

            XpMultiplierTier usable = tier.isValid() ? tier : tier.normalized();
            byLevel.put(usable.getLevel(), usable);
        }

        List<XpMultiplierTier> sorted = new ArrayList<>(byLevel.values());
        if (sorted.size() > MAX_TIERS_PER_SKILL)
        {
            // Keep the lowest rungs, which are the ones a player reaches first.
            return new ArrayList<>(sorted.subList(0, MAX_TIERS_PER_SKILL));
        }

        return sorted;
    }

    /**
     * Writes every skill's ladder out.
     *
     * <p>Keyed and ordered by skill name so the serialized value is stable
     * between runs and does not churn the config file when nothing changed.</p>
     */
    private void persistLocked()
    {
        Map<String, List<XpMultiplierTier>> serializable = new TreeMap<>();
        tiersBySkill.forEach((skill, tiers) -> serializable.put(skill.name(), tiers));
        configManager.setConfiguration(
            GokIrlBankedXpConfig.GROUP, CONFIG_KEY, gson.toJson(new LinkedHashMap<>(serializable)));
    }

    private static Skill parseSkill(String raw)
    {
        if (raw == null || raw.isBlank())
        {
            return null;
        }

        try
        {
            return Skill.valueOf(raw.trim().toUpperCase(Locale.ROOT));
        }
        catch (IllegalArgumentException ex)
        {
            return null;
        }
    }
}

package com.gokirlbankedxp.service;

import com.gokirlbankedxp.GokIrlBankedXpPlugin;
import com.gokirlbankedxp.model.IrlAction;
import com.google.common.math.LongMath;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

/**
 * Banks XP for work the user already finished, without running a timer.
 *
 * <p>This is the manual counterpart to {@link TimerManager}. Where a timer
 * accrues units as real time passes, this converts a completed session the user
 * describes after the fact — "I did {@code repetitions} sets of
 * {@code unitsPerRepetition} units" — into banked XP in one step. It exists so
 * benchmark-style actions ("1 XP per pound lifted", "250 XP per km run") are
 * usable at all: those have no duration for a timer to count against.</p>
 *
 * <p>The per-skill arithmetic itself lives on {@link IrlAction#xpForUnits(long)},
 * shared with the timer path so both routes to banked XP always agree.</p>
 */
@Singleton
public class ActionLogManager
{
    private final IrlActionManager actionManager;
    private final GokIrlBankedXpPlugin plugin;
    private final XpMultiplierManager multiplierManager;

    @Inject
    public ActionLogManager(
        IrlActionManager actionManager,
        GokIrlBankedXpPlugin plugin,
        XpMultiplierManager multiplierManager)
    {
        this.actionManager = Objects.requireNonNull(actionManager);
        this.plugin = Objects.requireNonNull(plugin);
        this.multiplierManager = Objects.requireNonNull(multiplierManager);
    }

    /**
     * Computes what a completed session is worth without banking anything.
     *
     * <p>Used to preview the award in the UI as the user types, so the numbers
     * shown before pressing the button are produced by the same code that
     * actually grants the XP.</p>
     *
     * <p>The preview applies the level multiplier itself, through the same
     * service the plugin uses, because it has to show what will land in the bank
     * rather than what the action's rates say on paper. It only ever estimates:
     * the authoritative figure is whatever {@link #log} gets back from the
     * plugin, which is the one place XP is actually multiplied and stored.</p>
     *
     * @return empty when the action is unknown or either count is not positive
     */
    public Optional<LoggedAward> preview(UUID actionId, long unitsPerRepetition, long repetitions)
    {
        if (unitsPerRepetition <= 0 || repetitions <= 0)
        {
            return Optional.empty();
        }

        Optional<IrlAction> action = actionManager.getAction(actionId);
        if (action.isEmpty())
        {
            return Optional.empty();
        }

        IrlAction value = action.get();
        // Saturating rather than throwing: a nonsensical count clamps to the
        // long ceiling instead of wrapping negative and subtracting banked XP.
        long totalUnits = LongMath.saturatedMultiply(unitsPerRepetition, repetitions);
        Map<Skill, Long> base = value.xpForUnits(totalUnits);
        if (base.isEmpty())
        {
            return Optional.empty();
        }

        Map<Skill, Long> banked = new EnumMap<>(Skill.class);
        base.forEach((skill, amount) -> banked.put(skill, multiplierManager.applyTo(skill, amount)));

        return Optional.of(new LoggedAward(value.getName(), value.getUnitName(), totalUnits, base, banked));
    }

    /**
     * Banks the XP for a completed session and returns what was granted.
     *
     * <p>Nothing is persisted about the session itself; the plugin's banked XP
     * totals are the only record, exactly as with timer-earned XP.</p>
     *
     * <p>What comes back reports the plugin's own return values, not the preview's
     * estimate. The two agree in every ordinary case, but the plugin is the only
     * thing that knows what it actually stored, and a caller that tells the user
     * "banked 2,000 XP" should be quoting the bank rather than a prediction.</p>
     *
     * @return empty when nothing was banked, in which case no XP was granted
     */
    public Optional<LoggedAward> log(UUID actionId, long unitsPerRepetition, long repetitions)
    {
        Optional<LoggedAward> preview = preview(actionId, unitsPerRepetition, repetitions);
        if (preview.isEmpty())
        {
            return Optional.empty();
        }

        LoggedAward estimate = preview.get();
        Map<Skill, Long> banked = new EnumMap<>(Skill.class);
        estimate.getBaseXp().forEach((skill, amount) -> banked.put(skill, plugin.addActionXp(skill, amount)));

        return Optional.of(new LoggedAward(
            estimate.getActionName(),
            estimate.getUnitName(),
            estimate.getTotalUnits(),
            estimate.getBaseXp(),
            banked));
    }

    /**
     * The outcome of one logged session.
     *
     * <p>An ordinary class rather than a record because the Plugin Hub targets
     * Java 11.</p>
     */
    public static final class LoggedAward
    {
        private final String actionName;
        private final String unitName;
        private final long totalUnits;
        private final Map<Skill, Long> baseXp;
        private final Map<Skill, Long> awardedXp;

        LoggedAward(
            String actionName,
            String unitName,
            long totalUnits,
            Map<Skill, Long> baseXp,
            Map<Skill, Long> awardedXp)
        {
            this.actionName = actionName;
            this.unitName = unitName;
            this.totalUnits = totalUnits;
            this.baseXp = Collections.unmodifiableMap(baseXp);
            this.awardedXp = Collections.unmodifiableMap(awardedXp);
        }

        public String getActionName()
        {
            return actionName;
        }

        public String getUnitName()
        {
            return unitName;
        }

        public long getTotalUnits()
        {
            return totalUnits;
        }

        /**
         * What the action's own XP rates produce, before any level multiplier.
         *
         * <p>Kept alongside the awarded figure so the UI can say "1,000 becomes
         * 2,000" rather than only showing the end result, and so {@link #log}
         * has an unmultiplied amount to hand the plugin — the plugin applies the
         * multiplier itself, and passing it an already-multiplied figure would
         * double it.</p>
         */
        public Map<Skill, Long> getBaseXp()
        {
            return baseXp;
        }

        /**
         * What actually goes into the bank: the base XP after the skill's level
         * multiplier. Equal to {@link #getBaseXp()} whenever no multiplier is in
         * force, which is the case for any skill the user never configured.
         */
        public Map<Skill, Long> getAwardedXp()
        {
            return awardedXp;
        }

        /** Whether a level multiplier changed any of this award's figures. */
        public boolean isMultiplied()
        {
            return !baseXp.equals(awardedXp);
        }
    }
}

package com.gokirlbankedxp.service;

import com.google.common.math.LongMath;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Skill;

/**
 * Predicts how much banked XP a skill's next few in-game actions will consume.
 *
 * <p>The plugin needs to warn the user <em>before</em> a skill's banked XP runs
 * out, expressed in the unit people actually think in: "about five more actions
 * left". There is no API that reports "one action", and what an action costs is
 * entirely skill- and content-dependent — a yew log, an Ardougne lap, and a hit
 * on a boss are all one action but nothing alike.</p>
 *
 * <p>Rather than special-casing skills, this learns the rate from the game's own
 * XP drops. Every {@link net.runelite.api.events.StatChanged} that reduces a
 * skill's bank is one action's worth of XP by definition, so keeping the most
 * recent few of those per skill gives a live, self-correcting estimate that works
 * the same for woodcutting, agility, and combat. Nothing is persisted: a fresh
 * client simply re-learns the rate from the first drops of the session.</p>
 *
 * <p>{@code @Singleton} for the same reason the other services carry it — the
 * plugin is the only consumer today, but a second unscoped instance would be a
 * second, always-empty sample history.</p>
 */
@Singleton
public class DepletionForecaster
{
    /**
     * Upper bound on retained samples per skill, independent of the configured
     * window. It only exists so a user typing an absurd window size cannot make
     * the deques grow without limit; the config itself is range-capped well below
     * this.
     */
    private static final int MAX_SAMPLES = 64;

    /**
     * Recent XP drops per skill, oldest first. Guarded by this instance's
     * monitor: XP drops arrive on the client thread while the sidebar can ask for
     * a forecast from the EDT.
     */
    private final Map<Skill, Deque<Long>> recentDrops = new EnumMap<>(Skill.class);

    /**
     * Records one action's worth of XP for a skill.
     *
     * @param window how many recent drops the forecast should consider; samples
     *               beyond this are discarded, so shrinking the window in config
     *               takes effect on the next drop
     */
    public synchronized void recordDrop(Skill skill, long xpDelta, int window)
    {
        if (skill == null || xpDelta <= 0 || window <= 0)
        {
            return;
        }

        Deque<Long> drops = recentDrops.computeIfAbsent(skill, key -> new ArrayDeque<>());
        drops.addLast(xpDelta);

        int limit = Math.min(window, MAX_SAMPLES);
        while (drops.size() > limit)
        {
            drops.removeFirst();
        }
    }

    /**
     * Estimates what the next {@code window} actions will cost this skill.
     *
     * <p>The estimate is the mean recorded drop multiplied by the window. Once
     * the window is full that is exactly the sum of the last {@code window}
     * drops; before it fills, scaling the mean keeps the answer meaningful
     * instead of under-reporting and warning too late. Using the mean also keeps
     * combat honest, where individual drops vary from hit to hit.</p>
     *
     * @return 0 when nothing has been recorded yet, which callers read as "no
     *         prediction available, do not warn"
     */
    public synchronized long forecast(Skill skill, int window)
    {
        if (window <= 0)
        {
            return 0L;
        }

        long average = averageDrop(skill);
        // Saturating: a colossal learned rate clamps at the long ceiling rather
        // than wrapping negative, which would read as "no XP will be consumed".
        return average <= 0 ? 0L : LongMath.saturatedMultiply(average, window);
    }

    /**
     * The mean XP of the retained drops for a skill, rounded down.
     *
     * <p>Exposed so callers can turn "XP remaining" back into "actions remaining"
     * for the warning text, using the same samples the forecast was built from.</p>
     *
     * @return 0 when the skill has no samples yet
     */
    public synchronized long averageDrop(Skill skill)
    {
        Deque<Long> drops = skill == null ? null : recentDrops.get(skill);
        if (drops == null || drops.isEmpty())
        {
            return 0L;
        }

        long total = 0L;
        for (Long drop : drops)
        {
            total = LongMath.saturatedAdd(total, drop);
        }

        return total / drops.size();
    }

    /** Number of drops currently retained for a skill; 0 when it has none. */
    public synchronized int sampleCount(Skill skill)
    {
        Deque<Long> drops = skill == null ? null : recentDrops.get(skill);
        return drops == null ? 0 : drops.size();
    }

    /** Drops every learned rate, so a restarted plugin starts from a clean slate. */
    public synchronized void clear()
    {
        recentDrops.clear();
    }
}

package com.gokirlbankedxp.service;

import com.gokirlbankedxp.GokIrlBankedXpConfig;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigProfile;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Durable storage for banked XP, and the only place balances are written to or
 * read from.
 *
 * <p>Banked XP is user data, not a setting, but until this store existed it lived
 * solely in RuneLite's profile config. That config is not a safe home on its
 * own: RuneLite uploads it to the user's account every few minutes, and if one
 * upload fails it marks the profile as out of date and, on the next launch,
 * replaces the local file with the server's copy. Everything banked since the
 * last successful upload silently rolls back. That is what a user hit after a
 * five-hour session — every deposit gone, one stale balance left.</p>
 *
 * <p>So every save is written to two places:</p>
 * <ul>
 *   <li><b>RuneLite config</b> ({@value #XP_KEY} and {@value #SAVED_AT_KEY} in the
 *       plugin's group). Kept because it is what existing users already have, and
 *       because it follows a synced profile between machines.</li>
 *   <li><b>A plugin-owned file</b> under {@code ~/.runelite/gok-irl-xp/}, one per
 *       RuneLite config profile. RuneLite never touches it, so nothing in its sync
 *       or profile machinery can roll it back.</li>
 * </ul>
 *
 * <p>Both copies carry the time they were saved. {@link #load()} reads both and
 * keeps the newest, then rewrites the other so they agree again. If config was
 * rolled back, the file is newer and wins. If the config was synced from another
 * machine where the user banked more recently, the config is newer and wins. A
 * copy that does not exist always loses to one that does.</p>
 *
 * <p>Every method here runs on whichever thread the plugin mutates balances on —
 * the Swing thread for deposits, the timer executor for accrual, and the client
 * thread for XP drops. The file write is a few hundred bytes with no fsync, and
 * is done atomically (temp file plus rename) so a crash mid-write leaves the old
 * file, never a half-written one.</p>
 *
 * <p>{@code @Singleton}: the plugin is the only consumer today, but the last
 * written config value is what lets it tell its own {@code ConfigChanged} echo
 * from a real external change, and that memory has to be shared with whoever
 * else might write in future.</p>
 */
@Singleton
public class BankedXpStore
{
    private static final Logger log = LoggerFactory.getLogger(BankedXpStore.class);

    /** Config key holding the balances, as {@code SKILL:xp} entries joined by commas. */
    public static final String XP_KEY = "storedSkillXp";
    /** Config key holding the epoch-millisecond time {@link #XP_KEY} was last written. */
    public static final String SAVED_AT_KEY = "storedSkillXpSavedAt";

    private static final String ENTRY_DELIMITER = ",";
    private static final String VALUE_DELIMITER = ":";
    private static final String DATA_DIR_NAME = "gok-irl-xp";
    private static final String FILE_PREFIX = "banked-xp";
    private static final String FILE_SUFFIX = ".json";

    /** Save time reported for a copy that does not exist, so it loses to any real copy. */
    static final long ABSENT = -1L;
    /**
     * Save time reported for a config copy written before timestamps existed. It
     * beats nothing but an absent copy, so a user's first launch after this change
     * migrates their existing config balances into the file rather than losing them.
     */
    static final long LEGACY = 0L;

    private final ConfigManager configManager;
    private final Gson gson;
    private final File dataDir;

    /**
     * The exact string most recently written to {@link #XP_KEY}. RuneLite posts a
     * {@code ConfigChanged} synchronously for every write, including this store's
     * own; the plugin compares the event's new value against this to ignore the
     * echo. Volatile because the write and the event can be on different threads
     * from the one that later asks.
     */
    private volatile String lastWrittenConfigValue;

    /** Save time of the last copy written or loaded; keeps save times strictly increasing. */
    private long lastSavedAt = ABSENT;

    @Inject
    public BankedXpStore(ConfigManager configManager, Gson gson)
    {
        this(configManager, gson, new File(RuneLite.RUNELITE_DIR, DATA_DIR_NAME));
    }

    /**
     * @param dataDir where the per-profile JSON files live. Production uses
     *     {@code ~/.runelite/gok-irl-xp}; tests point this at a temporary directory.
     */
    public BankedXpStore(ConfigManager configManager, Gson gson, File dataDir)
    {
        this.configManager = configManager;
        this.gson = gson;
        this.dataDir = dataDir;
    }

    /**
     * Reads both copies, keeps the newest, and brings the other up to date.
     *
     * @return the balances to use, only ever holding skills with a non-zero
     *     amount. A negative amount is XP the skill owes after in-game gains
     *     outran the bank; the plugin nets later deposits against it.
     */
    public synchronized Map<Skill, Long> load()
    {
        Copy fromConfig = readConfig();
        Copy fromFile = readFile();

        // Strictly newer wins. On a tie — normally both copies of the same save —
        // the file is preferred because RuneLite cannot have altered it.
        Copy winner = fromConfig.savedAt > fromFile.savedAt ? fromConfig : fromFile;
        if (winner.savedAt == ABSENT)
        {
            log.debug("No banked XP saved anywhere yet");
        }
        else if (winner == fromFile && fromConfig.savedAt < fromFile.savedAt)
        {
            log.info("Banked XP config copy ({}) is older than the local file ({}); restoring from file",
                describe(fromConfig), describe(fromFile));
        }

        write(winner);
        // Built empty then filled: EnumMap's copy constructor rejects an empty
        // plain map, which is exactly what an absent copy carries.
        Map<Skill, Long> result = new EnumMap<>(Skill.class);
        result.putAll(winner.balances);
        return result;
    }

    /**
     * Writes the balances to both copies with a fresh save time.
     *
     * @param balances skills with their balance, positive for banked XP and
     *     negative for XP owed; entries at exactly zero are dropped
     */
    public synchronized void save(Map<Skill, Long> balances)
    {
        // Wall-clock time, nudged forward if the clock went backwards, so a later
        // save always compares as newer than an earlier one.
        long savedAt = Math.max(System.currentTimeMillis(), lastSavedAt + 1);
        write(new Copy(savedAt, balances));
    }

    /**
     * Whether a {@code ConfigChanged} new value is the echo of this store's own
     * most recent config write, as opposed to a change made by RuneLite itself
     * (a profile switch, a sync from the server, or a reset from the settings panel).
     */
    public boolean isOwnConfigValue(String configValue)
    {
        return configValue != null && configValue.equals(lastWrittenConfigValue);
    }

    /** The file holding the active config profile's balances. */
    File dataFile()
    {
        // Balances are scoped to the RuneLite config profile, exactly as the config
        // copy is, so a user who keeps separate profiles keeps separate banks. The
        // profile is read on every call rather than cached because RuneLite can
        // switch profiles while the plugin is running.
        ConfigProfile profile = configManager.getProfile();
        String name = profile == null
            ? FILE_PREFIX + FILE_SUFFIX
            : FILE_PREFIX + "-" + profile.getId() + FILE_SUFFIX;
        return new File(dataDir, name);
    }

    // ---- writing ----------------------------------------------------------

    private void write(Copy copy)
    {
        String serialized = serializeBalances(copy.balances);

        // Recorded before the config write, because ConfigManager posts the
        // ConfigChanged event synchronously from inside setConfiguration and the
        // plugin's listener compares against this field while handling it.
        lastWrittenConfigValue = serialized;
        configManager.setConfiguration(GokIrlBankedXpConfig.GROUP, XP_KEY, serialized);
        configManager.setConfiguration(GokIrlBankedXpConfig.GROUP, SAVED_AT_KEY, Long.toString(copy.savedAt));

        writeFile(copy);
        lastSavedAt = copy.savedAt;
    }

    /**
     * {@code SKILL:xp} entries in {@link Skill} declaration order (the order the
     * previous format used too), or the empty string when nothing is banked or
     * owed. A debt is written with its sign, e.g. {@code WOODCUTTING:-5000}.
     */
    private static String serializeBalances(Map<Skill, Long> balances)
    {
        StringBuilder out = new StringBuilder();
        // TreeMap so the order is stable regardless of the input map type.
        for (Map.Entry<Skill, Long> entry : new TreeMap<>(balances).entrySet())
        {
            if (entry.getValue() == null || entry.getValue() == 0)
            {
                continue;
            }
            if (out.length() > 0)
            {
                out.append(ENTRY_DELIMITER);
            }
            out.append(entry.getKey().name()).append(VALUE_DELIMITER).append(entry.getValue());
        }
        return out.toString();
    }

    private void writeFile(Copy copy)
    {
        FileContents contents = new FileContents();
        contents.savedAt = copy.savedAt;
        contents.skills = new LinkedHashMap<>();
        for (Map.Entry<Skill, Long> entry : new TreeMap<>(copy.balances).entrySet())
        {
            if (entry.getValue() != null && entry.getValue() != 0)
            {
                contents.skills.put(entry.getKey().name(), entry.getValue());
            }
        }

        File target = dataFile();
        try
        {
            Files.createDirectories(dataDir.toPath());
            // Write beside the target and rename over it, so the file on disk is
            // always either the previous complete save or this one.
            Path temp = new File(dataDir, target.getName() + ".tmp").toPath();
            Files.write(temp, gson.toJson(contents).getBytes(StandardCharsets.UTF_8));
            try
            {
                Files.move(temp, target.toPath(), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            }
            catch (AtomicMoveNotSupportedException ex)
            {
                Files.move(temp, target.toPath(), StandardCopyOption.REPLACE_EXISTING);
            }
        }
        catch (IOException ex)
        {
            // The config copy was written first, so nothing is lost yet; the file
            // simply stays at its previous save until the next write succeeds.
            log.warn("Unable to write banked XP to {}", target, ex);
        }
    }

    // ---- reading ----------------------------------------------------------

    private Copy readConfig()
    {
        String serialized = configManager.getConfiguration(GokIrlBankedXpConfig.GROUP, XP_KEY);
        if (serialized == null)
        {
            return Copy.absent();
        }

        String savedAtRaw = configManager.getConfiguration(GokIrlBankedXpConfig.GROUP, SAVED_AT_KEY);
        long savedAt = LEGACY;
        if (savedAtRaw != null)
        {
            try
            {
                savedAt = Long.parseLong(savedAtRaw.trim());
            }
            catch (NumberFormatException ex)
            {
                log.debug("Ignoring unparseable banked XP save time [{}]", savedAtRaw);
            }
        }

        Map<Skill, Long> balances = new EnumMap<>(Skill.class);
        for (String entry : serialized.split(ENTRY_DELIMITER))
        {
            String[] parts = entry.split(VALUE_DELIMITER);
            if (parts.length != 2)
            {
                continue;
            }
            putIfValid(balances, parts[0], parts[1]);
        }
        return new Copy(savedAt, balances);
    }

    private Copy readFile()
    {
        File file = dataFile();
        String json;
        try
        {
            json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
        }
        catch (NoSuchFileException ex)
        {
            return Copy.absent();
        }
        catch (IOException ex)
        {
            log.warn("Unable to read banked XP from {}", file, ex);
            return Copy.absent();
        }

        FileContents contents;
        try
        {
            contents = gson.fromJson(json, FileContents.class);
        }
        catch (JsonParseException ex)
        {
            contents = null;
        }
        if (contents == null || contents.skills == null)
        {
            // Keep the damaged file for the user to inspect instead of overwriting
            // it on the next save; the config copy carries on as the source.
            File aside = new File(dataDir, file.getName() + ".corrupt-" + System.currentTimeMillis());
            log.warn("Banked XP file {} is unreadable; moving it to {}", file, aside);
            if (!file.renameTo(aside))
            {
                log.warn("Unable to move {} aside", file);
            }
            return Copy.absent();
        }

        Map<Skill, Long> balances = new EnumMap<>(Skill.class);
        for (Map.Entry<String, Long> entry : contents.skills.entrySet())
        {
            if (entry.getValue() != null)
            {
                putIfValid(balances, entry.getKey(), Long.toString(entry.getValue()));
            }
        }
        return new Copy(contents.savedAt, balances);
    }

    /**
     * Adds one entry when the skill name is known and the amount is a non-zero
     * number. Negative amounts are debts and are kept; only an explicit zero is
     * dropped, because it carries the same meaning as no entry.
     */
    private static void putIfValid(Map<Skill, Long> into, String skillName, String amountRaw)
    {
        Skill skill = parseSkill(skillName);
        if (skill == null)
        {
            return;
        }
        try
        {
            long amount = Long.parseLong(amountRaw.trim());
            if (amount != 0)
            {
                into.put(skill, amount);
            }
        }
        catch (NumberFormatException ex)
        {
            log.debug("Ignoring banked XP entry [{}:{}]", skillName, amountRaw);
        }
    }

    /** Null for a name no {@link Skill} carries, so a removed skill drops out rather than failing the load. */
    private static Skill parseSkill(String raw)
    {
        if (raw == null || raw.isBlank())
        {
            return null;
        }
        try
        {
            return Skill.valueOf(raw.trim().toUpperCase(Locale.ROOT));
        }
        catch (IllegalArgumentException ex)
        {
            return null;
        }
    }

    private static String describe(Copy copy)
    {
        return copy.savedAt == ABSENT ? "absent" : "saved at " + copy.savedAt;
    }

    /** One copy of the balances together with when it was saved. */
    private static final class Copy
    {
        final long savedAt;
        final Map<Skill, Long> balances;

        Copy(long savedAt, Map<Skill, Long> balances)
        {
            this.savedAt = savedAt;
            this.balances = balances;
        }

        static Copy absent()
        {
            return new Copy(ABSENT, Collections.emptyMap());
        }
    }

    /**
     * On-disk shape of the JSON file: {@code {"savedAt": 1725000000000, "skills": {"AGILITY": 5850}}}.
     * Skill names are stored as strings rather than the enum so an unknown name is
     * skipped on read instead of failing the whole parse.
     */
    private static class FileContents
    {
        long savedAt;
        Map<String, Long> skills;

        FileContents()
        {
        }
    }
}

package com.gokirlbankedxp.service;

import com.gokirlbankedxp.GokIrlBankedXpConfig;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Remembers what level the player is in each skill, including while logged out.
 *
 * <p>{@link com.gokirlbankedxp.service.XpMultiplierManager} needs a level to pick
 * a tier, and XP is banked from three places that are all off the client thread:
 * the Swing sidebar, the timer scheduler, and the log-completed-work form. Rather
 * than reach into {@link net.runelite.api.Client} from those threads, the plugin
 * pushes every experience reading it already observes on the client thread into
 * this tracker, and everything else reads the cached answer.</p>
 *
 * <p>Levels are persisted, unlike the plugin's in-memory {@code lastKnownXp} map.
 * The sidebar works at the login screen — logging a run before you log in is a
 * normal thing to do — and without a saved level every such deposit would be
 * multiplied as though the player were level 1. Writes only happen when a level
 * actually changes, so a level-up (rare) costs a config write and ordinary XP
 * drops (constant) cost nothing.</p>
 *
 * <p>{@code @Singleton} because the plugin writes to it and the multiplier
 * service and sidebar read from it; unscoped, each would hold its own map and
 * only the plugin's would ever be filled in.</p>
 */
@Singleton
public class SkillLevelTracker
{
    private static final Logger log = LoggerFactory.getLogger(SkillLevelTracker.class);

    /** Hidden config key; the levels are observed data, never user-edited. */
    private static final String CONFIG_KEY = "observedSkillLevels";

    /**
     * Persisted as skill name to level rather than as a {@code Map<Skill, Integer>}
     * so that a skill removed from a future RuneLite release degrades to an
     * ignored entry instead of failing the whole parse.
     */
    private static final Type LEVEL_MAP_TYPE = new TypeToken<Map<String, Integer>>()
    {
    }.getType();

    /** What an unobserved skill reports, matching a fresh account. */
    public static final int UNKNOWN_LEVEL = 1;

    private final ConfigManager configManager;
    private final Gson gson;

    private final Object lock = new Object();
    private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);

    /**
     * The shared Gson instance is injected rather than constructed; the Plugin
     * Hub build fails on plugin sources that construct their own Gson.
     */
    @Inject
    public SkillLevelTracker(ConfigManager configManager, Gson gson)
    {
        this.configManager = Objects.requireNonNull(configManager);
        this.gson = Objects.requireNonNull(gson);
    }

    /** Reads the saved levels back in. Called once as the plugin starts up. */
    public void load()
    {
        String raw = configManager.getConfiguration(GokIrlBankedXpConfig.GROUP, CONFIG_KEY);

        synchronized (lock)
        {
            levels.clear();

            if (raw == null || raw.isBlank())
            {
                return;
            }

            try
            {
                Map<String, Integer> parsed = gson.fromJson(raw, LEVEL_MAP_TYPE);
                if (parsed == null)
                {
                    return;
                }

                parsed.forEach((name, level) -> {
                    Skill skill = parseSkill(name);
                    if (skill != null && level != null)
                    {
                        levels.put(skill, clampLevel(level));
                    }
                });
            }
            catch (JsonParseException ex)
            {
                log.warn("Failed to parse observed skill levels; relearning them from the client", ex);
            }
        }
    }

    /**
     * Records an experience reading for a skill and derives its level.
     *
     * <p>Must be called from the client thread, because that is where the
     * experience value comes from. Nothing is written to config unless the
     * derived level differs from what was already stored.</p>
     *
     * @param experience total experience in the skill, as the client reports it
     * @return the level now recorded for the skill
     */
    public int recordExperience(Skill skill, int experience)
    {
        if (skill == null)
        {
            return UNKNOWN_LEVEL;
        }

        // Experience.getLevelForXp returns virtual levels up to 126 and throws on
        // a negative argument, so a nonsensical reading is floored rather than
        // allowed to blow up the caller's event handler.
        int level = clampLevel(Experience.getLevelForXp(Math.max(0, experience)));

        boolean changed;
        synchronized (lock)
        {
            Integer previous = levels.put(skill, level);
            changed = previous == null || previous != level;
            if (changed)
            {
                persistLocked();
            }
        }

        return level;
    }

    /**
     * The last level observed for a skill.
     *
     * @return the observed level, or {@link #UNKNOWN_LEVEL} for a skill this
     *     plugin has never seen an experience reading for
     */
    public int getLevel(Skill skill)
    {
        if (skill == null)
        {
            return UNKNOWN_LEVEL;
        }

        synchronized (lock)
        {
            return levels.getOrDefault(skill, UNKNOWN_LEVEL);
        }
    }

    /** Whether a real reading has been seen for this skill, as opposed to the level-1 default. */
    public boolean hasObserved(Skill skill)
    {
        if (skill == null)
        {
            return false;
        }

        synchronized (lock)
        {
            return levels.containsKey(skill);
        }
    }

    /** Every observed level, for display. Never the live map. */
    public Map<Skill, Integer> getObservedLevels()
    {
        synchronized (lock)
        {
            return new EnumMap<>(levels);
        }
    }

    /**
     * Writes the observed levels out.
     *
     * <p>Sorted by skill name so the stored value is stable: an unordered map
     * would reserialize differently run to run and churn the config file even
     * when nothing changed.</p>
     */
    private void persistLocked()
    {
        Map<String, Integer> serializable = new TreeMap<>();
        levels.forEach((skill, level) -> serializable.put(skill.name(), level));
        configManager.setConfiguration(
            GokIrlBankedXpConfig.GROUP, CONFIG_KEY, gson.toJson(new LinkedHashMap<>(serializable)));
    }

    private static int clampLevel(int level)
    {
        return Math.min(Experience.MAX_VIRT_LEVEL, Math.max(UNKNOWN_LEVEL, level));
    }

    private static Skill parseSkill(String raw)
    {
        if (raw == null || raw.isBlank())
        {
            return null;
        }

        try
        {
            return Skill.valueOf(raw.trim().toUpperCase(Locale.ROOT));
        }
        catch (IllegalArgumentException ex)
        {
            return null;
        }
    }
}

package com.gokirlbankedxp;

import com.google.common.math.LongMath;
import com.google.inject.Provides;
import com.gokirlbankedxp.service.BankedXpStore;
import com.gokirlbankedxp.service.DepletionForecaster;
import com.gokirlbankedxp.service.IrlActionManager;
import com.gokirlbankedxp.service.SkillLevelTracker;
import com.gokirlbankedxp.service.TimerManager;
import com.gokirlbankedxp.service.XpMultiplierManager;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Value;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigProfile;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.QuantityFormatter;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(
    name = "IRL XP",
    description = "Turn real-world actions into banked RuneScape XP and track it as you train.",
    tags = {"banked", "experience", "irl", "xp"}
)
public class GokIrlBankedXpPlugin extends Plugin
{
    // Skill.OVERALL is a deprecated null sentinel; Skill.values() already omits it.
    private static final Skill[] TRACKABLE_SKILLS = Skill.values();

    private static final BufferedImage NAV_ICON = buildIcon();

    private final Object dataLock = new Object();
    /**
     * The balance of every skill that has one. Positive is XP banked and waiting
     * to be spent in-game; negative is XP owed, because in-game gains outran what
     * was banked (see {@link #subtractXpLocked}). Zero is never stored — a skill
     * with nothing banked and nothing owed simply has no entry.
     */
    private final Map<Skill, Long> storedXp = new EnumMap<>(Skill.class);
    /**
     * The in-game XP of every skill the last time this plugin looked, so an XP
     * drop can be measured as "new total minus this". It is session state on
     * purpose: it is read from the client once each login has finished, so XP
     * gained without the plugin running is never charged against the bank.
     */
    private final Map<Skill, Integer> lastKnownXp = new EnumMap<>(Skill.class);
    /**
     * Game ticks still to wait before {@link #lastKnownXp} can be read after a
     * login, world hop, or plugin start.
     *
     * <p>The client reports 0 XP for every skill until it has processed the
     * login's stat sync, which lands <em>after</em> {@link GameState#LOGGED_IN}
     * is announced. Reading the baseline at that moment on a freshly started
     * client recorded 0 for every skill, and the sync's own {@link StatChanged}
     * burst was then charged against the bank as if the player had just earned
     * their whole XP total. RuneLite's XP tracker waits this many ticks for the
     * same reason ("xp is not available until after login is finished").</p>
     *
     * <p>Only ever touched on the client thread, which is where every game
     * event and both lifecycle hooks are delivered.</p>
     */
    private int loginSyncTicksRemaining;
    /** How long the XP tracker waits after a login before trusting skill XP. */
    private static final int LOGIN_SYNC_TICKS = 2;
    /** Skills already warned about crossing {@code lowXpThreshold}, so the chat line is sent once. */
    private final Set<Skill> warnedSkills = EnumSet.noneOf(Skill.class);
    /**
     * Skills already warned about imminent depletion.
     *
     * <p>Kept separate from {@link #warnedSkills} because the two warnings answer
     * different questions — a fixed XP threshold versus "how many more actions can
     * you take" — and each has to be able to re-arm without silencing the other.</p>
     */
    private final Set<Skill> depletionWarnedSkills = EnumSet.noneOf(Skill.class);

    private volatile BankedXpSnapshot currentSnapshot = BankedXpSnapshot.empty();
    private NavigationButton navigationButton;
    private volatile Long loadedProfileId;
    private volatile boolean profileLoaded;

    @Inject
    private ConfigManager configManager;

    private Long currentProfileId()
    {
        ConfigProfile profile = configManager.getProfile();
        return profile == null ? null : profile.getId();
    }

    /** Reject work from the previous profile during ConfigManager's event-delivery gap. */
    private boolean isProfileCurrent()
    {
        return !profileLoaded || Objects.equals(loadedProfileId, currentProfileId());
    }

    @Inject
    private Client client;

    @Inject
    private GokIrlBankedXpConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private GokIrlBankedXpOverlay overlay;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private GokIrlXpPanel panel;

    @Inject
    private IrlActionManager irlActionManager;

    @Inject
    private TimerManager timerManager;

    @Inject
    private DepletionForecaster depletionForecaster;

    @Inject
    private SkillLevelTracker skillLevelTracker;

    @Inject
    private XpMultiplierManager xpMultiplierManager;

    @Inject
    private Notifier notifier;

    /**
     * Where balances are saved and loaded. The plugin never touches config for
     * banked XP directly; see {@link BankedXpStore} for why there are two copies.
     */
    @Inject
    private BankedXpStore bankedXpStore;

    @Provides
    GokIrlBankedXpConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GokIrlBankedXpConfig.class);
    }

    @Override
    protected void startUp()
    {
        loadedProfileId = currentProfileId();
        profileLoaded = true;
        overlayManager.add(overlay);
        navigationButton = NavigationButton.builder()
            .tooltip("IRL XP")
            .icon(NAV_ICON)
            .priority(5)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navigationButton);

        irlActionManager.loadActions();
        // Both are read before the first deposit can happen. A level multiplier
        // needs the saved tiers and the player's last observed level to resolve
        // at all, and an unloaded manager would quietly bank everything at 1.00x.
        skillLevelTracker.load();
        xpMultiplierManager.load();
        // startUp() runs on the client thread, so every Swing mutation below has
        // to be handed to the EDT rather than performed inline.
        SwingUtilities.invokeLater(panel::refreshActions);
        loadStoredXp();
        timerManager.startUp();
        // The XP baseline is taken on a later game tick rather than here. If the
        // plugin was just enabled mid-session the client already has real skill
        // XP and the wait costs nothing; if it starts at the login screen, no
        // tick fires until a login has happened and reset the wait anyway.
        beginLoginSync();
        rebuildSnapshotAndNotify();
    }

    @Override
    protected void shutDown()
    {
        // Like startUp(), this runs on the client thread; the panel's Swing
        // refresh timer must be stopped from the EDT.
        SwingUtilities.invokeLater(panel::stopUiUpdates);
        if (timerManager != null)
        {
            timerManager.shutDown();
        }

        overlayManager.remove(overlay);
        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
            navigationButton = null;
        }
        // Learned XP-drop rates are session state, not saved data: a reloaded
        // plugin relearns them from the first few drops rather than acting on
        // rates from whatever the user was training hours ago.
        depletionForecaster.clear();
        loginSyncTicksRemaining = 0;
        synchronized (dataLock)
        {
            storedXp.clear();
            lastKnownXp.clear();
            warnedSkills.clear();
            depletionWarnedSkills.clear();
            currentSnapshot = BankedXpSnapshot.empty();
        }

        SwingUtilities.invokeLater(() -> panel.updateSnapshot(BankedXpSnapshot.empty()));
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (!isProfileCurrent())
        {
            return;
        }
        Skill skill = event.getSkill();
        if (skill == null)
        {
            return;
        }

        int newXp = event.getXp();

        // Fed to the tracker outside the data lock, and before anything else,
        // because this is the client thread — the only place a live experience
        // reading is available. Everything that banks XP runs on some other
        // thread and reads the level back from the tracker instead of the client.
        skillLevelTracker.recordExperience(skill, newXp);

        if (loginSyncTicksRemaining > 0)
        {
            // This is the stat sync the server sends on login: the player's
            // existing totals, not XP just earned. The baseline is read from the
            // client once the sync has landed (see onGameTick), so nothing here
            // may be measured against the bank.
            return;
        }

        boolean changed = false;
        String depletionWarning = null;

        synchronized (dataLock)
        {
            Integer previous = lastKnownXp.put(skill, newXp);
            if (previous == null)
            {
                return;
            }

            int delta = newXp - previous;
            if (delta <= 0)
            {
                return;
            }

            changed = subtractXpLocked(skill, delta);
            if (changed)
            {
                depletionWarning = evaluateDepletionLocked(skill, delta);
            }
        }

        // Fired outside the lock on purpose: the notifier posts to the event bus
        // and touches the client UI, and neither should run while this plugin's
        // data lock is held.
        if (depletionWarning != null)
        {
            notifier.notify(config.depletionNotification(), depletionWarning);
        }

        if (changed)
        {
            rebuildSnapshotAndNotify();
        }
    }

    /**
     * Decides whether this XP drop means the skill is about to run dry.
     *
     * <p>Feeds the drop to {@link DepletionForecaster} and compares what the next
     * {@code depletionWarningActions} actions are predicted to cost against what
     * is actually left. Called with {@link #dataLock} held so the remaining total
     * it reads is the one this drop just produced.</p>
     *
     * @return the message to notify with, or null when nothing should be sent
     */
    private String evaluateDepletionLocked(Skill skill, long delta)
    {
        int window = Math.max(0, config.depletionWarningActions());
        if (window <= 0)
        {
            // Feature switched off: forget any standing warning so re-enabling it
            // starts clean rather than staying silent on an old flag.
            depletionWarnedSkills.remove(skill);
            return null;
        }

        depletionForecaster.recordDrop(skill, delta, window);

        long remaining = storedXp.getOrDefault(skill, 0L);
        if (remaining <= 0)
        {
            // Already spent, or in debt. There is nothing left to warn about, and
            // re-arming here means the next top-up gets a fresh warning. The drop
            // was still recorded above: the rate it teaches is just as valid for
            // when the skill is topped up again.
            depletionWarnedSkills.remove(skill);
            return null;
        }

        long forecast = depletionForecaster.forecast(skill, window);
        if (forecast <= 0 || remaining > forecast)
        {
            // Either no rate learned yet, or comfortably more than the next
            // `window` actions will consume.
            //
            // Deliberately not re-armed here. A drop only ever lowers the
            // balance, so the only way this branch is reached after a warning
            // is the forecast itself moving — and in combat it moves on every
            // hit. Re-arming on that flip meant the red flash fired again on
            // the very next drop, then again, all the way down. The warning is
            // once per top-up: a deposit, a removal, a reload, or the skill
            // running dry (below) is what re-arms it.
            return null;
        }

        if (!depletionWarnedSkills.add(skill))
        {
            // Already warned and the balance has not recovered since.
            return null;
        }

        // Turn "XP left" back into "actions left" using the same samples the
        // forecast came from, because that is the unit the warning promises.
        long averageDrop = depletionForecaster.averageDrop(skill);
        long actionsLeft = averageDrop <= 0 ? window : Math.max(1L, remaining / averageDrop);

        return String.format(
            Locale.US,
            "%s banked XP is nearly gone: %s left, about %d more action%s.",
            skill.getName(),
            QuantityFormatter.formatNumber(remaining),
            actionsLeft,
            actionsLeft == 1 ? "" : "s"
        );
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();
        // Both states precede a full stat sync from the server: a login sends
        // every skill, and a world hop is a fresh login to another world. The
        // LOGGED_IN state is deliberately not used — it fires before the sync
        // has been processed (and again on every region change), so the skill
        // XP the client reports at that moment is 0 on a fresh client.
        if (state == GameState.LOGGING_IN || state == GameState.HOPPING)
        {
            beginLoginSync();
        }
    }

    /**
     * Counts down the wait started by {@link #beginLoginSync()} and, when it
     * ends, reads the XP baseline from the client. Game ticks only fire while
     * logged in, so reaching zero here means a login has completed.
     */
    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (loginSyncTicksRemaining <= 0)
        {
            return;
        }

        loginSyncTicksRemaining--;
        if (loginSyncTicksRemaining > 0)
        {
            return;
        }

        if (!refreshLastKnownXp())
        {
            // The sync has still not landed; try again next tick rather than
            // record a baseline of zeros. Until it does, XP drops keep being
            // ignored, which loses nothing: the baseline read later already
            // includes them.
            loginSyncTicksRemaining = 1;
            return;
        }

        rebuildSnapshotAndNotify();
    }

    /**
     * Forgets the XP baseline and starts the post-login wait.
     *
     * <p>Clearing the baseline is what makes the wait safe: with no previous
     * reading on file, nothing can be measured until {@link #onGameTick} has
     * read real figures from the client.</p>
     */
    private void beginLoginSync()
    {
        loginSyncTicksRemaining = LOGIN_SYNC_TICKS;
        synchronized (dataLock)
        {
            lastKnownXp.clear();
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!GokIrlBankedXpConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }

        // A profile switch emits per-key events before ProfileChanged. Wait for
        // the complete transition rather than mixing new balances with old timers.
        if (!isProfileCurrent())
        {
            return;
        }

        boolean needsRefresh = false;
        if ("lowXpThreshold".equals(event.getKey()))
        {
            needsRefresh = true;
        }
        else if ("levelMultipliersEnabled".equals(event.getKey()))
        {
            // The master switch changes what every deposit is worth, and the
            // sidebar states that figure in two places: the deposit preview and
            // the multipliers tab. Neither hears about settings changes on its
            // own, so without this they kept quoting the old multiplier until
            // the next XP drop happened to refresh them.
            needsRefresh = true;
        }
        else if ("depletionWarningActions".equals(event.getKey()))
        {
            // A new window means a new prediction, so any standing warning is
            // stale. Re-arm rather than leaving skills silenced under the old one.
            synchronized (dataLock)
            {
                depletionWarnedSkills.clear();
            }
        }
        else if (BankedXpStore.XP_KEY.equals(event.getKey()))
        {
            // ConfigManager posts this synchronously for every write, including the
            // store's own. Reloading on that echo re-parsed what was just saved and,
            // worse, cleared the warn-once sets on every XP drop. Only a value this
            // plugin did not write — a profile switch, a sync from the server, or a
            // reset from the settings panel — is a reason to reload.
            if (bankedXpStore.isOwnConfigValue(event.getNewValue()))
            {
                return;
            }
            loadStoredXp();
            needsRefresh = true;
        }

        if (needsRefresh)
        {
            rebuildSnapshotAndNotify();
        }
    }

    /** RuneLite leaves enabled plugins running when configuration profiles change. */
    @Subscribe
    public void onProfileChanged(ProfileChanged event)
    {
        timerManager.reloadProfile(() -> {
            loadedProfileId = currentProfileId();
            profileLoaded = true;
            irlActionManager.loadActions();
            skillLevelTracker.load();
            xpMultiplierManager.load();
            loadStoredXp();
            depletionForecaster.clear();
        });

        // The level tracker was just reloaded from the new profile's config,
        // which may never have seen this character. The XP baseline is session
        // state that belongs to the logged-in character, not the profile, so it
        // is still correct — and without feeding it back in, the first deposit
        // into each skill after a switch was multiplied as though the player
        // were level 1. Copied out first so the tracker's config writes (one
        // per changed level) never happen under the data lock.
        Map<Skill, Integer> knownXp;
        synchronized (dataLock)
        {
            knownXp = new EnumMap<>(lastKnownXp);
        }
        knownXp.forEach(skillLevelTracker::recordExperience);

        // Refresh every visible library, including an already-open multipliers tab.
        SwingUtilities.invokeLater(panel::refreshActions);
        rebuildSnapshotAndNotify();
    }

    /**
     * The one door XP comes in through, and therefore the one place the level
     * multiplier is applied.
     *
     * <p>Every route into the bank — the sidebar's "bank a chunk" form, a running
     * timer, and a logged completed session — lands here, so the multiplier is
     * applied exactly once per deposit no matter which route was taken. Putting it
     * anywhere further out would mean applying it in three places, and any preview
     * that scaled the amount itself would double it.</p>
     *
     * <p>Removals are pointedly not the inverse of this; see
     * {@link #removeManualXp}. A correction takes back a literal figure, because
     * the user is undoing an amount they can see in their balance, not re-earning
     * one.</p>
     *
     * <p>A deposit into a skill that is in debt pays the debt off first. Owing
     * 5,000 and banking 3,000 leaves the skill owing 2,000, and nothing shows as
     * banked until the whole debt is cleared. That is the point of the debt: XP
     * earned in-game ahead of the bank is still paid for with real-world effort,
     * just after the fact.</p>
     *
     * @param amount the base XP earned, before any multiplier
     * @return how much was actually credited after the multiplier, which is 0 when
     *     the skill's current tier multiplies by zero. This is the figure that
     *     moved the balance, whether it paid down a debt or added to the bank.
     */
    long addManualXp(Skill skill, long amount)
    {
        if (!isProfileCurrent() || skill == null || amount <= 0)
        {
            return 0L;
        }

        long banked = xpMultiplierManager.applyTo(skill, amount);
        if (banked <= 0)
        {
            // A deliberate 0x tier. Nothing is stored, and no warning state is
            // touched, because the balance did not move.
            return 0L;
        }

        synchronized (dataLock)
        {
            // The deposit lands on whatever the balance is, debt included.
            // Saturating: a huge total clamps at the long ceiling rather than
            // wrapping negative, which would now read as an enormous debt.
            long updated = LongMath.saturatedAdd(storedXp.getOrDefault(skill, 0L), banked);
            storeBalanceLocked(skill, updated);
            warnedSkills.remove(skill);
            depletionWarnedSkills.remove(skill);
            persistStoredXpLocked();
        }

        rebuildSnapshotAndNotify();
        return banked;
    }

    /**
     * Takes banked XP back out of a skill, for corrections only.
     *
     * <p>This is the undo for a mistyped or misdirected deposit, and it is
     * deliberately <em>not</em> the inverse of {@link #addManualXp}: it can only
     * ever reduce a balance the user already has, never create or deepen a
     * negative one. A skill that is in debt has nothing to take back, so removal
     * refuses it outright. The caller asks for an amount and is told what was
     * actually removed, so a request larger than the balance empties the skill
     * instead of failing or going below zero.</p>
     *
     * <p>A correction is not gameplay consumption, so it is kept out of the
     * warning machinery entirely: no low-XP chat line, no depletion flash, and no
     * sample handed to {@link DepletionForecaster} — an edit the user made in the
     * sidebar says nothing about what an in-game action costs.</p>
     *
     * @return how much was actually removed; 0 when the skill has no banked XP
     */
    long removeManualXp(Skill skill, long amount)
    {
        if (skill == null || amount <= 0)
        {
            return 0L;
        }

        long removed;
        synchronized (dataLock)
        {
            long current = storedXp.getOrDefault(skill, 0L);
            if (current <= 0)
            {
                return 0L;
            }

            removed = Math.min(amount, current);
            storeBalanceLocked(skill, current - removed);

            // Re-arm both warnings rather than firing them: the balance changed
            // because the user edited it, not because they trained.
            warnedSkills.remove(skill);
            depletionWarnedSkills.remove(skill);
            persistStoredXpLocked();
        }

        rebuildSnapshotAndNotify();
        return removed;
    }

    /**
     * The authoritative balance for a skill, used to bound removals. Negative
     * while the skill is in debt, and 0 for a skill with no entry at all.
     */
    long getBankedXp(Skill skill)
    {
        if (skill == null)
        {
            return 0L;
        }

        synchronized (dataLock)
        {
            return storedXp.getOrDefault(skill, 0L);
        }
    }

    /**
     * Banks XP earned from an IRL action, whether accrued by a live timer or
     * logged after the fact. Public because it is the services' entry point;
     * {@link #addManualXp} stays package-private for the XP tab's direct entry.
     *
     * @param amount the action's base XP, before the skill's level multiplier
     * @return how much was actually banked once the multiplier was applied, so
     *     callers can report the real figure rather than the one they asked for
     */
    public long addActionXp(Skill skill, long amount)
    {
        return addManualXp(skill, amount);
    }

    BankedXpSnapshot getCurrentSnapshot()
    {
        return currentSnapshot;
    }

    Skill[] getTrackableSkills()
    {
        return TRACKABLE_SKILLS.clone();
    }

    /**
     * Replaces the in-memory balances with whatever the store says is current.
     *
     * <p>Runs at start-up and whenever RuneLite changes the config copy from
     * outside this plugin. The read happens inside the lock: a read taken before
     * it could be overtaken by a deposit on another thread, and the stale result
     * would then be written back over the deposit.</p>
     */
    private void loadStoredXp()
    {
        synchronized (dataLock)
        {
            Map<Skill, Long> loaded = bankedXpStore.load();
            storedXp.clear();
            storedXp.putAll(loaded);
            // Balances may have changed under the warnings' feet, so both re-arm.
            warnedSkills.clear();
            depletionWarnedSkills.clear();
        }
    }

    /**
     * Reads every skill's XP from the client as the baseline later drops are
     * measured against.
     *
     * @return false when the client does not yet hold real figures, in which
     *         case nothing was recorded and the caller should try again later
     */
    private boolean refreshLastKnownXp()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return false;
        }

        // Every account has at least level 10 Hitpoints, so a reading of 0 XP
        // there can only mean the login stat sync has not been processed yet.
        // Taking the baseline now would record 0 for every skill and charge the
        // player's entire XP total against the bank on the next update.
        if (client.getSkillExperience(Skill.HITPOINTS) <= 0)
        {
            return false;
        }

        Map<Skill, Integer> observed = new EnumMap<>(Skill.class);
        for (Skill skill : TRACKABLE_SKILLS)
        {
            observed.put(skill, client.getSkillExperience(skill));
        }

        synchronized (dataLock)
        {
            lastKnownXp.putAll(observed);
        }

        // Deliberately outside the lock: recording a level writes to config when
        // it changes, and a config write is dispatched synchronously on the event
        // bus. Keeping it out here means the plugin's own config listener never
        // runs while this method holds the data lock.
        observed.forEach(skillLevelTracker::recordExperience);
        return true;
    }

    /**
     * Applies an in-game XP drop to a skill's balance, one for one.
     *
     * <p>This is the only place a balance can go below zero. When the drop is
     * bigger than what is banked — a quest reward, a lamp, or simply training a
     * skill with nothing banked — the balance keeps falling into a debt rather
     * than stopping at zero, and the next deposits pay that debt back before
     * anything shows as banked again (see {@link #addManualXp}). Deposits and
     * removals both refuse to create a debt, so one can only ever be earned in
     * the game. That is what keeps the bank honest: every XP the character gains
     * is eventually matched by real-world effort, whether banked before or
     * after.</p>
     *
     * <p>Saturating at the long floor, for the same reason deposits saturate at
     * the ceiling: a wrapped value would flip the sign and turn a debt into a
     * fortune.</p>
     *
     * @return whether the balance moved, which every positive drop makes it do
     */
    private boolean subtractXpLocked(Skill skill, long delta)
    {
        if (delta <= 0)
        {
            return false;
        }

        long current = storedXp.getOrDefault(skill, 0L);
        long updated = LongMath.saturatedSubtract(current, delta);
        storeBalanceLocked(skill, updated);

        handleThresholdLocked(skill, updated);
        persistStoredXpLocked();
        return updated != current;
    }

    /**
     * Writes a balance into {@link #storedXp}, dropping the entry when it is
     * exactly zero so "nothing banked, nothing owed" and "no entry" stay the same
     * state everywhere the map is read. Called with {@link #dataLock} held.
     */
    private void storeBalanceLocked(Skill skill, long balance)
    {
        if (balance == 0)
        {
            storedXp.remove(skill);
        }
        else
        {
            storedXp.put(skill, balance);
        }
    }

    private void handleThresholdLocked(Skill skill, long remaining)
    {
        int threshold = Math.max(0, config.lowXpThreshold());
        if (remaining > threshold)
        {
            warnedSkills.remove(skill);
            return;
        }

        if (remaining <= 0)
        {
            // Spent, or in debt. The low warning is about a balance that is
            // about to run out, not one that already has; the sidebar and
            // overlay show the debt itself. Re-arm so the next top-up warns again.
            warnedSkills.remove(skill);
            return;
        }

        if (config.chatWarningEnabled() && warnedSkills.add(skill))
        {
            String message = String.format(
                Locale.US,
                "%s banked XP low: %s remaining",
                skill.getName(),
                QuantityFormatter.formatNumber(remaining)
            );
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
        }
    }

    private void rebuildSnapshotAndNotify()
    {
        BankedXpSnapshot snapshot;
        synchronized (dataLock)
        {
            snapshot = buildSnapshotLocked();
            currentSnapshot = snapshot;
        }

        final BankedXpSnapshot published = snapshot;
        SwingUtilities.invokeLater(() -> panel.updateSnapshot(published));
    }

    private BankedXpSnapshot buildSnapshotLocked()
    {
        if (storedXp.isEmpty())
        {
            return BankedXpSnapshot.empty();
        }

        int threshold = Math.max(0, config.lowXpThreshold());
        List<BankedSkill> skills = new ArrayList<>();
        long total = 0;

        for (Map.Entry<Skill, Long> entry : storedXp.entrySet())
        {
            long remaining = entry.getValue();
            if (remaining == 0)
            {
                // Never stored (see storeBalanceLocked), but harmless to skip.
                continue;
            }

            Skill skill = entry.getKey();
            // The total is the net position: debts count against banked XP, so a
            // user with 10,000 banked in one skill and 4,000 owed in another sees
            // 6,000, which is what their real-world effort has actually covered.
            total = LongMath.saturatedAdd(total, remaining);
            skills.add(new BankedSkill(
                skill,
                skill.getName(),
                remaining,
                threshold,
                // LOW is a warning that a positive balance is nearly spent. A debt
                // is its own state, flagged by BankedSkill.isInDebt(), not a
                // very low balance.
                remaining > 0 && remaining <= threshold
            ));
        }

        if (skills.isEmpty())
        {
            return BankedXpSnapshot.empty();
        }

        // Largest balance first, which puts every debt at the bottom of the list.
        skills.sort(Comparator.comparingLong(BankedSkill::getRemainingXp).reversed());
        return new BankedXpSnapshot(total, List.copyOf(skills));
    }

    /** Saves the current balances; called with {@link #dataLock} held after every change. */
    private void persistStoredXpLocked()
    {
        // A profile may change after work began on the scheduler or client thread.
        // The forthcoming ProfileChanged reload replaces that obsolete in-memory state.
        if (isProfileCurrent())
        {
            bankedXpStore.save(storedXp);
        }
    }

    private static BufferedImage buildIcon()
    {
        BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();

        graphics.setColor(new Color(0xFF1F8A70, true));
        graphics.fillRect(0, 0, 16, 16);
        graphics.setColor(Color.WHITE);
        graphics.drawString("XP", 2, 12);
        graphics.dispose();

        return image;
    }

    /**
     * An immutable read of every balance, published to the sidebar and overlay
     * after each change so neither has to take {@link #dataLock}.
     */
    @Value
    static class BankedXpSnapshot
    {
        /** Net of every balance: banked XP minus XP owed. Can be zero or negative while any skill is in debt. */
        long totalXp;
        List<BankedSkill> skills;

        static BankedXpSnapshot empty()
        {
            return new BankedXpSnapshot(0L, Collections.emptyList());
        }

        /**
         * Whether there is anything to show. Judged on the skill list rather than
         * the total, because a bank that is entirely debt nets to zero or less
         * and is exactly the thing the user needs to see.
         */
        boolean hasData()
        {
            return !skills.isEmpty();
        }
    }

    @Value
    static class BankedSkill
    {
        Skill skill;
        String displayName;
        /** Positive: banked XP left to spend. Negative: XP owed after in-game gains outran the bank. */
        long remainingXp;
        int threshold;
        /** Only ever true for a positive balance; a debt is reported by {@link #isInDebt()} instead. */
        boolean belowThreshold;

        /** Whether in-game XP has outrun what was banked for this skill. */
        boolean isInDebt()
        {
            return remainingXp < 0;
        }
    }
}

