    }

    /**
     * A permanent signpost to the settings that are not in this sidebar.
     *
     * <p>RuneLite owns the settings panel, and a plugin cannot open it or move
     * its items into a sidebar tab. The warnings — the LOW marker, the chat
     * message, and the red screen flash as a skill runs dry — therefore live
     * somewhere the sidebar cannot show, and testers reliably failed to find
     * them. Naming the exact route, and the exact section headings to look for,
     * is the whole of what this note is for.</p>
     */
    private JPanel buildSettingsPointer()
    {
        JPanel card = IrlXpUi.card(new BorderLayout(0, 4));
        card.add(IrlXpUi.mutedLabel("Warnings & screen flash"), BorderLayout.NORTH);
        card.add(IrlXpUi.wrappingNote(
            "Set how and when you are warned that a skill is running out in RuneLite's own settings: "
                + "Configuration (the wrench) > IRL XP. Look for \"Low banked XP warning (chat)\" and "
                + "\"Almost-out warning (red screen flash)\".", 4), BorderLayout.CENTER);
        return card;
    }

    /**
     * Restates the typed deposit as the amount that will actually be banked.
     *
     * <p>Silent about the multiplier when there is none in force, so a user who
     * never touched the feature never sees a line about it. When one is in force
     * this is the only warning that "500" is about to become something else, and
     * it deliberately shows the same figure the plugin will bank, computed by the
     * same service, rather than a separately derived estimate.</p>
     */
    private void refreshDepositPreview()
    {
        Skill selected = (Skill) skillSelector.getSelectedItem();
        long typed = parsePositiveXp(xpField.getText());

        if (selected == null)
        {
            depositPreview.setText(" ");
            return;
        }

        double multiplier = multiplierManager.currentMultiplier(selected);
        if (multiplier == XpMultiplierManager.NEUTRAL_MULTIPLIER)
        {
            depositPreview.setText(" ");
            return;
        }

        if (multiplier == 0.0)
        {
            depositPreview.setText(String.format(
                Locale.US,
                "%s is set to 0.00x at your level, so nothing would be banked. Change it on the "
                    + "LEVEL MULTIPLIERS tab.",
                selected.getName()));
            return;
        }

        if (typed <= 0)
        {
            depositPreview.setText(String.format(
                Locale.US,
                "%s banks at %s right now.",
                selected.getName(),
                IrlXpUi.formatMultiplier(multiplier)));
            return;
        }

        depositPreview.setText(String.format(
            Locale.US,
            "Banks as %s XP (%s at %s).",
            QuantityFormatter.formatNumber(XpMultiplierManager.scale(typed, multiplier)),
            IrlXpUi.formatMultiplier(multiplier),
            selected.getName()));
    }

    /** The Add/Remove switch, styled like the sidebar's own tab strip. */
    private JPanel buildModeToggle()
    {
        JPanel toggle = new JPanel(new GridLayout(1, 2, 5, 0));
        toggle.setOpaque(false);

        configureModeButton(addModeButton, ADD_CARD);
        configureModeButton(removeModeButton, REMOVE_CARD);

        toggle.add(addModeButton);
        toggle.add(removeModeButton);
        return toggle;
    }

    private void configureModeButton(JButton button, String card)
    {
        button.setFont(button.getFont().deriveFont(Font.BOLD, 10f));
        button.setFocusPainted(false);
        button.setBorder(BorderFactory.createEmptyBorder(6, 5, 6, 5));
        button.addActionListener(event -> showMode(card));
    }

    private void showMode(String card)
    {
        boolean adding = ADD_CARD.equals(card);
        formLayout.show(formCards, card);
        styleModeButton(addModeButton, adding);
        styleModeButton(removeModeButton, !adding);
    }

    private void styleModeButton(JButton button, boolean selected)
    {
        button.setOpaque(true);
        button.setBackground(selected ? IrlXpUi.ACCENT : IrlXpUi.SURFACE_RAISED);
        button.setForeground(selected ? new java.awt.Color(0x18130B) : IrlXpUi.MUTED_TEXT);
    }

    /**
     * Builds the correction form.
     *
     * <p>Its skill drop-down is populated from the banked-XP snapshot rather than
     * from every skill in the game, so a skill with nothing banked simply is not
     * offered — there is no way to reach "subtract from an empty balance" through
     * this UI at all. The amount is checked against the live balance on submit as
     * well, because the snapshot can be a moment stale if XP drained in-game
     * while the form sat open.</p>
     */
    private JPanel buildRemoveForm()
    {
        JPanel removeForm = new JPanel(new GridBagLayout());
        removeForm.setOpaque(false);

        GridBagConstraints gc = new GridBagConstraints();
        gc.insets = FIELD_INSETS;
        gc.gridx = 0;
        gc.gridy = 0;
        gc.anchor = GridBagConstraints.WEST;
        gc.fill = GridBagConstraints.HORIZONTAL;
        gc.weightx = 1.0;
        gc.gridwidth = GridBagConstraints.REMAINDER;

        removeForm.add(IrlXpUi.sectionTitle("Correct a mistake"), gc);

        gc.gridy = 1;
        removeForm.add(IrlXpUi.wrappingNote(
            "Banked to the wrong skill, or typed too much? Take it back out here.", 2), gc);

        gc.gridy = 2;
        JLabel skillLabel = new JLabel("Skill");
        skillLabel.setForeground(IrlXpUi.MUTED_TEXT);
        removeForm.add(skillLabel, gc);

        gc.gridy = 3;
        removeSkillSelector.setPreferredSize(new Dimension(1, 32));
        removeSkillSelector.setRenderer(IrlXpUi.skillNameRenderer());
        removeSkillSelector.addActionListener(e -> refreshRemoveBalanceLabel());
        IrlXpUi.styleField(removeSkillSelector);
        removeForm.add(removeSkillSelector, gc);

        gc.gridy = 4;
        removeForm.add(removeBalanceLabel, gc);

        gc.gridy = 5;
        JLabel amountLabel = new JLabel("XP to remove");
        amountLabel.setForeground(IrlXpUi.MUTED_TEXT);
        removeForm.add(amountLabel, gc);

        gc.gridy = 6;
        removeXpField.setToolTipText("Enter a positive whole number, no larger than the banked amount");
        removeXpField.setCaretColor(IrlXpUi.TEXT);
        removeXpField.setPreferredSize(new Dimension(1, 36));
        IrlXpUi.styleField(removeXpField);
        removeXpField.addActionListener(e -> onRemoveXp());
        removeXpField.addMouseListener(new FocusOnClick(removeXpField));
        removeForm.add(removeXpField, gc);

        gc.gridy = 7;
        gc.insets = new Insets(8, 0, 0, 0);
        IrlXpUi.styleDangerButton(removeButton);
        removeButton.setFont(removeButton.getFont().deriveFont(Font.BOLD));
        removeButton.addActionListener(e -> onRemoveXp());
        removeForm.add(removeButton, gc);

        return removeForm;
    }

    void updateSnapshot(GokIrlBankedXpPlugin.BankedXpSnapshot snapshot)
    {
        SwingUtilities.invokeLater(() -> {
            skillListModel.clear();
            refreshRemovableSkills(snapshot);
            // A snapshot follows every XP change, and an XP change can be the
            // level-up that moves this skill onto a different multiplier tier.
            refreshDepositPreview();

            if (snapshot == null || !snapshot.hasData())
            {
                totalXpLabel.setText("0 XP");
                skillListModel.addElement("No banked XP yet — add your first chunk above.");
                return;
            }

            totalXpLabel.setText(QuantityFormatter.formatNumber(snapshot.getTotalXp()) + " XP");

            for (GokIrlBankedXpPlugin.BankedSkill entry : snapshot.getSkills())
            {
                // A debt prints with its minus sign (e.g. "-5,000 XP") and is
                // marked OWED; LOW is reserved for a positive balance nearly spent.
                String marker = "";
                if (entry.isInDebt())
                {
                    marker = "   OWED";
                }
                else if (entry.isBelowThreshold())
                {
                    marker = "   LOW";
                }
                String line = String.format(
                    Locale.US,
                    "%s   •   %s XP%s",
                    entry.getDisplayName(),
                    QuantityFormatter.formatNumber(entry.getRemainingXp()),
                    marker
                );
                skillListModel.addElement(line);
            }
        });
    }

    /**
     * Rebuilds the removal drop-down to hold exactly the skills with a positive
     * balance. A skill in debt is left out: there is nothing banked to take back,
     * and removal must never deepen a debt.
     *
     * <p>Already on the EDT — the only caller is inside {@link #updateSnapshot}'s
     * {@code invokeLater} — so it must not queue another round trip, or the
     * selection restored here would be undone by the listener firing afterwards.</p>
     */
    private void refreshRemovableSkills(GokIrlBankedXpPlugin.BankedXpSnapshot snapshot)
    {
        Skill previous = (Skill) removeSkillSelector.getSelectedItem();

        List<Skill> banked = new ArrayList<>();
        if (snapshot != null)
        {
            for (GokIrlBankedXpPlugin.BankedSkill entry : snapshot.getSkills())
            {
                if (entry.getRemainingXp() > 0)
                {
                    banked.add(entry.getSkill());
                }
            }
        }

        DefaultComboBoxModel<Skill> model = new DefaultComboBoxModel<>();
        for (Skill skill : banked)
        {
            model.addElement(skill);
        }
        removeSkillSelector.setModel(model);

        if (previous != null && banked.contains(previous))
        {
            removeSkillSelector.setSelectedItem(previous);
        }
        else if (!banked.isEmpty())
        {
            removeSkillSelector.setSelectedIndex(0);
        }

        // With nothing banked there is nothing to correct, so the whole form goes
        // inert rather than accepting input it would only reject.
        boolean anyBanked = !banked.isEmpty();
        removeSkillSelector.setEnabled(anyBanked);
        removeXpField.setEnabled(anyBanked);
        removeButton.setEnabled(anyBanked);
        if (!anyBanked)
        {
            removeXpField.setText("");
        }

        refreshRemoveBalanceLabel();
    }

    /** Shows the ceiling for the current removal, so the cap is never a surprise. */
    private void refreshRemoveBalanceLabel()
    {
        Skill selected = (Skill) removeSkillSelector.getSelectedItem();
        if (selected == null)
        {
            removeBalanceLabel.setText("Nothing banked yet.");
            return;
        }

        removeBalanceLabel.setText(String.format(
            Locale.US,
            "Banked: %s XP — remove up to that.",
            QuantityFormatter.formatNumber(plugin.getBankedXp(selected))));
    }

    private void onAddXp()
    {
        Skill selectedSkill = (Skill) skillSelector.getSelectedItem();
        if (selectedSkill == null)
        {
            return;
        }

        long xp = parsePositiveXp(xpField.getText());
        if (xp <= 0)
        {
            JOptionPane.showMessageDialog(
                this,
                "Please enter a positive whole number.",
                "Invalid XP amount",
                JOptionPane.WARNING_MESSAGE
            );
            xpField.requestFocusInWindow();
            xpField.selectAll();
            return;
        }

        long banked = plugin.addManualXp(selectedSkill, xp);
        if (banked <= 0)
        {
            // The deposit was accepted but moved nothing. The only ordinary way
            // that happens is a 0.00x tier; saying so here beats a field that
            // clears itself as though the XP had gone somewhere.
            boolean zeroTier = multiplierManager.currentMultiplier(selectedSkill) == 0.0;
            JOptionPane.showMessageDialog(
                this,
                zeroTier
                    ? String.format(
                        Locale.US,
                        "Nothing was banked: %s is set to 0.00x at your level. "
                            + "Change that on the LEVEL MULTIPLIERS tab.",
                        selectedSkill.getName())
                    : "Nothing was banked. Please try again.",
                "Nothing banked",
                JOptionPane.INFORMATION_MESSAGE
            );
            return;
        }

        xpField.setText("");
        xpField.requestFocusInWindow();
    }

    private void onRemoveXp()
    {
        Skill selectedSkill = (Skill) removeSkillSelector.getSelectedItem();
        if (selectedSkill == null)
        {
            JOptionPane.showMessageDialog(
                this,
                "No skill has banked XP to remove.",
                "Nothing to remove",
                JOptionPane.INFORMATION_MESSAGE
            );
            return;
        }

        long requested = parsePositiveXp(removeXpField.getText());
        if (requested <= 0)
        {
            JOptionPane.showMessageDialog(
                this,
                "Please enter a positive whole number.",
                "Invalid XP amount",
                JOptionPane.WARNING_MESSAGE
            );
            removeXpField.requestFocusInWindow();
            removeXpField.selectAll();
            return;
        }

        long banked = plugin.getBankedXp(selectedSkill);
        if (banked <= 0)
        {
            // The balance drained in-game while this form sat open.
            JOptionPane.showMessageDialog(
                this,
                String.format(Locale.US, "%s has no banked XP left to remove.", selectedSkill.getName()),
                "Nothing to remove",
                JOptionPane.INFORMATION_MESSAGE
            );
            return;
        }

        if (requested > banked)
        {
            JOptionPane.showMessageDialog(
                this,
                String.format(
                    Locale.US,
                    "%s only has %s XP banked. Enter %s or less.",
                    selectedSkill.getName(),
                    QuantityFormatter.formatNumber(banked),
                    QuantityFormatter.formatNumber(banked)),
                "Amount too large",
                JOptionPane.WARNING_MESSAGE
            );
            removeXpField.requestFocusInWindow();
            removeXpField.selectAll();
            return;
        }

        long removed = plugin.removeManualXp(selectedSkill, requested);
        if (removed <= 0)
        {
            JOptionPane.showMessageDialog(
                this,
                String.format(Locale.US, "%s has no banked XP left to remove.", selectedSkill.getName()),
                "Nothing to remove",
                JOptionPane.INFORMATION_MESSAGE
            );
            return;
        }

        removeXpField.setText("");
        removeXpField.requestFocusInWindow();
    }

    /**
     * Parses user-entered XP without relying on formatted-field edit state.
     *
     * <p>Shares the plugin's one number parser, so "1,000" is accepted here just
     * as it is in the action editor, and anything that is not entirely a whole
     * number reads as 0 rather than as its leading digits.</p>
     *
     * @return the amount, or 0 when the text is not a positive whole number
     */
    static long parsePositiveXp(String text)
    {
        OptionalLong parsed = IrlXpUi.parseWholeNumber(text);
        if (parsed.isEmpty() || parsed.getAsLong() <= 0)
        {
            return 0L;
        }
        return parsed.getAsLong();
    }

    /**
     * Gives a text field keyboard focus when it is clicked.
     *
     * <p>RuneLite normally transfers focus automatically, but making it explicit
     * prevents the game canvas from retaining keyboard focus when a sidebar
     * control is clicked.</p>
     */
    private static class FocusOnClick extends MouseAdapter
    {
        private final JTextField field;

        FocusOnClick(JTextField field)
        {
            this.field = field;
        }

        @Override
        public void mousePressed(MouseEvent event)
        {
            field.requestFocusInWindow();
        }
    }

}

package com.gokirlbankedxp;

import com.gokirlbankedxp.service.TimerManager;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

/**
 * The on-screen banked XP and timer summary.
 *
 * <p>Sizing is handled entirely by RuneLite, so this plugin adds no hotkey or
 * config of its own for it. {@link OverlayPanel} already marks itself resizable,
 * and the client's own "Drag hotkey" (ALT by default, rebindable in RuneLite's
 * settings) is what puts overlays into management mode: holding it and dragging
 * an edge resizes this panel, right-clicking resets it, and {@code OverlayManager}
 * persists whatever size the user lands on. All of that only works if
 * {@link #render(Graphics2D)} hands off to {@code super}, which applies the
 * user's chosen size to the panel — see the note there.</p>
 */
class GokIrlBankedXpOverlay extends OverlayPanel
{
    /**
     * Default width before the user resizes anything. Wider than RuneLite's
     * 129px standard because skill rows pair a name with a formatted XP total.
     */
    private static final int DEFAULT_WIDTH = 240;

    /** Floor for user resizing, small enough to tuck away but still readable. */
    private static final int MINIMUM_SIZE = 100;

    private final GokIrlBankedXpPlugin plugin;
    private final TimerManager timerManager;

    @Inject
    private GokIrlBankedXpOverlay(GokIrlBankedXpPlugin plugin, TimerManager timerManager)
    {
        this.plugin = plugin;
        this.timerManager = timerManager;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
        panelComponent.setPreferredSize(new Dimension(DEFAULT_WIDTH, 0));
        setMinimumSize(MINIMUM_SIZE);
        // Scales the font with the panel so a shrunken overlay stays legible and
        // a widened one does not look sparse. This is what keeps the overlay
        // looking right across fixed, resizable, and stretched screen modes.
        setDynamicFont(true);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        GokIrlBankedXpPlugin.BankedXpSnapshot snapshot = plugin.getCurrentSnapshot();
        if (snapshot != null && snapshot.hasData())
        {
            panelComponent.getChildren().add(
                TitleComponent.builder()
                    .text("IRL XP")
                    .color(graphics.getColor())
                    .build()
            );

            panelComponent.getChildren().add(
                LineComponent.builder()
                    .left("Total")
                    .right(QuantityFormatter.formatNumber(snapshot.getTotalXp()))
                    .build()
            );

            for (GokIrlBankedXpPlugin.BankedSkill entry : snapshot.getSkills())
            {
                LineComponent.LineComponentBuilder builder = LineComponent.builder()
                    .left(entry.getDisplayName())
                    .right(QuantityFormatter.formatNumber(entry.getRemainingXp()));

                // Red for a debt (the figure already carries its minus sign),
                // orange for a positive balance that is nearly spent.
                if (entry.isInDebt())
                {
                    builder.leftColor(Color.RED);
                    builder.rightColor(Color.RED);
                }
                else if (entry.isBelowThreshold())
                {
                    builder.leftColor(Color.ORANGE);
                    builder.rightColor(Color.ORANGE);
                }

                panelComponent.getChildren().add(builder.build());
            }
        }

        List<TimerManager.TimerSnapshot> timers = timerManager.getTimerSnapshots();
        if (!timers.isEmpty())
        {
            panelComponent.getChildren().add(
                TitleComponent.builder()
                    .text("Active Timers")
                    .color(graphics.getColor())
                    .build()
            );

            for (TimerManager.TimerSnapshot timer : timers)
            {
                String label = timer.paused()
                    ? String.format("%s (paused)", timer.actionName())
                    : timer.actionName();
                String rates = timer.formatRates();
                String right = rates.isEmpty()
                    ? timer.formatElapsed()
                    : String.format("%s %s", timer.formatElapsed(), rates);

                panelComponent.getChildren().add(
                    LineComponent.builder()
                        .left(label)
                        .right(right)
                        .build()
                );
            }
        }

        // Must go through super, not panelComponent.render(): OverlayPanel.render()
        // is what copies the overlay's user-chosen preferred size onto the panel
        // (and clears the children afterwards). Rendering the panel directly
        // skipped that, which is why the overlay stayed pinned at its default
        // width no matter how it was dragged or which screen mode was in use.
        return super.render(graphics);
    }
}

package com.gokirlbankedxp;

import java.awt.Color;
import java.awt.TrayIcon;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.Range;
import net.runelite.client.config.RequestFocusType;

/**
 * Everything about IRL XP that lives in RuneLite's settings panel.
 *
 * <p>The visible items are grouped into named, self-describing sections so a user
 * looking for a specific behaviour — "stop the screen flashing at me", "warn me
 * sooner" — can find it by reading the section titles instead of scanning a flat
 * list. Each section's description says, in plain language, what the whole group
 * controls; each item's description says what that one setting does and what the
 * value means.</p>
 *
 * <p>Anything the user edits through the sidebar instead (their action library,
 * their banked totals, their level multiplier tiers) is stored here as a hidden
 * item. Hidden items never appear in the settings panel, which keeps the panel
 * limited to things that are actually meant to be edited there.</p>
 */
@ConfigGroup(GokIrlBankedXpConfig.GROUP)
public interface GokIrlBankedXpConfig extends Config
{
    String GROUP = "gokirlbankedxp";

    String LOW_XP_SECTION = "lowXpSection";
    String ALMOST_OUT_SECTION = "almostOutSection";
    String MULTIPLIER_SECTION = "multiplierSection";

    /**
     * The out-of-the-box depletion warning: a red screen flash, plus a chat line.
     *
     * <p>RuneLite's {@link Notification} normally inherits whatever the user set
     * under Settings &gt; Notifications, where screen flashing is off by default.
     * That default would make this feature do nothing visible, so the notification
     * is built with {@code override} set, which tells
     * {@link net.runelite.client.Notifier} to use exactly these settings instead of
     * the global ones. Users still get the full notification editor for this item
     * and can change or disable any part of it.</p>
     *
     * <p>Every field has to be stated explicitly. {@code Notifier} switches on
     * {@code requestFocus} and {@code sound} without a null check, and it returns
     * early when {@code sendWhenFocused} is false and the client has focus — which
     * is exactly when someone training in-game would be looking at the screen.</p>
     */
    static Notification defaultDepletionNotification()
    {
        return Notification.ON
            .withInitialized(true)
            .withOverride(true)
            .withSendWhenFocused(true)
            .withRequestFocus(RequestFocusType.OFF)
            .withSound(NotificationSound.OFF)
            .withTrayIconType(TrayIcon.MessageType.NONE)
            .withGameMessage(true)
            // The same translucent red RuneLite uses for its own flash default, so
            // the warning is unmistakable without blacking out the game.
            .withFlash(FlashNotification.FLASH_TWO_SECONDS)
            .withFlashColor(new Color(255, 0, 0, 70));
    }

    // ------------------------------------------------------------------
    // Section 1 — the plain chat warning at a fixed XP figure
    // ------------------------------------------------------------------

    @ConfigSection(
        name = "Low banked XP warning (chat)",
        description = "A one-off chat message when a skill's banked XP drops below a set amount. "
            + "This is the quiet warning. The red screen flash is in the next section.",
        position = 0
    )
    String lowXpSection = LOW_XP_SECTION;

    @ConfigItem(
        keyName = "chatWarningEnabled",
        name = "Send the chat warning",
        description = "Turn this off to stop the chat message entirely. "
            + "The message is sent once per skill, and only becomes possible again after that skill is topped up.",
        section = LOW_XP_SECTION,
        position = 1
    )
    default boolean chatWarningEnabled()
    {
        return true;
    }

    @ConfigItem(
        keyName = "lowXpThreshold",
        name = "Warn below this much XP",
        description = "The banked XP figure that counts as low. A skill at or under this amount is marked LOW "
            + "in the sidebar and on the overlay, and triggers the chat warning above. Default: 500.",
        section = LOW_XP_SECTION,
        position = 2
    )
    default int lowXpThreshold()
    {
        return 500;
    }

    // ------------------------------------------------------------------
    // Section 2 — the red screen flash as a skill is about to run dry
    // ------------------------------------------------------------------

    @ConfigSection(
        name = "Almost-out warning (red screen flash)",
        description = "Flashes your screen red when a skill is only a few more actions from running out of banked XP. "
            + "Use 'Warn me this many actions early' to change how much notice you get, "
            + "and 'How you are warned' to change the flash colour, add a sound, or switch the flash off.",
        position = 10
    )
    String almostOutSection = ALMOST_OUT_SECTION;

    @Range(min = 0, max = 50)
    @ConfigItem(
        keyName = "depletionWarningActions",
        name = "Warn me this many actions early",
        description = "How much notice you get. One action means one XP drop: a log chopped, a lap run, a hit landed. "
            + "Higher means an earlier warning. Set this to 0 to switch the whole almost-out warning off. Default: 5.",
        section = ALMOST_OUT_SECTION,
        position = 11
    )
    default int depletionWarningActions()
    {
        return 5;
    }

    @ConfigItem(
        keyName = "depletionNotification",
        name = "How you are warned",
        description = "The full notification editor for the almost-out warning. "
            + "Out of the box it flashes the screen red for two seconds and prints a chat line. "
            + "Open it to change the flash colour, add a sound or tray popup, or turn the flash off "
            + "while keeping the chat line.",
        section = ALMOST_OUT_SECTION,
        position = 12
    )
    default Notification depletionNotification()
    {
        return defaultDepletionNotification();
    }

    // ------------------------------------------------------------------
    // Section 3 — level-based banking multipliers
    // ------------------------------------------------------------------

    @ConfigSection(
        name = "Level multipliers",
        description = "Bank more (or less) XP as your in-game levels climb. "
            + "The multipliers themselves are set per skill in the sidebar: "
            + "open the IRL XP sidebar and pick the MULTIPLIERS tab. This switch turns them all on or off at once.",
        position = 20
    )
    String multiplierSection = MULTIPLIER_SECTION;

    @ConfigItem(
        keyName = "levelMultipliersEnabled",
        name = "Use level multipliers",
        description = "When on, XP you bank is multiplied by whatever your level in that skill has earned, "
            + "as set on the sidebar's MULTIPLIERS tab. When off, XP is banked exactly as entered "
            + "and your thresholds are kept for later. Skills you never set a multiplier for are unaffected either way.",
        section = MULTIPLIER_SECTION,
        position = 21
    )
    default boolean levelMultipliersEnabled()
    {
        return true;
    }

    // ------------------------------------------------------------------
    // Hidden storage — edited through the sidebar, never in this panel
    // ------------------------------------------------------------------

    @ConfigItem(
        keyName = "irlActionsJson",
        name = "IRL actions",
